def _build_provider_truth_policy_work_order(
    review_packet: dict,
    approval_gate: dict,
    target_map: dict,
    implementation_checklist: dict,
    simulation_recipe: dict,
    post_approval_watchdog: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "")
    approved = bool((approval_gate or {}).get("policy_change_allowed"))
    frozen = bool((post_approval_watchdog or {}).get("freeze_triggered")) or str((approval_gate or {}).get("approval_state") or "").upper() == "AUTO_FROZEN"
    checklist_ready = str((implementation_checklist or {}).get("status") or "") == "READY_AFTER_APPROVAL"
    if frozen:
        status = "AUTO_FROZEN"
    elif approved and checklist_ready:
        status = "READY_AFTER_APPROVAL"
    else:
        status = "BLOCKED_BY_APPROVAL"
    return {
        "status": status,
        "work_order_key": f"work_order:{review_key}" if review_key else None,
        "review_key": review_key or None,
        "patch_type": (review_packet or {}).get("patch_type"),
        "target_count": int((target_map or {}).get("target_count") or 0),
        "checklist_passed": int((implementation_checklist or {}).get("passed_required") or 0),
        "checklist_total": int((implementation_checklist or {}).get("total_required") or 0),
        "recipe_count": int((simulation_recipe or {}).get("recipe_count") or 0),
        "manual_only": True,
        "auto_apply_enabled": False,
        "implementation_started": False,
        "target_map": target_map,
        "implementation_checklist": implementation_checklist,
        "simulation_test_recipe": simulation_recipe,
        "next_action": (
            "Ready for a separate manual implementation patch and code review."
            if status == "READY_AFTER_APPROVAL"
            else "Work order is frozen by the watchdog; collect fresh evidence before implementation."
            if status == "AUTO_FROZEN"
            else "Work order is prepared but blocked until explicit approval."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_approval_evidence_summary(
    review_packet: dict,
    accumulator_score: dict,
    timeline: dict,
    dry_run_preview: dict,
    now: datetime,
) -> dict:
    evidence = []
    latest_event_by_key: dict[str, dict] = {}
    for event in list((timeline or {}).get("events") or []):
        key = str(event.get("key") or _provider_truth_queue_key(event) or "")
        if not key:
            continue
        prev = latest_event_by_key.get(key)
        if not prev or (_gb_parse_ts(event.get("ts_utc")) or datetime.min.replace(tzinfo=timezone.utc)) > (_gb_parse_ts(prev.get("ts_utc")) or datetime.min.replace(tzinfo=timezone.utc)):
            latest_event_by_key[key] = dict(event)

    for item in list((accumulator_score or {}).get("items") or []):
        item = dict(item)
        key = str(item.get("key") or _provider_truth_queue_key(item) or "")
        event = latest_event_by_key.get(key, {})
        outcome = str(item.get("evidence_outcome") or event.get("evidence_outcome") or "").upper()
        evidence.append({
            "key": key or None,
            "symbol": item.get("symbol") or event.get("symbol"),
            "mint": item.get("mint") or event.get("mint"),
            "evidence_outcome": outcome or None,
            "evidence_source": item.get("evidence_source") or "ACCUMULATED_REVIEW",
            "current_source": item.get("current_source") or event.get("current_source"),
            "source": item.get("source") or event.get("source"),
            "quality": item.get("current_quality") if item.get("current_quality") is not None else event.get("quality"),
            "pressure": item.get("current_pressure") if item.get("current_pressure") is not None else event.get("pressure"),
            "freshness": item.get("current_freshness") or event.get("freshness"),
            "confidence": item.get("current_confidence") or event.get("confidence"),
            "similarity_score": item.get("similarity_score") or event.get("similarity_score"),
            "latest_event_at": event.get("ts_utc"),
            "operator_read": (
                "Supports the patch candidate."
                if outcome == "EVIDENCE_BENEFIT"
                else "Would block the patch if it appeared as risk."
                if outcome == "EVIDENCE_RISK"
                else "Neutral; useful for context but not approval weight."
            ),
        })

    if not evidence:
        for item in list((dry_run_preview or {}).get("items") or [])[:8]:
            item = dict(item)
            evidence.append({
                "key": _provider_truth_queue_key(item) or None,
                "symbol": item.get("symbol"),
                "mint": item.get("mint"),
                "evidence_outcome": item.get("evidence_outcome"),
                "current_source": item.get("current_source"),
                "source": item.get("source"),
                "quality": item.get("quality"),
                "pressure": item.get("pressure"),
                "latest_event_at": None,
                "operator_read": "Dry-run preview item.",
            })

    benefit_items = [item for item in evidence if str(item.get("evidence_outcome") or "").upper() == "EVIDENCE_BENEFIT"]
    risk_items = [item for item in evidence if str(item.get("evidence_outcome") or "").upper() == "EVIDENCE_RISK"]
    neutral_items = [item for item in evidence if str(item.get("evidence_outcome") or "").upper() == "EVIDENCE_NEUTRAL"]
    return {
        "status": "READY" if evidence else "EMPTY",
        "review_key": (review_packet or {}).get("review_key"),
        "evidence_count": len(evidence),
        "benefit_count": len(benefit_items),
        "risk_count": len(risk_items),
        "neutral_count": len(neutral_items),
        "top_items": sorted(evidence, key=lambda x: (_gb_float(x.get("similarity_score")), _gb_float(x.get("quality")), _gb_float(x.get("pressure"))), reverse=True)[:8],
        "next_action": (
            "Review the top evidence examples before approving, holding, or rejecting."
            if evidence
            else "No approval evidence examples are available yet."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_risk_explanation(
    accumulator_score: dict,
    dry_run_preview: dict,
    before_after: dict,
    confidence_curve: dict,
    post_approval_watchdog: dict,
    now: datetime,
) -> dict:
    accumulator_risk = int((accumulator_score or {}).get("risk_count") or 0)
    dry_run_risk = int((dry_run_preview or {}).get("would_risk_count") or 0)
    worsened = int((before_after or {}).get("worsened_count") or 0)
    trend = str((confidence_curve or {}).get("trend") or "").upper()
    confidence = _gb_float((confidence_curve or {}).get("confidence_score"))
    watchdog_freeze = bool((post_approval_watchdog or {}).get("freeze_triggered"))
    risk_zero = bool(accumulator_risk == 0 and dry_run_risk == 0 and worsened == 0 and trend != "WEAKENING" and not watchdog_freeze)
    return {
        "status": "RISK_ZERO" if risk_zero else "RISK_PRESENT",
        "risk_zero": risk_zero,
        "risk_count": accumulator_risk + dry_run_risk,
        "reasons": [
            f"Accumulator risk items: {accumulator_risk}.",
            f"Dry-run would-risk items: {dry_run_risk}.",
            f"Before/after worsened items: {worsened}.",
            f"Confidence curve trend: {trend or 'WAITING'} at {round(confidence, 1)}.",
            f"Watchdog freeze triggered: {bool(watchdog_freeze)}.",
        ],
        "would_become_nonzero_if": [
            "A refreshed evidence item becomes EVIDENCE_RISK.",
            "The dry-run preview marks any candidate WOULD_KEEP_BLOCKED because of patch risk.",
            "Before/after scoring detects a worsened token after the patch idea.",
            "Confidence curve turns WEAKENING or falls below the watchdog floor.",
            "Any approval-state watchdog auto-freeze is triggered.",
        ],
        "next_action": (
            "Risk is currently zero; approval is still manual and implementation remains separate."
            if risk_zero
            else "Risk is nonzero; hold or reject instead of approving implementation."
        ),
        "updated_at": now.isoformat(),
    }


def _provider_truth_risk_causes(item: dict) -> list[str]:
    causes: list[str] = []
    freshness = str(item.get("freshness") or item.get("current_freshness") or "").upper()
    confidence = str(item.get("confidence") or item.get("current_confidence") or "").upper()
    current_source = _provider_source_key(item.get("current_source"))
    source = _provider_truth_learning_source(item.get("source"))
    quality = _gb_float(item.get("quality"), _gb_float(item.get("current_quality")))
    pressure = _gb_float(item.get("pressure"), _gb_float(item.get("current_pressure")))
    trend = str(item.get("confidence_trend") or "").upper()
    direction = str(item.get("direction") or "").upper()
    if freshness == "STALE":
        causes.append("DATA_STALE")
    if confidence == "LOW":
        causes.append("LOW_CONFIDENCE")
    if current_source in {"", "unknown", "cache"} or (
        source
        and current_source
        and current_source != source
        and current_source not in {"unknown", "cache"}
    ):
        causes.append("SOURCE_MISMATCH")
    if quality < 65 or pressure < 35:
        causes.append("WEAK_QUALITY")
    if trend == "WEAKENING" or direction == "WORSENED":
        causes.append("WEAKENING_TREND")
    if not causes:
        causes.append("PATCH_RISK_FLAG")
    return list(dict.fromkeys(causes))


def _build_provider_truth_risk_case_drilldown(
    approval_evidence_summary: dict,
    dry_run_preview: dict,
    before_after: dict,
    confidence_curve: dict,
    now: datetime,
) -> dict:
    cases_by_key: dict[str, dict] = {}
    for item in list((approval_evidence_summary or {}).get("top_items") or []):
        item = dict(item)
        if str(item.get("evidence_outcome") or "").upper() != "EVIDENCE_RISK":
            continue
        key = str(item.get("key") or _provider_truth_queue_key(item) or f"symbol:{str(item.get('symbol') or 'UNKNOWN').upper()}")
        cases_by_key[key] = {
            **item,
            "key": key,
            "risk_source": "ACCUMULATED_EVIDENCE",
            "risk_reason": "Evidence outcome is EVIDENCE_RISK.",
        }

    for item in list((dry_run_preview or {}).get("items") or []):
        item = dict(item)
        if str(item.get("evidence_outcome") or "").upper() != "EVIDENCE_RISK" and str(item.get("simulated_change") or "").upper() != "WOULD_KEEP_BLOCKED":
            continue
        key = str(_provider_truth_queue_key(item) or f"symbol:{str(item.get('symbol') or 'UNKNOWN').upper()}")
        cases_by_key.setdefault(key, {
            **item,
            "key": key,
            "risk_source": "DRY_RUN_PREVIEW",
            "risk_reason": "Dry-run would keep this candidate blocked.",
        })

    for item in list((before_after or {}).get("items") or []):
        item = dict(item)
        if str(item.get("direction") or "").upper() != "WORSENED":
            continue
        key = str(item.get("key") or _provider_truth_queue_key(item) or f"symbol:{str(item.get('symbol') or 'UNKNOWN').upper()}")
        cases_by_key.setdefault(key, {
            **item,
            "key": key,
            "risk_source": "BEFORE_AFTER",
            "risk_reason": "Before/after evidence worsened.",
        })

    if str((confidence_curve or {}).get("trend") or "").upper() == "WEAKENING":
        cases_by_key["curve:WEAKENING"] = {
            "key": "curve:WEAKENING",
            "symbol": "CONFIDENCE_CURVE",
            "risk_source": "CONFIDENCE_CURVE",
            "risk_reason": "Patch confidence curve is weakening.",
            "confidence_trend": (confidence_curve or {}).get("trend"),
            "confidence_score": (confidence_curve or {}).get("confidence_score"),
        }

    cases = list(cases_by_key.values())
    for case in cases:
        case["causes"] = _provider_truth_risk_causes(case)
    cases.sort(key=lambda x: (_gb_float(x.get("similarity_score")), _gb_float(x.get("quality")), _gb_float(x.get("pressure"))), reverse=True)
    return {
        "status": "ACTIVE" if cases else "CLEAR",
        "risk_count": len(cases),
        "items": cases[:20],
        "top_case": cases[0] if cases else None,
        "next_action": (
            "Review the exact risk cases before approval."
            if cases
            else "No concrete risk cases are active."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_risk_cause_classifier(risk_case_drilldown: dict, now: datetime) -> dict:
    counts: dict[str, int] = {}
    items = []
    for case in list((risk_case_drilldown or {}).get("items") or []):
        case = dict(case)
        causes = list(case.get("causes") or _provider_truth_risk_causes(case))
        for cause in causes:
            counts[cause] = counts.get(cause, 0) + 1
        items.append({
            "key": case.get("key"),
            "symbol": case.get("symbol"),
            "mint": case.get("mint"),
            "risk_source": case.get("risk_source"),
            "primary_cause": causes[0] if causes else "PATCH_RISK_FLAG",
            "causes": causes,
            "risk_reason": case.get("risk_reason"),
        })
    ranked = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)
    primary = ranked[0][0] if ranked else None
    return {
        "status": "CLASSIFIED" if items else "CLEAR",
        "risk_count": len(items),
        "primary_cause": primary,
        "cause_counts": counts,
        "items": items[:20],
        "next_action": (
            f"Clear primary risk cause {primary.replace('_', ' ').lower()} before approval."
            if primary
            else "No risk causes are active."
        ),
        "updated_at": now.isoformat(),
    }


def _provider_truth_risk_resolution_definition(cause: str) -> dict:
    cause_key = str(cause or "PATCH_RISK_FLAG").strip().upper() or "PATCH_RISK_FLAG"
    definitions = {
        "SOURCE_MISMATCH": {
            "label": "Source mismatch",
            "clearing_action": "Confirm the preferred current source on fresh live/recent data before loosening provider precedence.",
            "evidence_required": [
                "Current source is not unknown/cache.",
                "Freshness is LIVE or RECENT.",
                "Confidence is not LOW.",
                "Dry-run no longer keeps the row blocked.",
            ],
            "recheck_minutes": 30,
        },
        "WEAK_QUALITY": {
            "label": "Weak quality",
            "clearing_action": "Wait until quality and pressure recover above the provider-truth safety floor.",
            "evidence_required": [
                "Quality is at least 65.",
                "Pressure is at least 35.",
                "Before/after does not worsen.",
            ],
            "recheck_minutes": 60,
        },
        "DATA_STALE": {
            "label": "Stale data",
            "clearing_action": "Refresh the candidate from live/recent market data before reviewing the patch again.",
            "evidence_required": [
                "Freshness is LIVE or RECENT.",
                "Latest evidence timestamp refreshes.",
                "Dry-run risk remains zero after refresh.",
            ],
            "recheck_minutes": 20,
        },
        "LOW_CONFIDENCE": {
            "label": "Low confidence",
            "clearing_action": "Require non-low confidence from the refreshed source before this hold can clear.",
            "evidence_required": [
                "Confidence is MEDIUM or HIGH.",
                "Provider agreement remains stable.",
                "No new risk evidence appears.",
            ],
            "recheck_minutes": 60,
        },
        "WEAKENING_TREND": {
            "label": "Weakening trend",
            "clearing_action": "Let the confidence curve stabilize before returning this packet to operator review.",
            "evidence_required": [
                "Confidence trend is not WEAKENING.",
                "Before/after has zero worsened cases.",
                "Watchdog freeze is not triggered.",
            ],
            "recheck_minutes": 90,
        },
        "PATCH_RISK_FLAG": {
            "label": "Patch risk flag",
            "clearing_action": "Manually inspect the flagged case and require a clean dry-run before review resumes.",
            "evidence_required": [
                "Risk case is absent from the latest drilldown.",
                "Dry-run would-risk count is zero.",
                "Operator can explain why the prior risk no longer applies.",
            ],
            "recheck_minutes": 120,
        },
    }
    return {"cause": cause_key, **definitions.get(cause_key, definitions["PATCH_RISK_FLAG"])}


def _build_provider_truth_risk_resolution_playbook(
    risk_cause_classifier: dict,
    risk_case_drilldown: dict,
    now: datetime,
) -> dict:
    cause_counts = dict((risk_cause_classifier or {}).get("cause_counts") or {})
    if not cause_counts and int((risk_case_drilldown or {}).get("risk_count") or 0) > 0:
        cause_counts = {"PATCH_RISK_FLAG": int((risk_case_drilldown or {}).get("risk_count") or 0)}
    items = []
    for cause, count in sorted(cause_counts.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0]))):
        definition = _provider_truth_risk_resolution_definition(cause)
        items.append({
            **definition,
            "active_count": int(count or 0),
            "status": "ACTIVE" if int(count or 0) > 0 else "CLEAR",
        })
    return {
        "status": "ACTIVE" if items else "CLEAR",
        "playbook_count": len(items),
        "items": items,
        "top_action": (items[0].get("clearing_action") if items else "No risk causes are active."),
        "next_action": (
            "Use the playbook to clear each active risk cause before review resumes."
            if items
            else "No risk resolution playbook is needed."
        ),
        "updated_at": now.isoformat(),
    }


def _risk_recheck_delay_minutes(causes: list[str]) -> int:
    delays = [
        int(_provider_truth_risk_resolution_definition(cause).get("recheck_minutes") or 120)
        for cause in causes
    ]
    return min(delays) if delays else 120


def _build_provider_truth_risk_evidence_recheck_queue(
    review_packet: dict,
    approval_gate: dict,
    risk_case_drilldown: dict,
    risk_resolution_playbook: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    risk_items = [dict(item) for item in list((risk_case_drilldown or {}).get("items") or [])]
    if not review_key:
        return {
            "status": "NO_REVIEW_PACKET",
            "review_key": None,
            "queued_count": 0,
            "due_count": 0,
            "items": [],
            "next_action": "No review packet is available for risk rechecks.",
            "updated_at": now.isoformat(),
        }

    payload = _freshness_kv_read(_PROVIDER_TRUTH_RISK_RECHECK_QUEUE_KEY)
    previous_items = {
        str(item.get("queue_key") or ""): dict(item)
        for item in list((payload or {}).get("items") or [])
        if str(item.get("queue_key") or "")
    }
    active_review_state = str((approval_gate or {}).get("approval_state") or "").upper()
    queued = []
    for item in risk_items:
        risk_key = str(item.get("key") or _provider_truth_queue_key(item) or item.get("symbol") or "risk").strip()
        queue_key = f"{review_key}:{risk_key}"
        previous = previous_items.get(queue_key, {})
        causes = list(item.get("causes") or _provider_truth_risk_causes(item))
        delay = _risk_recheck_delay_minutes(causes)
        previous_due = _gb_parse_ts(previous.get("next_recheck_at"))
        due_now = False
        if previous_due:
            next_recheck = previous_due
        else:
            next_recheck = now + timedelta(minutes=delay)
        if previous_due and previous_due <= now:
            due_now = True
        queued.append({
            "queue_key": queue_key,
            "review_key": review_key,
            "risk_key": risk_key,
            "symbol": item.get("symbol"),
            "mint": item.get("mint"),
            "risk_source": item.get("risk_source"),
            "causes": causes,
            "status": "WAITING_RECHECK",
            "recheck_reason": (risk_resolution_playbook or {}).get("top_action"),
            "last_seen_at": now.isoformat(),
            "next_recheck_at": next_recheck.isoformat(),
            "due": due_now,
            "recheck_minutes": delay,
        })

    old_other_reviews = [
        dict(item) for item in list((payload or {}).get("items") or [])
        if str(item.get("review_key") or "") != review_key
    ][-200:]
    stored = old_other_reviews + queued
    _freshness_kv_write(
        _PROVIDER_TRUTH_RISK_RECHECK_QUEUE_KEY,
        {
            "status": "TRACKING",
            "updated_at": now.isoformat(),
            "items": stored[-300:],
        },
    )
    due_count = len([item for item in queued if item.get("due")])
    next_times = [_gb_parse_ts(item.get("next_recheck_at")) for item in queued]
    next_times = [ts for ts in next_times if ts]
    return {
        "status": "TRACKING" if queued else "CLEAR",
        "review_key": review_key,
        "approval_state": active_review_state or None,
        "queued_count": len(queued),
        "due_count": due_count,
        "next_recheck_at": min(next_times).isoformat() if next_times else None,
        "items": queued[:20],
        "next_action": (
            "Risk evidence rechecks are queued for held cases."
            if queued
            else "No active risk cases need rechecks."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_hold_aging_escalation(
    review_packet: dict,
    approval_gate: dict,
    risk_case_drilldown: dict,
    evidence_recheck_queue: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    approval_state = str((approval_gate or {}).get("approval_state") or "").upper()
    updated_at = _gb_parse_ts((approval_gate or {}).get("state_updated_at"))
    age_hours = round(max(0.0, (now - updated_at).total_seconds() / 3600.0), 2) if updated_at else None
    risk_count = int((risk_case_drilldown or {}).get("risk_count") or 0)
    due_count = int((evidence_recheck_queue or {}).get("due_count") or 0)
    stale = bool(age_hours is not None and age_hours >= 24 and approval_state == "NEEDS_MORE_EVIDENCE")
    escalation = "ESCALATE_MANUAL_REVIEW" if stale and risk_count > 0 else "RECHECK_DUE" if due_count > 0 else "NONE"
    status = "STALE_HOLD" if stale else "ACTIVE_HOLD" if approval_state == "NEEDS_MORE_EVIDENCE" else "CLEAR"
    if stale and risk_count > 0 and review_key:
        audit = _freshness_kv_read(_PROVIDER_TRUTH_MISS_REVIEW_AUDIT_KEY)
        events = list((audit or {}).get("events") or [])
        recent_stale = False
        for event in reversed(events[-80:]):
            if str(event.get("review_key") or "") != review_key:
                continue
            if str(event.get("state") or "").upper() != "STALE_HOLD_ESCALATION":
                continue
            event_ts = _gb_parse_ts(event.get("ts_utc"))
            if event_ts and (now - event_ts).total_seconds() < 6 * 3600:
                recent_stale = True
                break
        if not recent_stale:
            events.append({
                "event_id": f"{review_key}:STALE_HOLD_ESCALATION:{now.isoformat()}",
                "ts_utc": now.isoformat(),
                "review_key": review_key,
                "state": "STALE_HOLD_ESCALATION",
                "risk_count": risk_count,
                "hold_age_hours": age_hours,
                "operator_note": "Hold aged past 24h with active risk cases; manual escalation required.",
                "manual_only": True,
                "policy_auto_apply": False,
            })
            _freshness_kv_write(
                _PROVIDER_TRUTH_MISS_REVIEW_AUDIT_KEY,
                {
                    "status": "TRACKING",
                    "updated_at": now.isoformat(),
                    "event_count": len(events[-500:]),
                    "events": events[-500:],
                },
            )
    return {
        "status": status,
        "review_key": review_key or None,
        "approval_state": approval_state or None,
        "hold_age_hours": age_hours,
        "risk_count": risk_count,
        "due_recheck_count": due_count,
        "escalation": escalation,
        "stale_after_hours": 24,
        "next_action": (
            "Manual review should inspect this stale hold before it remains blocked longer."
            if stale
            else "Run due evidence rechecks for this hold."
            if due_count > 0
            else "Hold is fresh; continue scheduled rechecks."
            if approval_state == "NEEDS_MORE_EVIDENCE"
            else "No active hold aging action is needed."
        ),
        "updated_at": now.isoformat(),
    }


def _apply_provider_truth_clear_to_review_state(
    review_packet: dict,
    approval_gate: dict,
    risk_clear_requirements: dict,
    hold_aging_escalation: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    if not review_key:
        return dict(approval_gate or {})
    packet_ready = str((review_packet or {}).get("status") or "").upper() == "READY_FOR_OPERATOR_REVIEW"
    current_state = str((approval_gate or {}).get("approval_state") or "").upper()
    clear = str((risk_clear_requirements or {}).get("status") or "").upper() == "CLEAR"
    stale = str((hold_aging_escalation or {}).get("status") or "").upper() == "STALE_HOLD"
    if not (packet_ready and clear and current_state == "NEEDS_MORE_EVIDENCE" and not stale):
        out = dict(approval_gate or {})
        out["clear_to_review_applied"] = False
        out["risk_clear_status"] = (risk_clear_requirements or {}).get("status")
        return out

    states = _freshness_kv_read(_PROVIDER_TRUTH_MISS_REVIEW_STATES_KEY)
    previous = dict(states.get(review_key) or {})
    if str(previous.get("state") or "").upper() != "CLEARED_FOR_REVIEW":
        note = "Auto-cleared back to operator review after all risk-clear requirements passed."
        states[review_key] = {
            **previous,
            "state": "CLEARED_FOR_REVIEW",
            "updated_at": now.isoformat(),
            "note": note,
            "auto_cleared": True,
            "risk_count": 0,
        }
        _freshness_kv_write(_PROVIDER_TRUTH_MISS_REVIEW_STATES_KEY, states)
        audit = _freshness_kv_read(_PROVIDER_TRUTH_MISS_REVIEW_AUDIT_KEY)
        events = list((audit or {}).get("events") or [])
        events.append({
            "event_id": f"{review_key}:CLEARED_FOR_REVIEW:{now.isoformat()}",
            "ts_utc": now.isoformat(),
            "review_key": review_key,
            "state": "CLEARED_FOR_REVIEW",
            "packet_status": (review_packet or {}).get("status"),
            "risk_count": 0,
            "operator_note": note,
            "manual_only": True,
            "policy_auto_apply": False,
            "auto_cleared": True,
        })
        _freshness_kv_write(
            _PROVIDER_TRUTH_MISS_REVIEW_AUDIT_KEY,
            {
                "status": "TRACKING",
                "updated_at": now.isoformat(),
                "event_count": len(events[-500:]),
                "events": events[-500:],
            },
        )

    out = dict(approval_gate or {})
    out.update({
        "status": "PENDING",
        "approval_state": "CLEARED_FOR_REVIEW",
        "state_updated_at": now.isoformat(),
        "operator_note": states.get(review_key, {}).get("note"),
        "policy_change_allowed": False,
        "auto_apply_enabled": False,
        "clear_to_review_applied": True,
        "risk_blocked": False,
        "risk_count": 0,
        "risk_clear_status": "CLEAR",
        "next_action": "Risk cleared; packet can return to manual operator review.",
    })
    return out


def _apply_provider_truth_auto_hold_approval_state(
    review_packet: dict,
    approval_gate: dict,
    risk_case_drilldown: dict,
    risk_cause_classifier: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    if not review_key:
        return dict(approval_gate or {})
    risk_count = int((risk_case_drilldown or {}).get("risk_count") or 0)
    if risk_count <= 0:
        out = dict(approval_gate or {})
        out["auto_hold_applied"] = False
        return out

    current_state = str((approval_gate or {}).get("approval_state") or "").upper()
    if current_state in {"REJECTED", "AUTO_FROZEN"}:
        out = dict(approval_gate or {})
        out["auto_hold_applied"] = False
        out["risk_blocked"] = True
        return out

    states = _freshness_kv_read(_PROVIDER_TRUTH_MISS_REVIEW_STATES_KEY)
    previous = dict(states.get(review_key) or {})
    if str(previous.get("state") or "").upper() != "NEEDS_MORE_EVIDENCE":
        note = (
            f"Auto-held by risk drilldown: {risk_count} risk case(s), "
            f"primary cause {(risk_cause_classifier or {}).get('primary_cause') or 'unknown'}."
        )
        states[review_key] = {
            **previous,
            "state": "NEEDS_MORE_EVIDENCE",
            "updated_at": now.isoformat(),
            "note": note,
            "auto_hold": True,
            "risk_count": risk_count,
        }
        _freshness_kv_write(_PROVIDER_TRUTH_MISS_REVIEW_STATES_KEY, states)
        audit = _freshness_kv_read(_PROVIDER_TRUTH_MISS_REVIEW_AUDIT_KEY)
        events = list((audit or {}).get("events") or [])
        events.append({
            "event_id": f"{review_key}:AUTO_HOLD:{now.isoformat()}",
            "ts_utc": now.isoformat(),
            "review_key": review_key,
            "state": "NEEDS_MORE_EVIDENCE",
            "packet_status": (review_packet or {}).get("status"),
            "risk_count": risk_count,
            "primary_risk_cause": (risk_cause_classifier or {}).get("primary_cause"),
            "operator_note": note,
            "manual_only": True,
            "policy_auto_apply": False,
            "auto_hold": True,
        })
        _freshness_kv_write(
            _PROVIDER_TRUTH_MISS_REVIEW_AUDIT_KEY,
            {
                "status": "TRACKING",
                "updated_at": now.isoformat(),
                "event_count": len(events[-500:]),
                "events": events[-500:],
            },
        )

    out = dict(approval_gate or {})
    out.update({
        "status": "PENDING",
        "approval_state": "NEEDS_MORE_EVIDENCE",
        "state_updated_at": now.isoformat(),
        "operator_note": states.get(review_key, {}).get("note"),
        "policy_change_allowed": False,
        "auto_apply_enabled": False,
        "auto_hold_applied": True,
        "risk_blocked": True,
        "risk_count": risk_count,
        "primary_risk_cause": (risk_cause_classifier or {}).get("primary_cause"),
        "next_action": "Approval auto-held because active risk cases exist.",
    })
    return out


def _build_provider_truth_risk_clear_requirements(
    risk_case_drilldown: dict,
    risk_cause_classifier: dict,
    confidence_curve: dict,
    before_after: dict,
    dry_run_preview: dict,
    now: datetime,
) -> dict:
    risk_count = int((risk_case_drilldown or {}).get("risk_count") or 0)
    cause_counts = dict((risk_cause_classifier or {}).get("cause_counts") or {})
    requirements = [
        {
            "key": "risk_cases_clear",
            "label": "All active risk cases clear",
            "passed": risk_count == 0,
            "current": risk_count,
            "required": 0,
        },
        {
            "key": "dry_run_risk_zero",
            "label": "Dry-run would-risk count is zero",
            "passed": int((dry_run_preview or {}).get("would_risk_count") or 0) == 0,
            "current": int((dry_run_preview or {}).get("would_risk_count") or 0),
            "required": 0,
        },
        {
            "key": "no_worsened_before_after",
            "label": "Before/after has no worsened cases",
            "passed": int((before_after or {}).get("worsened_count") or 0) == 0,
            "current": int((before_after or {}).get("worsened_count") or 0),
            "required": 0,
        },
        {
            "key": "confidence_not_weakening",
            "label": "Confidence curve is not weakening",
            "passed": str((confidence_curve or {}).get("trend") or "").upper() != "WEAKENING",
            "current": (confidence_curve or {}).get("trend") or "WAITING",
            "required": "NOT_WEAKENING",
        },
    ]
    for cause, count in sorted(cause_counts.items(), key=lambda kv: kv[0]):
        requirements.append({
            "key": f"cause_clear_{cause.lower()}",
            "label": f"{cause.replace('_', ' ').title()} cases clear",
            "passed": int(count or 0) == 0,
            "current": int(count or 0),
            "required": 0,
        })
    passed = len([item for item in requirements if item.get("passed")])
    total = len(requirements)
    return {
        "status": "CLEAR" if passed == total else "BLOCKED",
        "passed_count": passed,
        "total_count": total,
        "items": requirements,
        "next_action": (
            "Risk is clear; approval can return to normal review if evidence remains strong."
            if passed == total
            else "Clear every risk requirement before this packet can be approvable again."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_approval_consequences(
    review_packet: dict,
    approval_gate: dict,
    policy_work_order: dict,
    now: datetime,
) -> dict:
    review_key = (review_packet or {}).get("review_key")
    packet_status = str((review_packet or {}).get("status") or "").upper()
    can_approve = packet_status == "READY_FOR_OPERATOR_REVIEW"
    items = [
        {
            "state": "APPROVED_FOR_IMPLEMENTATION",
            "label": "Approve",
            "enabled": can_approve,
            "state_change": "approval_state becomes APPROVED_FOR_IMPLEMENTATION",
            "what_happens": "Work order can move to READY_AFTER_APPROVAL if guardrails still pass.",
            "what_does_not_happen": "No provider policy is auto-applied and live buying remains locked.",
        },
        {
            "state": "NEEDS_MORE_EVIDENCE",
            "label": "Hold",
            "enabled": True,
            "state_change": "approval_state becomes NEEDS_MORE_EVIDENCE",
            "what_happens": "Work order remains blocked while evidence continues accumulating.",
            "what_does_not_happen": "No implementation work should start.",
        },
        {
            "state": "REJECTED",
            "label": "Reject",
            "enabled": True,
            "state_change": "approval_state becomes REJECTED",
            "what_happens": "Current packet is closed unless future evidence creates a new review case.",
            "what_does_not_happen": "No patch target is implemented.",
        },
    ]
    return {
        "status": "READY" if review_key else "NO_REVIEW_PACKET",
        "review_key": review_key,
        "current_approval_state": (approval_gate or {}).get("approval_state"),
        "current_work_order_status": (policy_work_order or {}).get("status"),
        "consequence_count": len(items),
        "items": items,
        "next_action": "Read button consequences before recording an approval decision.",
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_decision_audit_trail(review_packet: dict, now: datetime) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    payload = _freshness_kv_read(_PROVIDER_TRUTH_MISS_REVIEW_AUDIT_KEY)
    events = [
        dict(event) for event in list((payload or {}).get("events") or [])
        if not review_key or str(event.get("review_key") or "") == review_key
    ]
    events.sort(key=lambda x: _gb_parse_ts(x.get("ts_utc")) or datetime.min.replace(tzinfo=timezone.utc), reverse=True)
    latest = events[0] if events else {}
    return {
        "status": "TRACKING" if events else "EMPTY",
        "review_key": review_key or None,
        "event_count": len(events),
        "latest_state": latest.get("state"),
        "latest_event_at": latest.get("ts_utc"),
        "events": events[:20],
        "next_action": (
            "Approval decision history is available for audit."
            if events
            else "No approval decisions have been recorded for this review packet."
        ),
        "updated_at": now.isoformat(),
    }


def _provider_truth_hold_outcome_label(
    approval_state: str,
    risk_count: int,
    clear_status: str,
    hold_status: str,
) -> str:
    state = str(approval_state or "").upper()
    clear = str(clear_status or "").upper()
    hold = str(hold_status or "").upper()
    if state == "APPROVED_FOR_IMPLEMENTATION" and risk_count > 0:
        return "UNSAFE_APPROVAL_ATTEMPT"
    if state == "CLEARED_FOR_REVIEW" and risk_count == 0 and clear == "CLEAR":
        return "CLEARED_BACK_TO_REVIEW"
    if state == "APPROVED_FOR_IMPLEMENTATION" and risk_count == 0 and clear == "CLEAR":
        return "APPROVED_AFTER_CLEAR"
    if state == "REJECTED" and risk_count > 0:
        return "RISK_REJECTED"
    if state == "AUTO_FROZEN" and risk_count > 0:
        return "RISK_FROZEN"
    if hold == "STALE_HOLD" and risk_count > 0:
        return "STALE_RISK_HOLD"
    if state == "NEEDS_MORE_EVIDENCE" and risk_count > 0:
        return "ACTIVE_RISK_HOLD"
    if state == "NEEDS_MORE_EVIDENCE" and risk_count == 0 and clear == "CLEAR":
        return "CLEAR_BUT_STILL_HELD"
    return "OBSERVING"


def _build_provider_truth_hold_outcome_journal(
    review_packet: dict,
    approval_gate: dict,
    risk_case_drilldown: dict,
    risk_cause_classifier: dict,
    risk_clear_requirements: dict,
    hold_aging_escalation: dict,
    decision_audit_trail: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    payload = _freshness_kv_read(_PROVIDER_TRUTH_HOLD_OUTCOME_JOURNAL_KEY)
    entries = [dict(item) for item in list((payload or {}).get("entries") or [])]
    if not review_key:
        return {
            "status": "NO_REVIEW_PACKET",
            "review_key": None,
            "entry_count": len(entries),
            "latest_outcome": None,
            "items": entries[-20:],
            "next_action": "No provider-truth review packet is available for outcome journaling.",
            "updated_at": now.isoformat(),
        }

    risk_count = int((risk_case_drilldown or {}).get("risk_count") or 0)
    clear_status = str((risk_clear_requirements or {}).get("status") or "WAITING").upper()
    approval_state = str((approval_gate or {}).get("approval_state") or "PENDING_REVIEW").upper()
    hold_status = str((hold_aging_escalation or {}).get("status") or "CLEAR").upper()
    cause_counts = dict((risk_cause_classifier or {}).get("cause_counts") or {})
    causes = [str(cause).upper() for cause in cause_counts.keys()]
    if not causes:
        previous_for_review = [
            dict(item) for item in entries
            if str(item.get("review_key") or "") == review_key and list(item.get("causes") or [])
        ]
        if previous_for_review:
            causes = [str(cause).upper() for cause in list(previous_for_review[-1].get("causes") or [])]
    latest_audit_state = (decision_audit_trail or {}).get("latest_state")
    outcome = _provider_truth_hold_outcome_label(approval_state, risk_count, clear_status, hold_status)
    signature = "|".join([
        review_key,
        approval_state,
        str(risk_count),
        clear_status,
        hold_status,
        outcome,
        ",".join(sorted(causes)),
    ])
    existing_signatures = {str(item.get("signature") or "") for item in entries}
    if signature not in existing_signatures:
        entry = {
            "journal_key": f"{review_key}:{len(entries) + 1}",
            "signature": signature,
            "ts_utc": now.isoformat(),
            "review_key": review_key,
            "approval_state": approval_state,
            "packet_status": (review_packet or {}).get("status"),
            "risk_count": risk_count,
            "clear_status": clear_status,
            "clear_passed": int((risk_clear_requirements or {}).get("passed_count") or 0),
            "clear_total": int((risk_clear_requirements or {}).get("total_count") or 0),
            "hold_status": hold_status,
            "hold_age_hours": (hold_aging_escalation or {}).get("hold_age_hours"),
            "hold_escalation": (hold_aging_escalation or {}).get("escalation"),
            "causes": causes,
            "primary_cause": (risk_cause_classifier or {}).get("primary_cause") or (causes[0] if causes else None),
            "top_symbol": (dict((risk_case_drilldown or {}).get("top_case") or {})).get("symbol"),
            "latest_audit_state": latest_audit_state,
            "outcome_label": outcome,
            "manual_only": True,
            "policy_auto_apply": False,
        }
        entries.append(entry)
        entries = entries[-500:]
        _freshness_kv_write(
            _PROVIDER_TRUTH_HOLD_OUTCOME_JOURNAL_KEY,
            {
                "status": "TRACKING",
                "updated_at": now.isoformat(),
                "entry_count": len(entries),
                "entries": entries,
            },
        )
    latest = entries[-1] if entries else {}
    review_entries = [
        dict(item) for item in entries
        if str(item.get("review_key") or "") == review_key
    ]
    return {
        "status": "TRACKING" if entries else "EMPTY",
        "review_key": review_key,
        "entry_count": len(entries),
        "review_entry_count": len(review_entries),
        "latest_outcome": latest.get("outcome_label"),
        "latest_state": latest.get("approval_state"),
        "latest_at": latest.get("ts_utc"),
        "items": list(reversed(review_entries[-20:])),
        "all_items": entries[-200:],
        "next_action": (
            "Outcome observations are being journaled for later scoring."
            if entries
            else "No hold/review outcomes have been observed yet."
        ),
        "updated_at": now.isoformat(),
    }


def _provider_truth_source_weight(item: dict, source_index: dict[str, dict] | None = None) -> dict:
    source = _provider_source_key(item.get("current_source") or item.get("source"))
    source_meta = dict((source_index or {}).get(source) or {})
    source_confidence = _gb_float(
        item.get("source_confidence_score"),
        _gb_float(source_meta.get("confidence_score"), 45.0),
    )
    freshness = str(item.get("freshness") or item.get("current_freshness") or "").upper()
    confidence = str(item.get("confidence") or item.get("current_confidence") or "").upper()
    quality = _gb_float(item.get("quality"), _gb_float(item.get("current_quality")))
    pressure = _gb_float(item.get("pressure"), _gb_float(item.get("current_pressure")))
    weight = 35.0 + source_confidence * 0.35
    if freshness == "LIVE":
        weight += 18.0
    elif freshness == "RECENT":
        weight += 9.0
    elif freshness == "STALE":
        weight -= 18.0
    if confidence == "HIGH":
        weight += 10.0
    elif confidence == "LOW":
        weight -= 14.0
    weight += min(14.0, quality * 0.08)
    weight += min(8.0, pressure * 0.05)
    if source.startswith("cache") or source in {"", "unknown"}:
        weight -= 20.0
    weight = round(max(0.0, min(100.0, weight)), 1)
    return {
        "source": source,
        "source_confidence_score": round(source_confidence, 1),
        "freshness": freshness or None,
        "confidence": confidence or None,
        "quality": round(quality, 1),
        "pressure": round(pressure, 1),
        "evidence_weight": weight,
        "weight_band": "HIGH" if weight >= 75 else "MEDIUM" if weight >= 45 else "LOW",
    }


def _build_provider_truth_source_trust_weighting(
    approval_evidence_summary: dict,
    risk_case_drilldown: dict,
    dry_run_preview: dict,
    source_index: dict[str, dict],
    now: datetime,
) -> dict:
    weighted: dict[str, dict] = {}
    for origin, rows in [
        ("APPROVAL_EVIDENCE", list((approval_evidence_summary or {}).get("top_items") or [])),
        ("RISK_CASE", list((risk_case_drilldown or {}).get("items") or [])),
        ("DRY_RUN", list((dry_run_preview or {}).get("items") or [])),
    ]:
        for raw in rows:
            item = dict(raw)
            key = str(item.get("key") or _provider_truth_queue_key(item) or f"{origin}:{item.get('symbol') or item.get('mint') or len(weighted)}")
            weight = _provider_truth_source_weight(item, source_index)
            previous = weighted.get(key)
            merged = {
                "key": key,
                "origin": origin,
                "symbol": item.get("symbol"),
                "mint": item.get("mint"),
                "risk_source": item.get("risk_source"),
                "evidence_outcome": item.get("evidence_outcome"),
                "causes": list(item.get("causes") or _provider_truth_risk_causes(item)),
                **weight,
            }
            if not previous or _gb_float(merged.get("evidence_weight")) > _gb_float(previous.get("evidence_weight")):
                weighted[key] = merged
    items = sorted(weighted.values(), key=lambda x: _gb_float(x.get("evidence_weight")), reverse=True)[:30]
    total_weight = round(sum(_gb_float(item.get("evidence_weight")) for item in items), 1)
    avg_weight = round(total_weight / max(1, len(items)), 1) if items else None
    high_count = len([item for item in items if _gb_float(item.get("evidence_weight")) >= 75])
    low_count = len([item for item in items if _gb_float(item.get("evidence_weight")) < 45])
    return {
        "status": "READY" if items else "EMPTY",
        "item_count": len(items),
        "total_weight": total_weight,
        "avg_weight": avg_weight,
        "high_weight_count": high_count,
        "low_weight_count": low_count,
        "top_source": items[0].get("source") if items else None,
        "top_weight": items[0].get("evidence_weight") if items else None,
        "items": items,
        "next_action": (
            "Use source trust weights to judge evidence strength before tuning thresholds."
            if items
            else "No provider-truth evidence is available for source weighting yet."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_cause_accuracy_scoring(hold_outcome_journal: dict, now: datetime) -> dict:
    rows = [dict(item) for item in list((hold_outcome_journal or {}).get("all_items") or (hold_outcome_journal or {}).get("items") or [])]
    by_cause: dict[str, dict] = {}
    protective_labels = {"ACTIVE_RISK_HOLD", "STALE_RISK_HOLD", "RISK_REJECTED", "RISK_FROZEN"}
    cleared_labels = {"CLEARED_BACK_TO_REVIEW", "APPROVED_AFTER_CLEAR", "CLEAR_BUT_STILL_HELD"}
    unsafe_labels = {"UNSAFE_APPROVAL_ATTEMPT"}
    for row in rows:
        causes = [str(cause).upper() for cause in list(row.get("causes") or [])]
        if not causes:
            causes = ["UNCLASSIFIED"]
        outcome = str(row.get("outcome_label") or "").upper()
        for cause in causes:
            bucket = by_cause.setdefault(cause, {
                "cause": cause,
                "observed_count": 0,
                "protective_count": 0,
                "cleared_count": 0,
                "unsafe_count": 0,
            })
            bucket["observed_count"] += 1
            if outcome in protective_labels:
                bucket["protective_count"] += 1
            if outcome in cleared_labels:
                bucket["cleared_count"] += 1
            if outcome in unsafe_labels:
                bucket["unsafe_count"] += 1
    items = []
    for bucket in by_cause.values():
        observed = max(1, int(bucket.get("observed_count") or 0))
        protective = int(bucket.get("protective_count") or 0)
        unsafe = int(bucket.get("unsafe_count") or 0)
        score = round(max(0.0, min(100.0, ((protective - unsafe) / observed) * 100.0)), 1)
        items.append({
            **bucket,
            "accuracy_score": score,
            "read": (
                "protective"
                if score >= 60
                else "noisy"
                if score <= 20 and observed >= 3
                else "building_sample"
            ),
        })
    items.sort(key=lambda x: (_gb_float(x.get("accuracy_score")), int(x.get("observed_count") or 0)), reverse=True)
    return {
        "status": "SCORING" if items else "NO_SAMPLE",
        "cause_count": len(items),
        "sample_n": len(rows),
        "top_cause": (items[0].get("cause") if items else None),
        "top_score": (items[0].get("accuracy_score") if items else None),
        "items": items[:20],
        "next_action": (
            "Use cause scores as evidence, not automatic policy changes."
            if items
            else "Keep collecting hold outcomes before scoring causes."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_outcome_weighted_cause_scores(
    hold_outcome_journal: dict,
    source_trust_weighting: dict,
    now: datetime,
) -> dict:
    rows = [dict(item) for item in list((hold_outcome_journal or {}).get("all_items") or (hold_outcome_journal or {}).get("items") or [])]
    evidence_items = list((source_trust_weighting or {}).get("items") or [])
    cause_weight_hint: dict[str, float] = {}
    for item in evidence_items:
        weight = _gb_float(item.get("evidence_weight"))
        for cause in list(item.get("causes") or []):
            key = str(cause or "UNCLASSIFIED").upper()
            cause_weight_hint[key] = max(cause_weight_hint.get(key, 0.0), weight)
    protective_labels = {"ACTIVE_RISK_HOLD", "STALE_RISK_HOLD", "RISK_REJECTED", "RISK_FROZEN"}
    cleared_labels = {"CLEARED_BACK_TO_REVIEW", "APPROVED_AFTER_CLEAR", "CLEAR_BUT_STILL_HELD"}
    unsafe_labels = {"UNSAFE_APPROVAL_ATTEMPT"}
    buckets: dict[str, dict] = {}
    for row in rows:
        causes = [str(cause).upper() for cause in list(row.get("causes") or [])] or ["UNCLASSIFIED"]
        outcome = str(row.get("outcome_label") or "").upper()
        risk_count = max(1, int(row.get("risk_count") or 0))
        base_impact = 1.0 + min(3.0, risk_count * 0.5)
        if outcome in unsafe_labels:
            outcome_mult = -2.0
        elif outcome in protective_labels:
            outcome_mult = 1.25
        elif outcome in cleared_labels:
            outcome_mult = 0.35
        else:
            outcome_mult = 0.15
        for cause in causes:
            evidence_weight = cause_weight_hint.get(cause, 50.0)
            weighted_value = round(base_impact * outcome_mult * (evidence_weight / 50.0), 3)
            bucket = buckets.setdefault(cause, {
                "cause": cause,
                "observed_count": 0,
                "weighted_signal": 0.0,
                "weighted_abs_signal": 0.0,
                "max_evidence_weight": 0.0,
            })
            bucket["observed_count"] += 1
            bucket["weighted_signal"] = round(_gb_float(bucket.get("weighted_signal")) + weighted_value, 3)
            bucket["weighted_abs_signal"] = round(_gb_float(bucket.get("weighted_abs_signal")) + abs(weighted_value), 3)
            bucket["max_evidence_weight"] = max(_gb_float(bucket.get("max_evidence_weight")), evidence_weight)
    items = []
    for bucket in buckets.values():
        denom = max(0.001, _gb_float(bucket.get("weighted_abs_signal")))
        weighted_score = round(max(0.0, min(100.0, ((_gb_float(bucket.get("weighted_signal")) / denom) + 1.0) * 50.0)), 1)
        items.append({
            **bucket,
            "weighted_score": weighted_score,
            "read": (
                "strong_protective"
                if weighted_score >= 75
                else "mixed"
                if weighted_score >= 40
                else "risk_of_noise"
            ),
        })
    items.sort(key=lambda x: (_gb_float(x.get("weighted_score")), _gb_float(x.get("max_evidence_weight"))), reverse=True)
    return {
        "status": "SCORING" if items else "NO_SAMPLE",
        "sample_n": len(rows),
        "cause_count": len(items),
        "top_cause": items[0].get("cause") if items else None,
        "top_weighted_score": items[0].get("weighted_score") if items else None,
        "items": items[:20],
        "next_action": (
            "Use weighted cause scores to prioritize manual threshold review."
            if items
            else "Keep collecting outcomes and weighted evidence before scoring causes."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_clear_requirement_backtest(
    hold_outcome_journal: dict,
    risk_clear_requirements: dict,
    now: datetime,
) -> dict:
    rows = [dict(item) for item in list((hold_outcome_journal or {}).get("all_items") or (hold_outcome_journal or {}).get("items") or [])]
    release_rows = [
        row for row in rows
        if str(row.get("clear_status") or "").upper() == "CLEAR"
        and int(row.get("risk_count") or 0) == 0
    ]
    blocked_rows = [
        row for row in rows
        if str(row.get("clear_status") or "").upper() == "BLOCKED"
        or int(row.get("risk_count") or 0) > 0
    ]
    stale_block_rows = [
        row for row in blocked_rows
        if str(row.get("hold_status") or "").upper() == "STALE_HOLD"
    ]
    unsafe_release_rows = [
        row for row in release_rows
        if str(row.get("outcome_label") or "").upper() == "UNSAFE_APPROVAL_ATTEMPT"
    ]
    total = len(rows)
    current_passed = int((risk_clear_requirements or {}).get("passed_count") or 0)
    current_total = int((risk_clear_requirements or {}).get("total_count") or 0)
    if unsafe_release_rows:
        verdict = "TOO_LOOSE"
    elif stale_block_rows:
        verdict = "POSSIBLY_TOO_STRICT"
    elif release_rows or blocked_rows:
        verdict = "BALANCED_SO_FAR"
    else:
        verdict = "NO_SAMPLE"
    return {
        "status": verdict,
        "sample_n": total,
        "would_release_count": len(release_rows),
        "would_block_count": len(blocked_rows),
        "stale_block_count": len(stale_block_rows),
        "unsafe_release_count": len(unsafe_release_rows),
        "current_passed": current_passed,
        "current_total": current_total,
        "items": [
            {
                "name": "release_when_clear",
                "passed": len(unsafe_release_rows) == 0,
                "value": len(release_rows),
                "risk": len(unsafe_release_rows),
            },
            {
                "name": "block_when_risk_present",
                "passed": len(blocked_rows) >= len(unsafe_release_rows),
                "value": len(blocked_rows),
                "risk": len(stale_block_rows),
            },
            {
                "name": "current_clear_progress",
                "passed": current_passed == current_total and current_total > 0,
                "value": f"{current_passed}/{current_total}" if current_total else "0/0",
                "risk": 0 if current_passed == current_total and current_total > 0 else current_total - current_passed,
            },
        ],
        "next_action": (
            "Tighten clear requirements before any release."
            if unsafe_release_rows
            else "Check whether stale blocks need faster rechecks or clearer evidence thresholds."
            if stale_block_rows
            else "Backtest is acceptable so far; keep collecting outcomes."
            if total
            else "No outcomes exist yet for clear-rule backtesting."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_weighted_clear_requirements(
    risk_clear_requirements: dict,
    risk_case_drilldown: dict,
    source_trust_weighting: dict,
    now: datetime,
) -> dict:
    risk_items = list((risk_case_drilldown or {}).get("items") or [])
    weight_by_key = {
        str(item.get("key") or ""): _gb_float(item.get("evidence_weight"))
        for item in list((source_trust_weighting or {}).get("items") or [])
        if str(item.get("key") or "")
    }
    high_risk_weight = 0.0
    medium_risk_weight = 0.0
    low_risk_weight = 0.0
    weighted_cases = []
    for raw in risk_items:
        item = dict(raw)
        key = str(item.get("key") or _provider_truth_queue_key(item) or item.get("symbol") or "")
        weight = weight_by_key.get(key)
        if weight is None:
            weight = _gb_float(_provider_truth_source_weight(item).get("evidence_weight"))
        if weight >= 75:
            high_risk_weight += weight
        elif weight >= 45:
            medium_risk_weight += weight
        else:
            low_risk_weight += weight
        weighted_cases.append({
            "key": key,
            "symbol": item.get("symbol"),
            "risk_source": item.get("risk_source"),
            "evidence_weight": round(weight, 1),
            "weight_band": "HIGH" if weight >= 75 else "MEDIUM" if weight >= 45 else "LOW",
        })
    high_risk_weight = round(high_risk_weight, 1)
    medium_risk_weight = round(medium_risk_weight, 1)
    low_risk_weight = round(low_risk_weight, 1)
    base_clear = str((risk_clear_requirements or {}).get("status") or "").upper() == "CLEAR"
    weighted_clear = bool(base_clear and high_risk_weight == 0 and medium_risk_weight <= 0)
    status = "CLEAR" if weighted_clear else "HIGH_WEIGHT_BLOCKED" if high_risk_weight > 0 else "MEDIUM_WEIGHT_BLOCKED" if medium_risk_weight > 0 else "BASE_REQUIREMENTS_BLOCKED"
    return {
        "status": status,
        "weighted_clear": weighted_clear,
        "case_count": len(weighted_cases),
        "high_risk_weight": high_risk_weight,
        "medium_risk_weight": medium_risk_weight,
        "low_risk_weight": low_risk_weight,
        "base_clear_status": (risk_clear_requirements or {}).get("status"),
        "items": sorted(weighted_cases, key=lambda x: _gb_float(x.get("evidence_weight")), reverse=True)[:20],
        "next_action": (
            "High-weight risk remains; do not clear this packet."
            if high_risk_weight > 0
            else "Medium-weight risk remains; continue evidence review."
            if medium_risk_weight > 0
            else "Only low-weight or no weighted risk remains; base clear rules still control manual review."
            if not weighted_clear
            else "Weighted risk is clear; packet may return to manual review if base rules are also clear."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_policy_tuning_suggestions(
    cause_accuracy_scoring: dict,
    clear_requirement_backtest: dict,
    now: datetime,
) -> dict:
    suggestions = []
    for item in list((cause_accuracy_scoring or {}).get("items") or []):
        cause = str(item.get("cause") or "UNCLASSIFIED").upper()
        observed = int(item.get("observed_count") or 0)
        score = _gb_float(item.get("accuracy_score"))
        if observed < 3:
            suggestions.append({
                "suggestion": f"COLLECT_MORE_{cause}",
                "cause": cause,
                "priority": "LOW",
                "manual_only": True,
                "auto_apply": False,
                "reason": f"{cause} has only {observed} scored observation(s).",
            })
        elif score >= 70:
            suggestions.append({
                "suggestion": f"KEEP_STRICT_{cause}",
                "cause": cause,
                "priority": "MEDIUM",
                "manual_only": True,
                "auto_apply": False,
                "reason": f"{cause} is acting as a useful protective signal.",
            })
        elif score <= 20:
            suggestions.append({
                "suggestion": f"REVIEW_NOISY_{cause}",
                "cause": cause,
                "priority": "MEDIUM",
                "manual_only": True,
                "auto_apply": False,
                "reason": f"{cause} may be too noisy; inspect before changing thresholds.",
            })
    backtest_status = str((clear_requirement_backtest or {}).get("status") or "").upper()
    if backtest_status == "TOO_LOOSE":
        suggestions.insert(0, {
            "suggestion": "TIGHTEN_CLEAR_REQUIREMENTS",
            "cause": None,
            "priority": "HIGH",
            "manual_only": True,
            "auto_apply": False,
            "reason": "Backtest found a release with unresolved risk.",
        })
    elif backtest_status == "POSSIBLY_TOO_STRICT":
        suggestions.insert(0, {
            "suggestion": "REVIEW_STALE_HOLD_THRESHOLDS",
            "cause": None,
            "priority": "MEDIUM",
            "manual_only": True,
            "auto_apply": False,
            "reason": "Backtest found stale blocked holds; consider faster rechecks, not auto-approval.",
        })
    if not suggestions:
        suggestions.append({
            "suggestion": "KEEP_COLLECTING_OUTCOMES",
            "cause": None,
            "priority": "LOW",
            "manual_only": True,
            "auto_apply": False,
            "reason": "Not enough outcome evidence exists for policy tuning.",
        })
    return {
        "status": "READY" if suggestions else "EMPTY",
        "suggestion_count": len(suggestions),
        "top_suggestion": suggestions[0].get("suggestion") if suggestions else None,
        "items": suggestions[:12],
        "manual_only": True,
        "auto_apply_enabled": False,
        "next_action": "Review suggestions manually; no policy tuning is auto-applied.",
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_weighted_threshold_suggestions(
    source_trust_weighting: dict,
    outcome_weighted_cause_scores: dict,
    weighted_clear_requirements: dict,
    now: datetime,
) -> dict:
    suggestions = []
    high_weight = _gb_float((weighted_clear_requirements or {}).get("high_risk_weight"))
    medium_weight = _gb_float((weighted_clear_requirements or {}).get("medium_risk_weight"))
    low_count = int((source_trust_weighting or {}).get("low_weight_count") or 0)
    avg_weight = _gb_float((source_trust_weighting or {}).get("avg_weight"))
    if high_weight > 0:
        suggestions.append({
            "suggestion": "KEEP_HIGH_WEIGHT_RISK_BLOCK",
            "priority": "HIGH",
            "threshold_area": "risk_clear",
            "manual_only": True,
            "auto_apply": False,
            "reason": f"High-weight unresolved risk totals {round(high_weight, 1)}.",
        })
    elif medium_weight > 0:
        suggestions.append({
            "suggestion": "REVIEW_MEDIUM_WEIGHT_RISK_CLEARANCE",
            "priority": "MEDIUM",
            "threshold_area": "risk_clear",
            "manual_only": True,
            "auto_apply": False,
            "reason": f"Medium-weight unresolved risk totals {round(medium_weight, 1)}.",
        })
    for item in list((outcome_weighted_cause_scores or {}).get("items") or [])[:4]:
        cause = str(item.get("cause") or "UNCLASSIFIED").upper()
        score = _gb_float(item.get("weighted_score"))
        observed = int(item.get("observed_count") or 0)
        if observed < 3:
            suggestions.append({
                "suggestion": f"COLLECT_MORE_WEIGHTED_{cause}",
                "priority": "LOW",
                "threshold_area": "cause_weight",
                "manual_only": True,
                "auto_apply": False,
                "reason": f"{cause} has {observed} weighted observation(s).",
            })
        elif score >= 75:
            suggestions.append({
                "suggestion": f"RAISE_TRUST_IN_{cause}",
                "priority": "MEDIUM",
                "threshold_area": "cause_weight",
                "manual_only": True,
                "auto_apply": False,
                "reason": f"{cause} has strong weighted protective score {round(score, 1)}.",
            })
        elif score < 40:
            suggestions.append({
                "suggestion": f"REVIEW_WEIGHT_NOISE_{cause}",
                "priority": "MEDIUM",
                "threshold_area": "cause_weight",
                "manual_only": True,
                "auto_apply": False,
                "reason": f"{cause} has weak weighted score {round(score, 1)}.",
            })
    if avg_weight and avg_weight < 45 and low_count:
        suggestions.append({
            "suggestion": "LOW_TRUST_EVIDENCE_SAMPLE",
            "priority": "LOW",
            "threshold_area": "source_trust",
            "manual_only": True,
            "auto_apply": False,
            "reason": f"Average provider-truth evidence weight is {round(avg_weight, 1)} with {low_count} low-weight rows.",
        })
    if not suggestions:
        suggestions.append({
            "suggestion": "KEEP_WEIGHTING_OBSERVATIONAL",
            "priority": "LOW",
            "threshold_area": "source_trust",
            "manual_only": True,
            "auto_apply": False,
            "reason": "Weighted evidence has no threshold change to suggest yet.",
        })
    return {
        "status": "READY",
        "suggestion_count": len(suggestions),
        "top_suggestion": suggestions[0].get("suggestion"),
        "items": suggestions[:12],
        "manual_only": True,
        "auto_apply_enabled": False,
        "next_action": "Review weighted threshold suggestions manually; no auto-apply is enabled.",
        "updated_at": now.isoformat(),
    }


def _provider_truth_disagreement_outcome(item: dict) -> str:
    outcome = str(item.get("evidence_outcome") or "").upper()
    simulated = str(item.get("simulated_change") or "").upper()
    risk_source = str(item.get("risk_source") or "").upper()
    if outcome == "EVIDENCE_RISK" or simulated == "WOULD_KEEP_BLOCKED" or risk_source:
        return "RISK"
    if outcome == "EVIDENCE_BENEFIT" or simulated == "WOULD_SEND_TO_MANUAL_SECOND_SOURCE_REVIEW":
        return "BENEFIT"
    return "NEUTRAL"


def _provider_truth_disagreement_cluster_key(item: dict) -> str:
    mint = str(item.get("mint") or "").strip()
    symbol = str(item.get("symbol") or "").strip().upper()
    if mint:
        return f"mint:{mint}"
    if symbol:
        return f"symbol:{symbol}"
    return str(item.get("key") or _provider_truth_queue_key(item) or "unknown")


def _build_provider_truth_disagreement_cluster_detector(
    approval_evidence_summary: dict,
    risk_case_drilldown: dict,
    dry_run_preview: dict,
    source_index: dict[str, dict],
    now: datetime,
) -> dict:
    rows = []
    for origin, source_rows in [
        ("APPROVAL_EVIDENCE", list((approval_evidence_summary or {}).get("top_items") or [])),
        ("RISK_CASE", list((risk_case_drilldown or {}).get("items") or [])),
        ("DRY_RUN", list((dry_run_preview or {}).get("items") or [])),
    ]:
        for raw in source_rows:
            item = dict(raw)
            weight = _provider_truth_source_weight(item, source_index)
            rows.append({
                "cluster_key": _provider_truth_disagreement_cluster_key(item),
                "symbol": item.get("symbol"),
                "mint": item.get("mint"),
                "source": weight.get("source"),
                "origin": origin,
                "outcome": _provider_truth_disagreement_outcome(item),
                "evidence_weight": weight.get("evidence_weight"),
                "weight_band": weight.get("weight_band"),
                "freshness": weight.get("freshness"),
                "confidence": weight.get("confidence"),
                "risk_source": item.get("risk_source"),
                "causes": list(item.get("causes") or _provider_truth_risk_causes(item)),
            })
    clusters: dict[str, dict] = {}
    for row in rows:
        key = str(row.get("cluster_key") or "unknown")
        cluster = clusters.setdefault(key, {
            "cluster_key": key,
            "symbol": row.get("symbol"),
            "mint": row.get("mint"),
            "sources": set(),
            "outcome_weights": {"RISK": 0.0, "BENEFIT": 0.0, "NEUTRAL": 0.0},
            "items": [],
        })
        if row.get("source"):
            cluster["sources"].add(row.get("source"))
        outcome = str(row.get("outcome") or "NEUTRAL").upper()
        cluster["outcome_weights"][outcome] = round(_gb_float(cluster["outcome_weights"].get(outcome)) + _gb_float(row.get("evidence_weight")), 1)
        cluster["items"].append(row)

    out = []
    for cluster in clusters.values():
        weights = dict(cluster.get("outcome_weights") or {})
        risk_weight = _gb_float(weights.get("RISK"))
        benefit_weight = _gb_float(weights.get("BENEFIT"))
        neutral_weight = _gb_float(weights.get("NEUTRAL"))
        source_count = len(cluster.get("sources") or [])
        high_conflict = bool(risk_weight >= 75 and benefit_weight >= 45)
        medium_conflict = bool(risk_weight >= 75 and neutral_weight >= 75 and source_count >= 2)
        source_split = bool(source_count >= 2 and risk_weight > 0 and (benefit_weight > 0 or neutral_weight > 0))
        if not (high_conflict or medium_conflict or source_split):
            continue
        sorted_items = sorted(list(cluster.get("items") or []), key=lambda x: _gb_float(x.get("evidence_weight")), reverse=True)
        out.append({
            "cluster_key": cluster.get("cluster_key"),
            "symbol": cluster.get("symbol"),
            "mint": cluster.get("mint"),
            "source_count": source_count,
            "sources": sorted(str(src) for src in cluster.get("sources") or []),
            "risk_weight": round(risk_weight, 1),
            "benefit_weight": round(benefit_weight, 1),
            "neutral_weight": round(neutral_weight, 1),
            "conflict_type": "RISK_VS_BENEFIT" if high_conflict else "RISK_VS_NEUTRAL" if medium_conflict else "SOURCE_SPLIT",
            "severity": "HIGH" if high_conflict else "MEDIUM",
            "items": sorted_items[:8],
            "top_source": sorted_items[0].get("source") if sorted_items else None,
            "top_weight": sorted_items[0].get("evidence_weight") if sorted_items else None,
        })
    out.sort(key=lambda x: (_gb_float(x.get("risk_weight")) + _gb_float(x.get("benefit_weight")), _gb_float(x.get("top_weight"))), reverse=True)
    return {
        "status": "CONFLICTS" if out else "NO_CONFLICTS",
        "cluster_count": len(out),
        "high_severity_count": len([item for item in out if str(item.get("severity") or "").upper() == "HIGH"]),
        "top_cluster": out[0] if out else None,
        "items": out[:20],
        "next_action": (
            "Run arbitration on high-weight provider disagreements."
            if out
            else "No high-weight provider disagreement is active."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_arbitration_decision_matrix(disagreement_clusters: dict, now: datetime) -> dict:
    rows = []
    for cluster in list((disagreement_clusters or {}).get("items") or []):
        risk_weight = _gb_float(cluster.get("risk_weight"))
        benefit_weight = _gb_float(cluster.get("benefit_weight"))
        neutral_weight = _gb_float(cluster.get("neutral_weight"))
        if risk_weight >= 75 and benefit_weight >= 45:
            decision = "REQUIRE_THIRD_SOURCE"
            safe_action = "KEEP_BLOCKED_PENDING_THIRD_SOURCE"
            reason = "High-weight risk and benefit evidence conflict."
        elif risk_weight >= 75:
            decision = "KEEP_BLOCKED"
            safe_action = "KEEP_BLOCKED"
            reason = "High-weight risk dominates the disagreement."
        elif benefit_weight >= 75 and risk_weight < 45:
            decision = "TRUST_BENEFIT_WITH_MANUAL_REVIEW"
            safe_action = "MANUAL_REVIEW_ONLY"
            reason = "Benefit evidence dominates, but approval remains manual."
        elif neutral_weight >= 75:
            decision = "REQUIRE_THIRD_SOURCE"
            safe_action = "KEEP_WATCHING"
            reason = "Neutral/high-weight evidence conflicts with active risk."
        else:
            decision = "KEEP_WATCHING"
            safe_action = "KEEP_WATCHING"
            reason = "Conflict weight is not strong enough to change state."
        rows.append({
            "cluster_key": cluster.get("cluster_key"),
            "symbol": cluster.get("symbol"),
            "mint": cluster.get("mint"),
            "conflict_type": cluster.get("conflict_type"),
            "severity": cluster.get("severity"),
            "risk_weight": risk_weight,
            "benefit_weight": benefit_weight,
            "neutral_weight": neutral_weight,
            "decision": decision,
            "safe_action": safe_action,
            "reason": reason,
            "manual_only": True,
            "auto_apply": False,
        })
    require_third = len([row for row in rows if row.get("decision") == "REQUIRE_THIRD_SOURCE"])
    blocked = len([row for row in rows if str(row.get("safe_action") or "").startswith("KEEP_BLOCKED")])
    return {
        "status": "READY" if rows else "NO_CONFLICTS",
        "decision_count": len(rows),
        "require_third_source_count": require_third,
        "blocked_count": blocked,
        "top_decision": rows[0] if rows else None,
        "items": rows[:20],
        "next_action": (
            "Queue third-source checks for unresolved high-weight disagreements."
            if require_third
            else "Keep blocked disagreements blocked; no third-source check is required."
            if blocked
            else "No arbitration action is required."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_third_source_confirmation_queue(
    review_packet: dict,
    arbitration_matrix: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    payload = _freshness_kv_read(_PROVIDER_TRUTH_THIRD_SOURCE_QUEUE_KEY)
    previous_items = {
        str(item.get("queue_key") or ""): dict(item)
        for item in list((payload or {}).get("items") or [])
        if str(item.get("queue_key") or "")
    }
    queued = []
    for row in list((arbitration_matrix or {}).get("items") or []):
        if str(row.get("decision") or "").upper() != "REQUIRE_THIRD_SOURCE":
            continue
        cluster_key = str(row.get("cluster_key") or row.get("symbol") or row.get("mint") or "cluster")
        queue_key = f"{review_key or 'no-review'}:{cluster_key}:THIRD_SOURCE"
        previous = previous_items.get(queue_key, {})
        previous_due = _gb_parse_ts(previous.get("next_check_at"))
        due_now = bool(previous_due and previous_due <= now)
        next_check = previous_due if previous_due else now + timedelta(minutes=30)
        queued.append({
            "queue_key": queue_key,
            "review_key": review_key or None,
            "cluster_key": cluster_key,
            "symbol": row.get("symbol"),
            "mint": row.get("mint"),
            "status": "DUE" if due_now else "WAITING_THIRD_SOURCE",
            "route": "THIRD_SOURCE_CONFIRMATION",
            "risk_weight": row.get("risk_weight"),
            "benefit_weight": row.get("benefit_weight"),
            "reason": row.get("reason"),
            "last_seen_at": now.isoformat(),
            "next_check_at": next_check.isoformat(),
            "due": due_now,
            "manual_only": True,
            "auto_apply": False,
        })
    old_other_reviews = [
        dict(item) for item in list((payload or {}).get("items") or [])
        if str(item.get("review_key") or "") != review_key
    ][-200:]
    stored = old_other_reviews + queued
    _freshness_kv_write(
        _PROVIDER_TRUTH_THIRD_SOURCE_QUEUE_KEY,
        {
            "status": "TRACKING",
            "updated_at": now.isoformat(),
            "items": stored[-300:],
        },
    )
    due_count = len([item for item in queued if item.get("due")])
    return {
        "status": "TRACKING" if queued else "EMPTY",
        "review_key": review_key or None,
        "queued_count": len(queued),
        "due_count": due_count,
        "next_check_at": min([item.get("next_check_at") for item in queued], default=None),
        "items": queued[:20],
        "next_action": (
            "Third-source confirmation is queued for high-weight disagreements."
            if queued
            else "No third-source confirmation is needed."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_manual_arbitration_packet(
    review_packet: dict,
    disagreement_clusters: dict,
    arbitration_matrix: dict,
    third_source_queue: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip()
    top_decision = dict((arbitration_matrix or {}).get("top_decision") or {})
    status = "READY_FOR_OPERATOR_REVIEW" if int((disagreement_clusters or {}).get("cluster_count") or 0) else "NO_DISAGREEMENT"
    packet = {
        "status": status,
        "review_key": review_key or None,
        "cluster_count": int((disagreement_clusters or {}).get("cluster_count") or 0),
        "decision_count": int((arbitration_matrix or {}).get("decision_count") or 0),
        "third_source_queued_count": int((third_source_queue or {}).get("queued_count") or 0),
        "top_symbol": top_decision.get("symbol"),
        "top_decision": top_decision.get("decision"),
        "top_safe_action": top_decision.get("safe_action"),
        "operator_summary": (
            f"{top_decision.get('symbol') or 'Top disagreement'}: {top_decision.get('decision')} because {top_decision.get('reason')}"
            if top_decision
            else "No active high-weight provider disagreement."
        ),
        "manual_only": True,
        "auto_apply_enabled": False,
        "items": list((arbitration_matrix or {}).get("items") or [])[:8],
        "next_action": (
            "Review disagreement packet before changing source trust or clearing any hold."
            if status == "READY_FOR_OPERATOR_REVIEW"
            else "No manual arbitration packet is needed."
        ),
        "updated_at": now.isoformat(),
    }
    return packet


def _provider_truth_current_candidates_for_cluster(cluster_key: str, intelligence_rows: list[dict]) -> list[dict]:
    raw = str(cluster_key or "").strip()
    mint = raw[5:] if raw.startswith("mint:") else ""
    symbol = raw[7:].upper() if raw.startswith("symbol:") else ""
    rows = []
    for row in list(intelligence_rows or []):
        row_mint = str(row.get("mint") or "").strip()
        row_symbol = str(row.get("symbol") or "").strip().upper()
        if mint and row_mint != mint:
            continue
        if symbol and row_symbol != symbol:
            continue
        rows.append(dict(row))
    rows.sort(key=lambda x: _gb_parse_ts(x.get("updated_at")) or datetime.min.replace(tzinfo=timezone.utc), reverse=True)
    return rows[:8]


def _run_provider_truth_third_source_queue_consumer(
    third_source_queue: dict,
    disagreement_clusters: dict,
    intelligence_rows: list[dict],
    source_index: dict[str, dict],
    now: datetime,
) -> dict:
    payload = _freshness_kv_read(_PROVIDER_TRUTH_THIRD_SOURCE_RESULTS_KEY)
    events = list((payload or {}).get("events") or [])
    due_items = [dict(item) for item in list((third_source_queue or {}).get("items") or []) if item.get("due")]
    if not due_items:
        return {
            "status": "WAITING",
            "ran": False,
            "due_count": int((third_source_queue or {}).get("due_count") or 0),
            "checked_count": 0,
            "events": events[-20:],
            "next_action": "No third-source confirmation check is due yet.",
            "updated_at": now.isoformat(),
        }

    clusters = {
        str(item.get("cluster_key") or ""): dict(item)
        for item in list((disagreement_clusters or {}).get("items") or [])
        if str(item.get("cluster_key") or "")
    }
    new_events = []
    for item in due_items[:8]:
        queue_key = str(item.get("queue_key") or "")
        recent = [
            dict(event) for event in events[-120:]
            if str(event.get("queue_key") or "") == queue_key
            and (_gb_parse_ts(event.get("checked_at")) and (now - _gb_parse_ts(event.get("checked_at"))).total_seconds() < 20 * 60)
        ]
        if recent:
            continue
        cluster_key = str(item.get("cluster_key") or "")
        cluster = clusters.get(cluster_key, {})
        existing_sources = {str(src).lower() for src in list(cluster.get("sources") or [])}
        candidates = _provider_truth_current_candidates_for_cluster(cluster_key, intelligence_rows)
        third_source_row = {}
        for row in candidates:
            source = _provider_source_key(row.get("market_source"))
            if source and source not in existing_sources and source not in {"unknown", "cache"}:
                third_source_row = row
                break
        if third_source_row:
            weight = _provider_truth_source_weight(
                {
                    "current_source": third_source_row.get("market_source"),
                    "current_freshness": third_source_row.get("data_freshness"),
                    "current_confidence": third_source_row.get("data_confidence"),
                    "current_quality": third_source_row.get("quality_score"),
                    "current_pressure": third_source_row.get("pressure_score"),
                },
                source_index,
            )
            quality = _gb_float(third_source_row.get("quality_score"))
            pressure = _gb_float(third_source_row.get("pressure_score"))
            freshness = str(third_source_row.get("data_freshness") or "").upper()
            confidence = str(third_source_row.get("data_confidence") or "").upper()
            if freshness in {"LIVE", "RECENT"} and confidence != "LOW" and quality >= 65 and pressure >= 35:
                observed = "BENEFIT"
            elif freshness == "STALE" or confidence == "LOW" or quality < 65:
                observed = "RISK"
            else:
                observed = "NEUTRAL"
            event = {
                "event_id": f"{queue_key}:{now.isoformat()}",
                "queue_key": queue_key,
                "review_key": item.get("review_key"),
                "cluster_key": cluster_key,
                "symbol": item.get("symbol") or third_source_row.get("symbol"),
                "mint": item.get("mint") or third_source_row.get("mint"),
                "checked_at": now.isoformat(),
                "status": "CHECKED",
                "third_source": weight.get("source"),
                "observed_outcome": observed,
                "evidence_weight": weight.get("evidence_weight"),
                "freshness": freshness,
                "confidence": confidence,
                "quality": round(quality, 1),
                "pressure": round(pressure, 1),
                "manual_only": True,
                "auto_apply": False,
            }
        else:
            event = {
                "event_id": f"{queue_key}:{now.isoformat()}",
                "queue_key": queue_key,
                "review_key": item.get("review_key"),
                "cluster_key": cluster_key,
                "symbol": item.get("symbol"),
                "mint": item.get("mint"),
                "checked_at": now.isoformat(),
                "status": "NO_THIRD_SOURCE_DATA",
                "third_source": None,
                "observed_outcome": "NO_DATA",
                "evidence_weight": 0.0,
                "manual_only": True,
                "auto_apply": False,
            }
        events.append(event)
        new_events.append(event)
    events = events[-500:]
    _freshness_kv_write(
        _PROVIDER_TRUTH_THIRD_SOURCE_RESULTS_KEY,
        {
            "status": "TRACKING",
            "updated_at": now.isoformat(),
            "event_count": len(events),
            "events": events,
        },
    )
    return {
        "status": "RAN" if new_events else "RECENTLY_CHECKED",
        "ran": bool(new_events),
        "due_count": len(due_items),
        "checked_count": len(new_events),
        "events": list(reversed(new_events or events[-20:])),
        "next_action": (
            "Classify third-source confirmation results."
            if new_events
            else "Third-source checks were recently recorded; wait before retrying."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_resolution_outcome_classifier(
    arbitration_matrix: dict,
    third_source_consumer: dict,
    now: datetime,
) -> dict:
    events_by_cluster: dict[str, dict] = {}
    for event in list((third_source_consumer or {}).get("events") or []):
        cluster_key = str(event.get("cluster_key") or "")
        if cluster_key and cluster_key not in events_by_cluster:
            events_by_cluster[cluster_key] = dict(event)
    items = []
    for row in list((arbitration_matrix or {}).get("items") or []):
        cluster_key = str(row.get("cluster_key") or "")
        event = events_by_cluster.get(cluster_key, {})
        observed = str(event.get("observed_outcome") or "").upper()
        risk_weight = _gb_float(row.get("risk_weight"))
        benefit_weight = _gb_float(row.get("benefit_weight"))
        evidence_weight = _gb_float(event.get("evidence_weight"))
        if not event:
            outcome = "PENDING_THIRD_SOURCE" if str(row.get("decision") or "").upper() == "REQUIRE_THIRD_SOURCE" else "NOT_REQUIRED"
        elif observed == "NO_DATA":
            outcome = "NO_DATA"
        elif observed == "RISK":
            outcome = "CONFIRMED_RISK"
        elif observed == "BENEFIT" and evidence_weight >= 75 and benefit_weight >= risk_weight:
            outcome = "CONFIRMED_BENEFIT"
        elif observed == "BENEFIT":
            outcome = "STILL_CONFLICTED"
        elif observed == "NEUTRAL":
            outcome = "STILL_CONFLICTED"
        else:
            outcome = "NO_DATA"
        items.append({
            "cluster_key": cluster_key,
            "symbol": row.get("symbol"),
            "mint": row.get("mint"),
            "decision": row.get("decision"),
            "observed_outcome": observed or None,
            "resolution_outcome": outcome,
            "third_source": event.get("third_source"),
            "evidence_weight": event.get("evidence_weight"),
            "manual_only": True,
            "auto_apply": False,
        })
    counts: dict[str, int] = {}
    for item in items:
        key = str(item.get("resolution_outcome") or "UNKNOWN")
        counts[key] = counts.get(key, 0) + 1
    status = "RESOLVED" if any(k in counts for k in ("CONFIRMED_RISK", "CONFIRMED_BENEFIT")) else "PENDING" if items else "NO_CONFLICTS"
    return {
        "status": status,
        "item_count": len(items),
        "counts": counts,
        "top_outcome": items[0].get("resolution_outcome") if items else None,
        "items": items[:20],
        "next_action": (
            "Feed third-source resolution outcomes back into arbitration state."
            if items
            else "No arbitration outcome needs classification."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_arbitration_state_update(
    arbitration_matrix: dict,
    resolution_classifier: dict,
    now: datetime,
) -> dict:
    resolution_by_cluster = {
        str(item.get("cluster_key") or ""): dict(item)
        for item in list((resolution_classifier or {}).get("items") or [])
        if str(item.get("cluster_key") or "")
    }
    items = []
    for row in list((arbitration_matrix or {}).get("items") or []):
        cluster_key = str(row.get("cluster_key") or "")
        resolution = resolution_by_cluster.get(cluster_key, {})
        outcome = str(resolution.get("resolution_outcome") or "PENDING_THIRD_SOURCE").upper()
        if outcome == "CONFIRMED_RISK":
            state = "RESOLVED_KEEP_BLOCKED"
            safe_action = "KEEP_BLOCKED"
        elif outcome == "CONFIRMED_BENEFIT":
            state = "RESOLVED_MANUAL_REVIEW_ONLY"
            safe_action = "MANUAL_REVIEW_ONLY"
        elif outcome == "NO_DATA":
            state = "UNRESOLVED_NO_DATA"
            safe_action = "KEEP_BLOCKED_PENDING_DATA"
        elif outcome == "STILL_CONFLICTED":
            state = "UNRESOLVED_STILL_CONFLICTED"
            safe_action = "KEEP_BLOCKED_PENDING_THIRD_SOURCE"
        elif outcome == "NOT_REQUIRED":
            state = "NO_UPDATE_REQUIRED"
            safe_action = row.get("safe_action")
        else:
            state = "PENDING_THIRD_SOURCE"
            safe_action = row.get("safe_action")
        items.append({
            **dict(row),
            "resolution_outcome": outcome,
            "arbitration_state": state,
            "safe_action": safe_action,
            "manual_only": True,
            "auto_apply": False,
        })
    resolved = len([item for item in items if str(item.get("arbitration_state") or "").startswith("RESOLVED")])
    unresolved = len([item for item in items if str(item.get("arbitration_state") or "").startswith("UNRESOLVED") or item.get("arbitration_state") == "PENDING_THIRD_SOURCE"])
    return {
        "status": "UPDATED" if items else "NO_CONFLICTS",
        "resolved_count": resolved,
        "unresolved_count": unresolved,
        "items": items[:20],
        "top_state": items[0].get("arbitration_state") if items else None,
        "next_action": (
            "Review updated arbitration state before any manual decision."
            if items
            else "No arbitration state update is needed."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_operator_resolution_packet(
    manual_arbitration_packet: dict,
    third_source_consumer: dict,
    resolution_classifier: dict,
    arbitration_state_update: dict,
    now: datetime,
) -> dict:
    top_item = (list((arbitration_state_update or {}).get("items") or []) or [{}])[0]
    status = "READY_FOR_OPERATOR_REVIEW" if top_item else "NO_RESOLUTION"
    top_event = (list((third_source_consumer or {}).get("events") or []) or [{}])[0]
    return {
        "status": status,
        "review_key": (manual_arbitration_packet or {}).get("review_key"),
        "resolution_status": (resolution_classifier or {}).get("status"),
        "arbitration_state": top_item.get("arbitration_state"),
        "safe_action": top_item.get("safe_action"),
        "third_source": top_event.get("third_source"),
        "third_source_status": top_event.get("status"),
        "observed_outcome": top_event.get("observed_outcome"),
        "summary": (
            f"{top_item.get('symbol') or 'Provider disagreement'}: {top_item.get('arbitration_state')} / {top_item.get('safe_action')}"
            if top_item
            else "No third-source resolution is available yet."
        ),
        "manual_only": True,
        "auto_apply_enabled": False,
        "items": list((arbitration_state_update or {}).get("items") or [])[:8],
        "next_action": (
            "Operator can review the third-source resolution packet; live execution remains locked."
            if top_item
            else "Wait for a due third-source check before operator resolution review."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_third_source_sla_watchdog(
    third_source_queue: dict,
    third_source_consumer: dict,
    arbitration_state_update: dict,
    now: datetime,
) -> dict:
    items = [dict(item) for item in list((third_source_queue or {}).get("items") or [])]
    due_items = []
    overdue_items = []
    oldest_age_minutes = None
    for item in items:
        next_check_at = _gb_parse_ts(item.get("next_check_at"))
        last_seen_at = _gb_parse_ts(item.get("last_seen_at"))
        age_minutes = None
        if last_seen_at:
            age_minutes = max(0.0, (now - last_seen_at).total_seconds() / 60.0)
            oldest_age_minutes = age_minutes if oldest_age_minutes is None else max(oldest_age_minutes, age_minutes)
        is_due = bool(item.get("due")) or bool(next_check_at and next_check_at <= now)
        is_overdue = bool(next_check_at and next_check_at <= now - timedelta(minutes=60))
        row = {
            **item,
            "age_minutes": round(age_minutes, 1) if age_minutes is not None else None,
            "due": is_due,
            "overdue": is_overdue,
        }
        if is_due:
            due_items.append(row)
        if is_overdue:
            overdue_items.append(row)
    unresolved_count = int((arbitration_state_update or {}).get("unresolved_count") or 0)
    checked_count = int((third_source_consumer or {}).get("checked_count") or 0)
    if not items:
        status = "CLEAR"
    elif overdue_items:
        status = "OVERDUE"
    elif due_items:
        status = "DUE"
    else:
        status = "WAITING"
    return {
        "status": status,
        "queued_count": len(items),
        "due_count": len(due_items),
        "overdue_count": len(overdue_items),
        "checked_count": checked_count,
        "unresolved_count": unresolved_count,
        "oldest_age_minutes": round(oldest_age_minutes, 1) if oldest_age_minutes is not None else None,
        "next_check_at": min([str(item.get("next_check_at") or "") for item in items if item.get("next_check_at")], default=None),
        "manual_only": True,
        "auto_apply": False,
        "items": (overdue_items or due_items or items)[:12],
        "next_action": (
            "Escalate stale third-source checks before clearing any provider truth hold."
            if overdue_items
            else "Run the due third-source confirmation check."
            if due_items
            else "Third-source confirmation is queued and still inside the SLA window."
            if items
            else "No third-source SLA is active."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_resolution_escalation_rules(
    sla_watchdog: dict,
    resolution_classifier: dict,
    arbitration_state_update: dict,
    now: datetime,
) -> dict:
    sla_status = str((sla_watchdog or {}).get("status") or "").upper()
    overdue = int((sla_watchdog or {}).get("overdue_count") or 0)
    rules = []
    for item in list((resolution_classifier or {}).get("items") or []):
        row = dict(item)
        outcome = str(row.get("resolution_outcome") or "").upper()
        if outcome == "CONFIRMED_RISK":
            rule = "KEEP_BLOCKED_CONFIRMED_RISK"
            action = "REJECT_PACKET"
            severity = "HIGH"
            reason = "Third-source evidence confirmed the risk side of the disagreement."
        elif outcome == "CONFIRMED_BENEFIT":
            rule = "RETURN_TO_MANUAL_REVIEW"
            action = "RETURN_TO_MANUAL_REVIEW"
            severity = "MEDIUM"
            reason = "Third-source evidence supports benefit, but approval remains manual."
        elif outcome == "STILL_CONFLICTED":
            rule = "MANUAL_CA_REVIEW"
            action = "REQUEST_CA_CHECK"
            severity = "MEDIUM"
            reason = "Third-source evidence did not resolve the provider disagreement."
        elif outcome == "NO_DATA" and overdue:
            rule = "NO_DATA_ESCALATE_CA_REVIEW"
            action = "REQUEST_CA_CHECK"
            severity = "HIGH"
            reason = "Third-source data is missing and the SLA is overdue."
        elif outcome == "NO_DATA":
            rule = "NO_DATA_KEEP_HOLD"
            action = "KEEP_HOLD"
            severity = "MEDIUM"
            reason = "Third-source data is missing; keep the hold until manually reviewed."
        elif outcome == "PENDING_THIRD_SOURCE" and overdue:
            rule = "STALE_UNRESOLVED"
            action = "REQUEST_CA_CHECK"
            severity = "HIGH"
            reason = "Third-source confirmation is stale and unresolved."
        elif outcome == "PENDING_THIRD_SOURCE":
            rule = "AWAIT_THIRD_SOURCE"
            action = "KEEP_WATCHING"
            severity = "LOW"
            reason = "Third-source confirmation is still within the wait window."
        else:
            continue
        rules.append({
            "cluster_key": row.get("cluster_key"),
            "symbol": row.get("symbol"),
            "mint": row.get("mint"),
            "resolution_outcome": outcome,
            "rule": rule,
            "recommended_action": action,
            "severity": severity,
            "reason": reason,
            "manual_only": True,
            "auto_apply": False,
        })
    if not rules and int((arbitration_state_update or {}).get("unresolved_count") or 0) and sla_status == "OVERDUE":
        rules.append({
            "cluster_key": None,
            "symbol": None,
            "mint": None,
            "resolution_outcome": "UNRESOLVED",
            "rule": "STALE_UNRESOLVED",
            "recommended_action": "REQUEST_CA_CHECK",
            "severity": "HIGH",
            "reason": "Arbitration is unresolved and third-source SLA is overdue.",
            "manual_only": True,
            "auto_apply": False,
        })
    top = rules[0] if rules else {}
    status = (
        "ESCALATE"
        if any(str(rule.get("severity") or "").upper() == "HIGH" for rule in rules)
        else "WAITING"
        if rules
        else "CLEAR"
    )
    return {
        "status": status,
        "rule_count": len(rules),
        "top_rule": top.get("rule"),
        "top_action": top.get("recommended_action"),
        "manual_only": True,
        "auto_apply": False,
        "items": rules[:12],
        "next_action": (
            "Operator review is required before changing any provider truth hold."
            if status == "ESCALATE"
            else "Keep watching the third-source queue."
            if status == "WAITING"
            else "No resolution escalation is active."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_operator_action_inbox(
    review_packet: dict,
    operator_resolution_packet: dict,
    sla_watchdog: dict,
    escalation_rules: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip() or None
    actions = []
    for rule in list((escalation_rules or {}).get("items") or []):
        top_action = str(rule.get("recommended_action") or "KEEP_WATCHING").upper()
        allowed = ["KEEP_HOLD", "KEEP_WATCHING"]
        if top_action == "REQUEST_CA_CHECK":
            allowed = ["REQUEST_CA_CHECK", "KEEP_HOLD"]
        elif top_action == "REJECT_PACKET":
            allowed = ["REJECT_PACKET", "KEEP_HOLD"]
        elif top_action == "RETURN_TO_MANUAL_REVIEW":
            allowed = ["RETURN_TO_MANUAL_REVIEW", "KEEP_HOLD"]
        actions.append({
            "action_key": f"{review_key or 'no-review'}:{rule.get('cluster_key') or rule.get('symbol') or len(actions)}:{top_action}",
            "review_key": review_key,
            "symbol": rule.get("symbol"),
            "mint": rule.get("mint"),
            "recommended_action": top_action,
            "allowed_actions": allowed,
            "severity": rule.get("severity"),
            "reason": rule.get("reason"),
            "source": "RESOLUTION_ESCALATION_RULES",
            "manual_only": True,
            "auto_apply": False,
        })
    if not actions and str((operator_resolution_packet or {}).get("status") or "").upper() == "READY_FOR_OPERATOR_REVIEW":
        safe_action = str((operator_resolution_packet or {}).get("safe_action") or "KEEP_WATCHING").upper()
        actions.append({
            "action_key": f"{review_key or 'no-review'}:operator-resolution:{safe_action}",
            "review_key": review_key,
            "symbol": None,
            "mint": None,
            "recommended_action": safe_action if safe_action else "KEEP_WATCHING",
            "allowed_actions": ["KEEP_WATCHING", "KEEP_HOLD"],
            "severity": "LOW",
            "reason": (operator_resolution_packet or {}).get("summary") or "Operator packet is ready for review.",
            "source": "OPERATOR_RESOLUTION_PACKET",
            "manual_only": True,
            "auto_apply": False,
        })
    top = actions[0] if actions else {}
    status = "OPEN" if actions else "EMPTY"
    return {
        "status": status,
        "review_key": review_key,
        "action_count": len(actions),
        "top_action": top.get("recommended_action"),
        "sla_status": (sla_watchdog or {}).get("status"),
        "manual_only": True,
        "auto_apply": False,
        "items": actions[:12],
        "next_action": (
            "Operator inbox has manual actions to review; live execution stays locked."
            if actions
            else "No operator action is required."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_decision_closeout_journal(
    review_packet: dict,
    operator_action_inbox: dict,
    decision_audit_trail: dict,
    resolution_classifier: dict,
    now: datetime,
) -> dict:
    review_key = str((review_packet or {}).get("review_key") or "").strip() or None
    payload = _freshness_kv_read(_PROVIDER_TRUTH_DECISION_CLOSEOUT_JOURNAL_KEY)
    entries = [dict(entry) for entry in list((payload or {}).get("entries") or [])]
    inbox_status = str((operator_action_inbox or {}).get("status") or "EMPTY").upper()
    action_count = int((operator_action_inbox or {}).get("action_count") or 0)
    latest_audit_state = (decision_audit_trail or {}).get("latest_state")
    top_outcome = (resolution_classifier or {}).get("top_outcome") or (resolution_classifier or {}).get("status")
    top_action = (operator_action_inbox or {}).get("top_action")
    closeout_label = (
        "OPEN_ACTION_REQUIRED"
        if action_count
        else "AUDIT_DECISION_RECORDED"
        if latest_audit_state
        else "OBSERVING"
    )
    signature = "|".join([
        str(review_key or "no-review"),
        str(latest_audit_state or "no-audit"),
        str(top_outcome or "no-resolution"),
        str(top_action or "no-action"),
        inbox_status,
        str(action_count),
    ])
    if (action_count or latest_audit_state) and signature not in {str(entry.get("signature") or "") for entry in entries[-300:]}:
        entries.append({
            "entry_id": f"{review_key or 'no-review'}:{now.isoformat()}",
            "signature": signature,
            "review_key": review_key,
            "closeout": closeout_label,
            "inbox_status": inbox_status,
            "action_count": action_count,
            "top_action": top_action,
            "latest_audit_state": latest_audit_state,
            "resolution_outcome": top_outcome,
            "manual_only": True,
            "auto_apply": False,
            "created_at": now.isoformat(),
        })
        entries = entries[-500:]
        _freshness_kv_write(
            _PROVIDER_TRUTH_DECISION_CLOSEOUT_JOURNAL_KEY,
            {
                "status": "TRACKING",
                "updated_at": now.isoformat(),
                "entries": entries,
            },
        )
    review_entries = [
        dict(entry) for entry in entries
        if not review_key or str(entry.get("review_key") or "") == review_key
    ]
    review_entries.sort(key=lambda x: _gb_parse_ts(x.get("created_at")) or datetime.min.replace(tzinfo=timezone.utc), reverse=True)
    latest = review_entries[0] if review_entries else {}
    return {
        "status": "TRACKING" if review_entries else "EMPTY",
        "review_key": review_key,
        "entry_count": len(entries),
        "review_entry_count": len(review_entries),
        "latest_closeout": latest.get("closeout"),
        "latest_action": latest.get("top_action"),
        "manual_only": True,
        "auto_apply": False,
        "items": review_entries[:20],
        "next_action": (
            "Use closeout history to judge whether operator waits, blocks, and clears were correct."
            if review_entries
            else "No closeout entry is recorded for this review yet."
        ),
        "updated_at": now.isoformat(),
    }


def _build_provider_truth_miss_evidence_accumulator(
    miss_review: dict,
    miss_repair_workbench: dict,
    learning_score: dict,
    truth_memory: dict,
    intelligence_rows: list[dict],
    source_index: dict[str, dict] | None,
    now: datetime,
) -> dict:
    matcher = _build_provider_truth_miss_similarity_matcher(miss_review, truth_memory, intelligence_rows, now)
    queue = _build_provider_truth_miss_evidence_queue(matcher, now)
    refresh = _run_provider_truth_due_evidence_refresh(queue, intelligence_rows, now)
    queue_after_refresh = dict(refresh.get("queue") or queue)
    score = _build_provider_truth_miss_accumulator_score(
        miss_repair_workbench,
        matcher,
        queue_after_refresh,
        refresh,
        learning_score,
        now,
    )
    timeline = _build_provider_truth_miss_evidence_timeline(matcher, queue_after_refresh, refresh, now)
    before_after = _build_provider_truth_before_after_score(timeline, now)
    confidence_curve = _build_provider_truth_patch_confidence_curve(score, timeline, before_after, now)
    review_packet = _build_provider_truth_manual_review_packet(
        miss_review,
        miss_repair_workbench,
        score,
        timeline,
        before_after,
        confidence_curve,
        now,
    )
    approval_gate = _build_provider_truth_approval_gate(review_packet, now)
    dry_run_preview = _build_provider_truth_dry_run_policy_preview(review_packet, approval_gate, score, matcher, now)
    approval_evidence_summary = _build_provider_truth_approval_evidence_summary(
        review_packet,
        score,
        timeline,
        dry_run_preview,
        now,
    )
    risk_case_drilldown = _build_provider_truth_risk_case_drilldown(
        approval_evidence_summary,
        dry_run_preview,
        before_after,
        confidence_curve,
        now,
    )
    source_trust_weighting = _build_provider_truth_source_trust_weighting(
        approval_evidence_summary,
        risk_case_drilldown,
        dry_run_preview,
        source_index or {},
        now,
    )
    risk_cause_classifier = _build_provider_truth_risk_cause_classifier(risk_case_drilldown, now)
    risk_resolution_playbook = _build_provider_truth_risk_resolution_playbook(
        risk_cause_classifier,
        risk_case_drilldown,
        now,
    )
    risk_explanation = _build_provider_truth_risk_explanation(
        score,
        dry_run_preview,
        before_after,
        confidence_curve,
        {},
        now,
    )
    approval_gate = _apply_provider_truth_auto_hold_approval_state(
        review_packet,
        approval_gate,
        risk_case_drilldown,
        risk_cause_classifier,
        now,
    )
    dry_run_preview = _build_provider_truth_dry_run_policy_preview(review_packet, approval_gate, score, matcher, now)
    post_approval_watchdog = _build_provider_truth_post_approval_watchdog(
        review_packet,
        approval_gate,
        dry_run_preview,
        score,
        before_after,
        confidence_curve,
        now,
    )
    risk_explanation = _build_provider_truth_risk_explanation(
        score,
        dry_run_preview,
        before_after,
        confidence_curve,
        post_approval_watchdog,
        now,
    )
    risk_clear_requirements = _build_provider_truth_risk_clear_requirements(
        risk_case_drilldown,
        risk_cause_classifier,
        confidence_curve,
        before_after,
        dry_run_preview,
        now,
    )
    weighted_clear_requirements = _build_provider_truth_weighted_clear_requirements(
        risk_clear_requirements,
        risk_case_drilldown,
        source_trust_weighting,
        now,
    )
    evidence_recheck_queue = _build_provider_truth_risk_evidence_recheck_queue(
        review_packet,
        approval_gate,
        risk_case_drilldown,
        risk_resolution_playbook,
        now,
    )
    hold_aging_escalation = _build_provider_truth_hold_aging_escalation(
        review_packet,
        approval_gate,
        risk_case_drilldown,
        evidence_recheck_queue,
        now,
    )
    approval_gate = _apply_provider_truth_clear_to_review_state(
        review_packet,
        approval_gate,
        risk_clear_requirements,
        hold_aging_escalation,
        now,
    )
    if approval_gate.get("clear_to_review_applied"):
        dry_run_preview = _build_provider_truth_dry_run_policy_preview(review_packet, approval_gate, score, matcher, now)
        post_approval_watchdog = _build_provider_truth_post_approval_watchdog(
            review_packet,
            approval_gate,
            dry_run_preview,
            score,
            before_after,
            confidence_curve,
            now,
        )
        risk_explanation = _build_provider_truth_risk_explanation(
            score,
            dry_run_preview,
            before_after,
            confidence_curve,
            post_approval_watchdog,
            now,
        )
    patch_target_map = _build_provider_truth_patch_target_map(review_packet, approval_gate, now)
    implementation_checklist = _build_provider_truth_implementation_checklist(
        review_packet,
        approval_gate,
        patch_target_map,
        dry_run_preview,
        post_approval_watchdog,
        now,
    )
    simulation_recipe = _build_provider_truth_simulation_test_recipe(
        review_packet,
        patch_target_map,
        implementation_checklist,
        now,
    )
    policy_work_order = _build_provider_truth_policy_work_order(
        review_packet,
        approval_gate,
        patch_target_map,
        implementation_checklist,
        simulation_recipe,
        post_approval_watchdog,
        now,
    )
    approval_consequences = _build_provider_truth_approval_consequences(
        review_packet,
        approval_gate,
        policy_work_order,
        now,
    )
    decision_audit_trail = _build_provider_truth_decision_audit_trail(review_packet, now)
    hold_outcome_journal = _build_provider_truth_hold_outcome_journal(
        review_packet,
        approval_gate,
        risk_case_drilldown,
        risk_cause_classifier,
        risk_clear_requirements,
        hold_aging_escalation,
        decision_audit_trail,
        now,
    )
    cause_accuracy_scoring = _build_provider_truth_cause_accuracy_scoring(hold_outcome_journal, now)
    outcome_weighted_cause_scores = _build_provider_truth_outcome_weighted_cause_scores(
        hold_outcome_journal,
        source_trust_weighting,
        now,
    )
    clear_requirement_backtest = _build_provider_truth_clear_requirement_backtest(
        hold_outcome_journal,
        risk_clear_requirements,
        now,
    )
    policy_tuning_suggestions = _build_provider_truth_policy_tuning_suggestions(
        cause_accuracy_scoring,
        clear_requirement_backtest,
        now,
    )
    weighted_threshold_suggestions = _build_provider_truth_weighted_threshold_suggestions(
        source_trust_weighting,
        outcome_weighted_cause_scores,
        weighted_clear_requirements,
        now,
    )
    disagreement_clusters = _build_provider_truth_disagreement_cluster_detector(
        approval_evidence_summary,
        risk_case_drilldown,
        dry_run_preview,
        source_index or {},
        now,
    )
    arbitration_matrix = _build_provider_truth_arbitration_decision_matrix(disagreement_clusters, now)
    third_source_queue = _build_provider_truth_third_source_confirmation_queue(
        review_packet,
        arbitration_matrix,
        now,
    )
    manual_arbitration_packet = _build_provider_truth_manual_arbitration_packet(
        review_packet,
        disagreement_clusters,
        arbitration_matrix,
        third_source_queue,
        now,
    )
    third_source_consumer = _run_provider_truth_third_source_queue_consumer(
        third_source_queue,
        disagreement_clusters,
        intelligence_rows,
        source_index or {},
        now,
    )
    resolution_classifier = _build_provider_truth_resolution_outcome_classifier(
        arbitration_matrix,
        third_source_consumer,
        now,
    )
    arbitration_state_update = _build_provider_truth_arbitration_state_update(
        arbitration_matrix,
        resolution_classifier,
        now,
    )
    operator_resolution_packet = _build_provider_truth_operator_resolution_packet(
        manual_arbitration_packet,
        third_source_consumer,
        resolution_classifier,
        arbitration_state_update,
        now,
    )
    third_source_sla_watchdog = _build_provider_truth_third_source_sla_watchdog(
        third_source_queue,
        third_source_consumer,
        arbitration_state_update,
        now,
    )
    resolution_escalation_rules = _build_provider_truth_resolution_escalation_rules(
        third_source_sla_watchdog,
        resolution_classifier,
        arbitration_state_update,
        now,
    )
    operator_action_inbox = _build_provider_truth_operator_action_inbox(
        review_packet,
        operator_resolution_packet,
        third_source_sla_watchdog,
        resolution_escalation_rules,
        now,
    )
    decision_closeout_journal = _build_provider_truth_decision_closeout_journal(
        review_packet,
        operator_action_inbox,
        decision_audit_trail,
        resolution_classifier,
        now,
    )
    return {
        "status": score.get("status"),
        "readiness_state": score.get("readiness_state"),
        "similarity_matcher": matcher,
        "evidence_queue": queue_after_refresh,
        "due_evidence_refresh": refresh,
        "accumulator_score": score,
        "evidence_timeline": timeline,
        "before_after_score": before_after,
        "patch_confidence_curve": confidence_curve,
        "manual_review_packet": review_packet,
        "approval_gate": approval_gate,
        "dry_run_policy_preview": dry_run_preview,
        "post_approval_watchdog": post_approval_watchdog,
        "patch_target_map": patch_target_map,
        "implementation_checklist": implementation_checklist,
        "simulation_test_recipe": simulation_recipe,
        "policy_patch_work_order": policy_work_order,
        "approval_evidence_summary": approval_evidence_summary,
        "source_trust_weighting": source_trust_weighting,
        "risk_explanation": risk_explanation,
        "risk_case_drilldown": risk_case_drilldown,
        "risk_cause_classifier": risk_cause_classifier,
        "risk_resolution_playbook": risk_resolution_playbook,
        "risk_evidence_recheck_queue": evidence_recheck_queue,
        "hold_aging_escalation": hold_aging_escalation,
        "risk_clear_requirements": risk_clear_requirements,
        "weighted_clear_requirements": weighted_clear_requirements,
        "approval_consequences": approval_consequences,
        "decision_audit_trail": decision_audit_trail,
        "hold_outcome_journal": hold_outcome_journal,
        "cause_accuracy_scoring": cause_accuracy_scoring,
        "outcome_weighted_cause_scores": outcome_weighted_cause_scores,
        "clear_requirement_backtest": clear_requirement_backtest,
        "policy_tuning_suggestions": policy_tuning_suggestions,
        "weighted_threshold_suggestions": weighted_threshold_suggestions,
        "disagreement_cluster_detector": disagreement_clusters,
        "arbitration_decision_matrix": arbitration_matrix,
        "third_source_confirmation_queue": third_source_queue,
        "manual_arbitration_packet": manual_arbitration_packet,
        "third_source_queue_consumer": third_source_consumer,
        "resolution_outcome_classifier": resolution_classifier,
        "arbitration_state_update": arbitration_state_update,
        "operator_resolution_packet": operator_resolution_packet,
        "third_source_sla_watchdog": third_source_sla_watchdog,
        "resolution_escalation_rules": resolution_escalation_rules,
        "operator_action_inbox": operator_action_inbox,
        "decision_closeout_journal": decision_closeout_journal,
        "next_action": policy_work_order.get("next_action") or approval_gate.get("next_action") or score.get("next_action"),
    }


def _provider_truth_retry_delay_minutes(retry_count: int, high_impact: bool) -> int:
    if retry_count <= 0:
        return 0
    schedule = [20, 60, 180, 360] if high_impact else [45, 180, 480, 720]
    return schedule[min(max(0, retry_count - 1), len(schedule) - 1)]


def _build_provider_truth_queue_health(fallback_router: dict, truth_memory: dict, now: datetime) -> dict:
    history_by_key = _provider_truth_memory_history_by_key(truth_memory)
    items = []
    retry_due_routes = []
    active_routes = []
    downgraded = 0
    escalated = 0
    waiting = 0
    due = 0
    oldest_age_minutes = 0.0
    for route in list((fallback_router or {}).get("routes") or []):
        route = dict(route)
        key = _provider_truth_queue_key(route)
        history = history_by_key.get(key) or []
        latest = history[0] if history else {}
        latest_status = str(latest.get("confirmation_status") or "").upper()
        unresolved_rows = [row for row in history if str(row.get("confirmation_status") or "").upper() == "UNRESOLVED"]
        retry_count = len(unresolved_rows)
        first_unresolved_ts = _gb_parse_ts((unresolved_rows[-1] if unresolved_rows else latest).get("ts_utc"))
        last_attempt_ts = _gb_parse_ts(latest.get("ts_utc"))
        age_minutes = round(max(0.0, (now - first_unresolved_ts).total_seconds() / 60.0), 1) if first_unresolved_ts else 0.0
        oldest_age_minutes = max(oldest_age_minutes, age_minutes)
        high_impact = bool(route.get("high_impact")) or _gb_float(route.get("priority_score")) >= 80
        low_impact = (not high_impact) and _gb_float(route.get("priority_score")) < 65
        retry_delay = _provider_truth_retry_delay_minutes(retry_count, high_impact)
        next_retry_at = (
            last_attempt_ts + timedelta(minutes=retry_delay)
            if last_attempt_ts and retry_delay > 0
            else now
        )
        retry_due = bool(next_retry_at <= now)
        status = "DUE_RETRY" if retry_due else "WAITING_RETRY"
        if latest_status == "CONFIRMED":
            status = "CONFIRMED_MEMORY"
            retry_due = False
        elif latest_status == "IDENTITY_MISMATCH":
            status = "IDENTITY_MISMATCH_REVIEW"
            retry_due = False
        elif low_impact and retry_count >= 2 and age_minutes >= 120:
            status = "DOWNGRADED_LOW_IMPACT"
            retry_due = False
            downgraded += 1
        elif high_impact and retry_count >= 2 and age_minutes >= 60:
            status = "ESCALATE_HIGH_IMPACT"
            retry_due = False
            escalated += 1
        elif retry_due:
            due += 1
        else:
            waiting += 1

        item = {
            "symbol": route.get("symbol"),
            "mint": route.get("mint"),
            "route": route.get("route"),
            "current_source": route.get("current_source"),
            "priority_score": route.get("priority_score"),
            "high_impact": high_impact,
            "impact_flags": list(route.get("impact_flags") or []),
            "status": status,
            "retry_count": retry_count,
            "age_minutes": age_minutes,
            "last_checked_at": latest.get("ts_utc"),
            "next_retry_at": next_retry_at.isoformat() if next_retry_at else None,
            "retry_due": retry_due,
            "latest_confirmation_status": latest_status or None,
            "reason": route.get("reason"),
        }
        items.append(item)
        if status in {"DUE_RETRY", "WAITING_RETRY"}:
            active_routes.append(route)
        if retry_due and status == "DUE_RETRY":
            retry_due_routes.append(route)

    items.sort(key=lambda x: (
        1 if str(x.get("status")) == "ESCALATE_HIGH_IMPACT" else 0,
        1 if x.get("retry_due") else 0,
        _gb_float(x.get("priority_score")),
        _gb_float(x.get("age_minutes")),
    ), reverse=True)
    status = (
        "ESCALATE" if escalated
        else "DUE" if due
        else "DOWNGRADED" if downgraded
        else "WAITING" if waiting
        else "CLEAR"
    )
    return {
        "status": status,
        "total_routes": len(items),
        "active_count": len(active_routes),
        "due_count": due,
        "waiting_count": waiting,
        "downgraded_count": downgraded,
        "escalated_count": escalated,
        "oldest_age_minutes": round(oldest_age_minutes, 1),
        "retry_due_routes": retry_due_routes[:8],
        "active_routes": active_routes[:12],
        "items": items[:16],
        "next_action": (
            "Escalate high-impact unresolved provider-truth routes to review."
            if escalated
            else "Retry due provider-truth routes on the controlled cadence."
            if due
            else "Low-impact unresolved routes were downgraded; keep the queue focused."
            if downgraded
            else "Provider-truth queue is waiting for the next retry window."
            if waiting
            else "Provider-truth queue is clear."
        ),
    }


def _apply_provider_truth_queue_health_to_router(fallback_router: dict, queue_health: dict) -> dict:
    out = dict(fallback_router or {})
    all_routes = list((fallback_router or {}).get("routes") or [])
    active_routes = list((queue_health or {}).get("active_routes") if "active_routes" in (queue_health or {}) else all_routes)
    out["all_route_count"] = len(all_routes)
    out["route_count"] = len(active_routes)
    out["routes"] = active_routes[:12]
    out["queue_status"] = (queue_health or {}).get("status")
    out["due_count"] = int((queue_health or {}).get("due_count") or 0)
    out["downgraded_count"] = int((queue_health or {}).get("downgraded_count") or 0)
    out["escalated_count"] = int((queue_health or {}).get("escalated_count") or 0)
    if not active_routes:
        out["status"] = "NO_FALLBACK_NEEDED"
    return out


def _write_provider_truth_queue_escalations(queue_health: dict, now: datetime) -> dict:
    escalated_items = [
        dict(item) for item in list((queue_health or {}).get("items") or [])
        if str(item.get("status") or "").upper() == "ESCALATE_HIGH_IMPACT" and str(item.get("mint") or "").strip()
    ]
    if not escalated_items:
        return {"status": "CLEAR", "written_count": 0, "items": []}
    written = 0
    try:
        conn = _dj_conn()
        try:
            for item in escalated_items[:8]:
                mint = str(item.get("mint") or "").strip()
                flags_json = json.dumps(list(item.get("impact_flags") or []) + ["provider_truth"], separators=(",", ":"))
                raw_json = json.dumps(item, separators=(",", ":"))
                conn.execute(
                    """
                    INSERT INTO provider_repair_escalations (
                        created_ts, updated_ts, mint, symbol, failure_class, repair_status,
                        escalation_lane, escalation_status, priority_score, queue_flags_json,
                        provider_path, reason, source_event_id, operator_decision, operator_note,
                        outcome_label, last_action_ts, sla_due_ts, raw_json
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, NULL, ?, ?, ?, ?)
                    ON CONFLICT(mint, escalation_lane) DO UPDATE SET
                        updated_ts=excluded.updated_ts,
                        symbol=excluded.symbol,
                        failure_class=excluded.failure_class,
                        repair_status=excluded.repair_status,
                        escalation_status=CASE
                            WHEN provider_repair_escalations.escalation_status IN ('DISMISSED','RESOLVED_REPAIRED','REVIEW_COMPLETE_STILL_BLOCKED') THEN provider_repair_escalations.escalation_status
                            ELSE excluded.escalation_status
                        END,
                        priority_score=MAX(COALESCE(provider_repair_escalations.priority_score, 0), COALESCE(excluded.priority_score, 0)),
                        queue_flags_json=excluded.queue_flags_json,
                        provider_path=excluded.provider_path,
                        reason=excluded.reason,
                        operator_decision=CASE
                            WHEN provider_repair_escalations.escalation_status IN ('DISMISSED','RESOLVED_REPAIRED','REVIEW_COMPLETE_STILL_BLOCKED') THEN provider_repair_escalations.operator_decision
                            ELSE excluded.operator_decision
                        END,
                        outcome_label=CASE
                            WHEN provider_repair_escalations.escalation_status IN ('DISMISSED','RESOLVED_REPAIRED','REVIEW_COMPLETE_STILL_BLOCKED') THEN provider_repair_escalations.outcome_label
                            ELSE excluded.outcome_label
                        END,
                        last_action_ts=excluded.last_action_ts,
                        sla_due_ts=excluded.sla_due_ts,
                        raw_json=excluded.raw_json
                    """,
                    (
                        now.isoformat(),
                        now.isoformat(),
                        mint,
                        item.get("symbol"),
                        "provider_truth_unresolved",
                        "UNRESOLVED",
                        "PROVIDER_TRUTH_REVIEW",
                        "QUEUED",
                        _gb_float(item.get("priority_score")),
                        flags_json,
                        item.get("route"),
                        f"Provider truth unresolved after {int(item.get('retry_count') or 0)} retries.",
                        "PENDING",
                        "PENDING_PROVIDER_TRUTH_REVIEW",
                        now.isoformat(),
                        (now + timedelta(hours=6)).isoformat(),
                        raw_json,
                    ),
                )
                written += 1
            conn.commit()
        finally:
            conn.close()
    except Exception as exc:
        return {"status": "ERROR", "written_count": written, "error": str(exc)[:160], "items": escalated_items[:8]}
    return {"status": "QUEUED", "written_count": written, "items": escalated_items[:8]}


def _run_provider_truth_fallback_confirmation(fallback_router: dict, now: datetime, min_interval_minutes: int = 20) -> dict:
    routes = list((fallback_router or {}).get("routes") or [])
    if not routes:
        return {
            "status": "NO_ROUTES",
            "ran": False,
            "read_only": True,
            "target_count": 0,
            "next_action": "No provider-truth fallback route is due.",
        }
    meta_key = "provider_truth_fallback_confirmation_autorun"
    previous = _freshness_kv_read(meta_key)
    last_ts = _gb_parse_ts((previous or {}).get("checked_at"))
    if last_ts and (now - last_ts).total_seconds() < max(60, min_interval_minutes * 60):
        return {
            "status": "THROTTLED",
            "ran": False,
            "read_only": True,
            "target_count": min(6, len(routes)),
            "last_checked_at": previous.get("checked_at"),
            "previous": previous,
            "next_action": "Provider-truth fallback confirmation was recently run; wait for the throttle window.",
        }
    try:
        from utils.token_intelligence import token_intelligence_fallback_confirmation_step  # type: ignore

        result = token_intelligence_fallback_confirmation_step(routes, limit=6)
    except Exception as exc:
        result = {
            "status": "ERROR",
            "checked_at": now.isoformat(),
            "read_only": True,
            "target_count": min(6, len(routes)),
            "error": str(exc)[:180],
            "events": [],
        }
    result = dict(result or {})
    result["ran"] = str(result.get("status") or "").upper() not in {"NO_TARGETS", "ERROR"}
    result["read_only"] = True
    result["requested_routes"] = [
        {
            "symbol": item.get("symbol"),
            "mint": item.get("mint"),
            "route": item.get("route"),
            "current_source": item.get("current_source"),
        }
        for item in routes[:6]
    ]
    result["next_action"] = (
        "Use confirmed fallback source evidence to clear provider-truth blockers."
        if int(result.get("confirmed_count") or 0)
        else "Fallback confirmation did not clear the blocker; keep the route blocked or send it to manual CA review."
    )
    _freshness_kv_write(meta_key, result)
    return result


def _build_provider_truth_outcome_tracking(truth_memory: dict, intelligence_rows: list[dict], now: datetime) -> dict:
    current_by_key: dict[str, dict] = {}
    for row in list(intelligence_rows or []):
        mint = str(row.get("mint") or "").strip()
        symbol = str(row.get("symbol") or "").strip().upper()
        if mint:
            current_by_key[mint] = row
        if symbol:
            current_by_key[f"symbol:{symbol}"] = row

    tracked = []
    confirmed_rows = [
        dict(row) for row in list((truth_memory or {}).get("items") or [])
        if str(row.get("confirmation_status") or "").upper() == "CONFIRMED"
    ]
    for row in confirmed_rows[:80]:
        mint = str(row.get("mint") or "").strip()
        symbol = str(row.get("symbol") or "").strip().upper()
        current = current_by_key.get(mint) or current_by_key.get(f"symbol:{symbol}") or {}
        start_marketcap = _gb_float(row.get("new_marketcap"))
        current_marketcap = _gb_float(current.get("marketcap"))
        return_pct = None
        status = "NO_MARKETCAP"
        if start_marketcap > 0 and current_marketcap > 0:
            return_pct = round(((current_marketcap - start_marketcap) / start_marketcap) * 100.0, 2)
            status = "POSITIVE" if return_pct > 2.0 else "NEGATIVE" if return_pct < -2.0 else "FLAT"
        tracked.append({
            "symbol": row.get("symbol"),
            "mint": row.get("mint"),
            "confirmed_at": row.get("ts_utc"),
            "source": row.get("new_source") or row.get("current_source"),
            "route": row.get("route"),
            "status": status,
            "return_pct": return_pct,
            "confirmed_marketcap": _nullable_float(row.get("new_marketcap")),
            "current_marketcap": _nullable_float(current.get("marketcap")),
            "current_freshness": current.get("data_freshness"),
            "current_confidence": current.get("data_confidence"),
        })

    tracked_with_return = [item for item in tracked if item.get("return_pct") is not None]
    avg_return = (
        round(sum(_gb_float(item.get("return_pct")) for item in tracked_with_return) / len(tracked_with_return), 2)
        if tracked_with_return
        else None
    )
    identity_mismatch_count = int((truth_memory or {}).get("summary", {}).get("IDENTITY_MISMATCH") or 0)
    unresolved_count = int((truth_memory or {}).get("summary", {}).get("UNRESOLVED") or 0)
    return {
        "status": "TRACKING" if tracked else "WAITING",
        "confirmed_count": len(confirmed_rows),
        "tracked_count": len(tracked_with_return),
        "avg_return_pct": avg_return,
        "positive_count": len([item for item in tracked_with_return if str(item.get("status")) == "POSITIVE"]),
        "negative_count": len([item for item in tracked_with_return if str(item.get("status")) == "NEGATIVE"]),
        "flat_count": len([item for item in tracked_with_return if str(item.get("status")) == "FLAT"]),
        "identity_mismatch_count": identity_mismatch_count,
        "unresolved_count": unresolved_count,
        "items": tracked[:12],
        "next_action": (
            "Review provider-truth outcomes before changing source precedence."
            if tracked
            else "Collect confirmed fallback repairs before scoring provider-truth outcomes."
        ),
    }


