def _build_provider_truth_layer(
    intelligence_rows: list[dict],
    journal_rows: list[dict],
    data_watchdog: dict,
    freshness_repair_loop: dict,
    provider_reliability: dict,
    repair_rows: list[dict],
) -> dict:
    now = datetime.now(timezone.utc)
    truth_memory = _read_provider_truth_memory(now - timedelta(days=7))
    learning_score = _build_provider_truth_learning_score(truth_memory, intelligence_rows, None, None, now)
    source_map_base = _build_provider_source_map(intelligence_rows, data_watchdog, provider_reliability, freshness_repair_loop, journal_rows)
    source_map = _apply_provider_truth_learning_to_source_map(source_map_base, learning_score)
    source_index = {
        _provider_source_key(item.get("source")): item
        for item in list(source_map.get("providers") or [])
    }
    targets = _provider_truth_high_impact_targets(freshness_repair_loop, data_watchdog)
    agreement_layer = _build_cross_provider_agreement_layer(targets, intelligence_rows, repair_rows, source_index, truth_memory)
    arbitration = _build_provider_confidence_arbitration(agreement_layer, source_map)
    fallback_router = _build_fallback_provider_router(
        arbitration,
        dict((freshness_repair_loop or {}).get("provider_health_limits") or {}),
    )
    queue_health = _build_provider_truth_queue_health(fallback_router, truth_memory, now)
    fallback_router = _apply_provider_truth_queue_health_to_router(fallback_router, queue_health)
    escalation_writer = _write_provider_truth_queue_escalations(queue_health, now)
    due_router = dict(fallback_router)
    due_router["routes"] = list(queue_health.get("retry_due_routes") or [])
    due_router["route_count"] = len(due_router["routes"])
    fallback_confirmation = _run_provider_truth_fallback_confirmation(due_router, now)
    if str(fallback_confirmation.get("status") or "").upper() in {"CONFIRMED", "IDENTITY_MISMATCH", "UNRESOLVED"}:
        truth_memory = _read_provider_truth_memory(now - timedelta(days=7))
        agreement_layer = _build_cross_provider_agreement_layer(targets, intelligence_rows, repair_rows, source_index, truth_memory)
        arbitration = _build_provider_confidence_arbitration(agreement_layer, source_map)
        fallback_router = _build_fallback_provider_router(
            arbitration,
            dict((freshness_repair_loop or {}).get("provider_health_limits") or {}),
        )
        queue_health = _build_provider_truth_queue_health(fallback_router, truth_memory, now)
        fallback_router = _apply_provider_truth_queue_health_to_router(fallback_router, queue_health)
        escalation_writer = _write_provider_truth_queue_escalations(queue_health, now)
    outcome_tracking = _build_provider_truth_outcome_tracking(truth_memory, intelligence_rows, now)
    learning_score = _build_provider_truth_learning_score(truth_memory, intelligence_rows, queue_health, outcome_tracking, now)
    source_map = _apply_provider_truth_learning_to_source_map(source_map_base, learning_score)
    source_index = {
        _provider_source_key(item.get("source")): item
        for item in list(source_map.get("providers") or [])
    }
    miss_review = _build_provider_truth_miss_review(learning_score, truth_memory, queue_health, intelligence_rows, now)
    miss_repair_workbench = _build_provider_truth_miss_repair_workbench(miss_review, learning_score, truth_memory, intelligence_rows, now)
    miss_evidence_accumulator = _build_provider_truth_miss_evidence_accumulator(
        miss_review,
        miss_repair_workbench,
        learning_score,
        truth_memory,
        intelligence_rows,
        source_index,
        now,
    )
    truth_panel = _build_dashboard_provider_truth_panel(
        source_map,
        agreement_layer,
        arbitration,
        fallback_router,
        fallback_confirmation,
        truth_memory,
        outcome_tracking,
        queue_health,
        escalation_writer,
        learning_score,
        miss_review,
        miss_repair_workbench,
        miss_evidence_accumulator,
    )
    return {
        "status": truth_panel.get("status"),
        "provider_source_map": source_map,
        "cross_provider_agreement": agreement_layer,
        "provider_confidence_arbitration": arbitration,
        "fallback_provider_router": fallback_router,
        "fallback_confirmation_runner": fallback_confirmation,
        "provider_truth_memory": truth_memory,
        "provider_truth_outcome_tracking": outcome_tracking,
        "provider_truth_queue_health": queue_health,
        "provider_truth_escalation_writer": escalation_writer,
        "provider_truth_learning_score": learning_score,
        "provider_truth_miss_review": miss_review,
        "provider_truth_miss_repair_workbench": miss_repair_workbench,
        "provider_truth_miss_evidence_accumulator": miss_evidence_accumulator,
        "dashboard_provider_truth_panel": truth_panel,
        "next_action": truth_panel.get("next_action"),
    }


def _apply_provider_truth_to_rule_gate(rule_gate: dict, provider_truth: dict) -> dict:
    out = copy.deepcopy(rule_gate or {})
    agreement = dict((provider_truth or {}).get("cross_provider_agreement") or {})
    panel = dict((provider_truth or {}).get("dashboard_provider_truth_panel") or {})
    if str(agreement.get("status") or "").upper() != "BLOCKED":
        return out
    blockers = list(out.get("blockers") or [])
    if "provider_truth_confirmation_missing" not in blockers:
        blockers.append("provider_truth_confirmation_missing")
    out["blockers"] = blockers
    out["status"] = "BLOCKED"
    out["provider_truth_gate"] = {
        "status": "BLOCKED",
        "blocked_count": int(panel.get("blocked_count") or 0),
        "top_symbol": panel.get("top_symbol"),
        "top_status": panel.get("top_status"),
        "requirement": "High-impact candidates need two independent non-weak provider confirmations before promotion.",
    }
    out["next_action"] = provider_truth.get("next_action") or out.get("next_action")
    return out


def _build_provider_escalation_queue(escalation_rows: list[dict], now: datetime | None = None) -> dict:
    now = now or datetime.now(timezone.utc)
    active_statuses = {"QUEUED", "WATCHING", "FORCE_REFRESH_REQUESTED", "STALE_REVIEW"}
    active = []
    by_lane: dict[str, int] = {}
    by_status: dict[str, int] = {}
    sla_breached = 0
    for row in escalation_rows or []:
        lane = str(row.get("escalation_lane") or "UNKNOWN").upper()
        status = str(row.get("escalation_status") or "UNKNOWN").upper()
        by_lane[lane] = by_lane.get(lane, 0) + 1
        by_status[status] = by_status.get(status, 0) + 1
        if status not in active_statuses:
            continue
        created = _gb_parse_ts(row.get("created_ts") or row.get("updated_ts"))
        updated = _gb_parse_ts(row.get("updated_ts") or row.get("created_ts"))
        due = _gb_parse_ts(row.get("sla_due_ts"))
        age_minutes = round(max(0.0, (now - created).total_seconds() / 60.0), 1) if created else None
        stale_minutes = round(max(0.0, (now - updated).total_seconds() / 60.0), 1) if updated else None
        breached = bool(due and due <= now)
        if breached:
            sla_breached += 1
        try:
            flags = json.loads(str(row.get("queue_flags_json") or "[]"))
            if not isinstance(flags, list):
                flags = []
        except Exception:
            flags = []
        active.append({
            "id": row.get("id"),
            "symbol": row.get("symbol"),
            "mint": row.get("mint"),
            "lane": lane,
            "status": status,
            "failure_class": row.get("failure_class"),
            "repair_status": row.get("repair_status"),
            "priority_score": _nullable_float(row.get("priority_score")),
            "queue_flags": flags,
            "provider_path": row.get("provider_path"),
            "reason": row.get("reason"),
            "age_minutes": age_minutes,
            "stale_minutes": stale_minutes,
            "sla_due_ts": row.get("sla_due_ts"),
            "sla_breached": breached,
            "operator_decision": row.get("operator_decision"),
            "outcome_label": row.get("outcome_label"),
        })
    active.sort(
        key=lambda x: (
            1 if x.get("sla_breached") else 0,
            _gb_float(x.get("priority_score")),
            _gb_float(x.get("age_minutes")),
        ),
        reverse=True,
    )
    return {
        "status": "SLA_BREACH" if sla_breached else "ACTIVE" if active else "CLEAR",
        "active_count": len(active),
        "sla_breached_count": sla_breached,
        "by_lane": by_lane,
        "by_status": by_status,
        "items": active[:12],
        "next_action": (
            "Resolve breached provider escalations before new rule work."
            if sla_breached
            else "Clear queued provider escalations before promoting candidates."
            if active
            else "No active provider escalations."
        ),
    }


def _build_provider_escalation_accuracy(escalation_rows: list[dict]) -> dict:
    rows = [dict(row) for row in escalation_rows or [] if str(row.get("blocker_correctness") or "").strip()]
    complete = [
        row for row in rows
        if str(row.get("blocker_correctness") or "").upper() not in {"PENDING_OUTCOME", "PENDING"}
    ]
    correctness_counts: dict[str, int] = {}
    lane_stats: dict[str, dict] = {}
    failure_stats: dict[str, dict] = {}
    examples = []
    correct_labels = {"BLOCK_CORRECT", "SUPPRESSION_CORRECT", "REPAIR_RESOLVED"}
    miss_labels = {"BLOCK_MISSED_RUNNER", "SUPPRESSION_TOO_AGGRESSIVE"}
    confidence_adjustment = 0.0
    for row in rows:
        correctness = str(row.get("blocker_correctness") or "UNKNOWN").upper()
        correctness_counts[correctness] = correctness_counts.get(correctness, 0) + 1
        confidence_adjustment += _gb_float(row.get("confidence_impact"))
        lane = str(row.get("escalation_lane") or "UNKNOWN").upper()
        failure = str(row.get("failure_class") or "unknown").lower()
        for bucket, key in ((lane_stats, lane), (failure_stats, failure)):
            item = bucket.setdefault(key, {"key": key, "sample_n": 0, "correct": 0, "missed": 0, "pending": 0})
            item["sample_n"] += 1
            if correctness in correct_labels:
                item["correct"] += 1
            elif correctness in miss_labels:
                item["missed"] += 1
            else:
                item["pending"] += 1
        if correctness in miss_labels and len(examples) < 5:
            examples.append({
                "symbol": row.get("symbol"),
                "mint": row.get("mint"),
                "lane": lane,
                "failure_class": failure,
                "correctness": correctness,
                "max_return_pct": _nullable_float(row.get("outcome_max_return_pct")),
                "return_1h_pct": _nullable_float(row.get("outcome_return_1h_pct")),
                "return_4h_pct": _nullable_float(row.get("outcome_return_4h_pct")),
                "return_24h_pct": _nullable_float(row.get("outcome_return_24h_pct")),
                "outcome_source": row.get("outcome_source"),
                "outcome_1h_status": row.get("outcome_1h_status"),
                "outcome_4h_status": row.get("outcome_4h_status"),
                "outcome_24h_status": row.get("outcome_24h_status"),
                "alert_kind": row.get("outcome_alert_kind"),
                "alert_ts": row.get("outcome_alert_ts"),
                "reason": row.get("outcome_reason"),
            })
    correct = sum(1 for row in complete if str(row.get("blocker_correctness") or "").upper() in correct_labels)
    missed = sum(1 for row in complete if str(row.get("blocker_correctness") or "").upper() in miss_labels)
    accuracy = round((correct / max(1, correct + missed)) * 100.0, 1) if complete else None
    status = (
        "LEARNING" if len(complete) < 5
        else "REVIEW" if missed or _gb_float(accuracy, 100.0) < 70
        else "RELIABLE" if _gb_float(accuracy) >= 80
        else "WATCH"
    )
    def _finish(bucket: dict[str, dict]) -> list[dict]:
        out = []
        for item in bucket.values():
            judged = int(item.get("correct") or 0) + int(item.get("missed") or 0)
            item["accuracy_pct"] = round((int(item.get("correct") or 0) / judged) * 100.0, 1) if judged else None
            out.append(item)
        out.sort(key=lambda x: (int(x.get("missed") or 0), int(x.get("sample_n") or 0)), reverse=True)
        return out[:8]
    return {
        "status": status,
        "sample_n": len(complete),
        "pending_n": len(rows) - len(complete),
        "correct_n": correct,
        "missed_n": missed,
        "accuracy_pct": accuracy,
        "confidence_adjustment": round(confidence_adjustment, 1),
        "correctness_counts": correctness_counts,
        "by_lane": _finish(lane_stats),
        "by_failure": _finish(failure_stats),
        "frozen_failure_classes": sorted({
            str(row.get("failure_class") or "unknown").lower()
            for row in complete
            if str(row.get("blocker_correctness") or "").upper() in miss_labels
        }),
        "frozen_lanes": sorted({
            str(row.get("escalation_lane") or "UNKNOWN").upper()
            for row in complete
            if str(row.get("blocker_correctness") or "").upper() in miss_labels
        }),
        "missed_examples": examples,
        "next_action": (
            "Inspect missed escalation blocks before trusting provider suppression."
            if missed
            else "Keep collecting escalation outcomes until the sample is stronger."
            if len(complete) < 5
            else "Escalation blocking is behaving correctly."
        ),
    }


def _build_provider_escalation_maturity(escalation_rows: list[dict], now: datetime | None = None) -> dict:
    now = now or datetime.now(timezone.utc)
    tracked = [
        dict(row) for row in escalation_rows or []
        if str(row.get("escalation_status") or "").upper() in {
            "REVIEW_COMPLETE_STILL_BLOCKED",
            "SUPPRESSED",
            "RESOLVED_REPAIRED",
        }
    ]
    pending = []
    due_now = []
    overdue = []
    next_due_ts: datetime | None = None
    by_horizon: dict[str, dict] = {
        "1h": {"waiting": 0, "checked": 0, "due": 0},
        "4h": {"waiting": 0, "checked": 0, "due": 0},
        "24h": {"waiting": 0, "checked": 0, "due": 0},
    }
    for row in tracked:
        next_h = str(row.get("next_outcome_horizon") or "").lower()
        next_ts = _gb_parse_ts(row.get("next_outcome_check_ts"))
        for horizon in ("1h", "4h", "24h"):
            status = str(row.get(f"outcome_{horizon}_status") or "").upper()
            if status in {"", "WAITING", "PENDING"}:
                by_horizon[horizon]["waiting"] += 1
            else:
                by_horizon[horizon]["checked"] += 1
        if next_h and next_ts:
            pending.append(row)
            if next_ts <= now:
                due_now.append(row)
                by_horizon.setdefault(next_h, {"waiting": 0, "checked": 0, "due": 0})["due"] += 1
                if (now - next_ts).total_seconds() > 30 * 60:
                    overdue.append(row)
            if next_due_ts is None or next_ts < next_due_ts:
                next_due_ts = next_ts
    minutes_until_next = None
    if next_due_ts:
        minutes_until_next = round((next_due_ts - now).total_seconds() / 60.0, 1)
    status = "OVERDUE" if overdue else "DUE_NOW" if due_now else "WAITING" if pending else "CLEAR"
    return {
        "status": status,
        "tracked_count": len(tracked),
        "pending_count": len(pending),
        "due_now_count": len(due_now),
        "overdue_count": len(overdue),
        "next_check_ts": next_due_ts.isoformat() if next_due_ts else None,
        "minutes_until_next_check": minutes_until_next,
        "by_horizon": by_horizon,
        "next_due": [
            {
                "symbol": row.get("symbol"),
                "mint": row.get("mint"),
                "horizon": row.get("next_outcome_horizon"),
                "next_check_ts": row.get("next_outcome_check_ts"),
                "correctness": row.get("blocker_correctness"),
            }
            for row in sorted(pending, key=lambda r: str(r.get("next_outcome_check_ts") or ""))[:6]
        ],
        "next_action": (
            "Run due escalation outcome checks now."
            if due_now
            else f"Next escalation outcome check in {minutes_until_next}m."
            if minutes_until_next is not None
            else "No pending escalation outcome checks."
        ),
    }


def _build_provider_escalation_alerts(raw_value: str | None) -> dict:
    try:
        rows = json.loads(raw_value or "[]")
        if not isinstance(rows, list):
            rows = []
    except Exception:
        rows = []
    important = []
    for item in rows[:20]:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("kind") or "").upper()
        if kind not in {"BLOCK_MISSED_RUNNER", "SUPPRESSION_TOO_AGGRESSIVE", "ESCALATION_OUTCOME_OVERDUE", "ESCALATION_ACCURACY_REVIEW"}:
            continue
        important.append({
            "ts_utc": item.get("ts_utc"),
            "kind": kind,
            "severity": item.get("severity"),
            "symbol": item.get("symbol"),
            "mint": item.get("mint"),
            "message": item.get("message"),
            "row_id": item.get("row_id"),
            "data": item.get("data") if isinstance(item.get("data"), dict) else {},
        })
    return {
        "status": "ACTIVE" if important else "CLEAR",
        "count": len(important),
        "items": important[:10],
    }


def _review_state_map(raw_value: str | None) -> dict[str, dict]:
    try:
        payload = json.loads(raw_value or "{}")
        if not isinstance(payload, dict):
            return {}
        out: dict[str, dict] = {}
        for key, value in payload.items():
            if isinstance(value, dict):
                out[str(key)] = dict(value)
        return out
    except Exception:
        return {}


def _build_provider_escalation_review_queue(alerts: dict, escalation_rows: list[dict], raw_states: str | None) -> dict:
    rows_by_id = {
        int(row.get("id") or 0): dict(row)
        for row in escalation_rows or []
        if row.get("id") not in (None, "")
    }
    states = _review_state_map(raw_states)
    groups: dict[str, dict] = {}
    for alert in list((alerts or {}).get("items") or []):
        if not isinstance(alert, dict):
            continue
        row = rows_by_id.get(int(_gb_float(alert.get("row_id")))) or {}
        data = dict(alert.get("data") or {})
        failure = str(data.get("failure_class") or row.get("failure_class") or "unknown").strip().lower() or "unknown"
        lane = str(data.get("lane") or row.get("escalation_lane") or "UNKNOWN").strip().upper() or "UNKNOWN"
        group_key = f"{failure}:{lane}"
        state_row = dict(states.get(group_key) or {})
        state = str(state_row.get("state") or "OPEN").strip().upper()
        if state not in (_PROVIDER_ESCALATION_REVIEW_OPEN_STATES | _PROVIDER_ESCALATION_REVIEW_CLOSED_STATES):
            state = "OPEN"
        group = groups.setdefault(group_key, {
            "group_key": group_key,
            "state": state,
            "state_updated_at": state_row.get("updated_at"),
            "operator_note": state_row.get("note"),
            "failure_class": failure,
            "lane": lane,
            "alert_count": 0,
            "kind_counts": {},
            "symbols": [],
            "latest_alert_ts": None,
            "max_return_pct": None,
            "evidence": [],
        })
        kind = str(alert.get("kind") or "ESCALATION_ALERT").upper()
        group["alert_count"] = int(group.get("alert_count") or 0) + 1
        group["kind_counts"][kind] = int(group["kind_counts"].get(kind) or 0) + 1
        symbol = str(alert.get("symbol") or row.get("symbol") or "").strip().upper()
        if symbol and symbol not in group["symbols"]:
            group["symbols"].append(symbol)
        ts = str(alert.get("ts_utc") or row.get("outcome_alert_ts") or "")
        if ts and (not group.get("latest_alert_ts") or ts > str(group.get("latest_alert_ts"))):
            group["latest_alert_ts"] = ts
        max_ret = _nullable_float(data.get("max_return_pct"))
        if max_ret is None:
            max_ret = _nullable_float(row.get("outcome_max_return_pct"))
        if max_ret is not None and (group.get("max_return_pct") is None or max_ret > _gb_float(group.get("max_return_pct"))):
            group["max_return_pct"] = max_ret
        if len(group["evidence"]) < 6:
            group["evidence"].append({
                "symbol": symbol or alert.get("symbol") or row.get("symbol"),
                "mint": alert.get("mint") or row.get("mint"),
                "kind": kind,
                "alert_ts": ts or None,
                "message": alert.get("message"),
                "row_id": alert.get("row_id"),
                "failure_class": failure,
                "lane": lane,
                "correctness": row.get("blocker_correctness"),
                "outcome_source": row.get("outcome_source"),
                "max_return_pct": max_ret,
                "return_1h_pct": _nullable_float(data.get("return_1h_pct") if data.get("return_1h_pct") is not None else row.get("outcome_return_1h_pct")),
                "return_4h_pct": _nullable_float(data.get("return_4h_pct") if data.get("return_4h_pct") is not None else row.get("outcome_return_4h_pct")),
                "return_24h_pct": _nullable_float(data.get("return_24h_pct") if data.get("return_24h_pct") is not None else row.get("outcome_return_24h_pct")),
                "outcome_1h_status": row.get("outcome_1h_status"),
                "outcome_4h_status": row.get("outcome_4h_status"),
                "outcome_24h_status": row.get("outcome_24h_status"),
                "outcome_reason": row.get("outcome_reason"),
            })

    items = []
    for group in groups.values():
        state = str(group.get("state") or "OPEN").upper()
        unresolved = state in _PROVIDER_ESCALATION_REVIEW_OPEN_STATES
        failure = str(group.get("failure_class") or "unknown").lower()
        recommended = (
            "DATA_PATCH_NEEDED"
            if failure in {"provider_miss", "no_market_data", "bad_ca_or_pair_mismatch"}
            else "RULE_PATCH_NEEDED"
        )
        group["unresolved"] = unresolved
        group["frozen"] = unresolved
        group["recommended_state"] = recommended
        group["next_action"] = (
            "Resolve or classify this alert group before promoting related rules."
            if unresolved
            else "Review group closed; promotion freeze removed for this group."
        )
        items.append(group)
    items.sort(
        key=lambda x: (
            1 if x.get("unresolved") else 0,
            _gb_float(x.get("max_return_pct")),
            int(x.get("alert_count") or 0),
            str(x.get("latest_alert_ts") or ""),
        ),
        reverse=True,
    )
    state_counts: dict[str, int] = {}
    for item in items:
        state_counts[str(item.get("state") or "OPEN").upper()] = state_counts.get(str(item.get("state") or "OPEN").upper(), 0) + 1
    unresolved_items = [item for item in items if item.get("unresolved")]
    return {
        "status": "ACTIVE" if unresolved_items else "CLEAR" if items else "NO_ALERTS",
        "group_count": len(items),
        "unresolved_count": len(unresolved_items),
        "state_counts": state_counts,
        "frozen_failure_classes": sorted({str(item.get("failure_class") or "unknown").lower() for item in unresolved_items}),
        "frozen_lanes": sorted({str(item.get("lane") or "UNKNOWN").upper() for item in unresolved_items}),
        "items": items[:10],
        "next_action": (
            "Classify open escalation alert groups before rule promotion."
            if unresolved_items
            else "No unresolved escalation alert groups."
        ),
    }


def _patch_state_map(raw_value: str | None) -> dict[str, dict]:
    try:
        payload = json.loads(raw_value or "{}")
        if not isinstance(payload, dict):
            return {}
        out: dict[str, dict] = {}
        for key, value in payload.items():
            if isinstance(value, dict):
                out[str(key)] = dict(value)
        return out
    except Exception:
        return {}


def _build_provider_escalation_patch_plans(
    review_queue: dict,
    rule_simulator: dict,
    escalation_accuracy: dict,
    raw_patch_states: str | None,
) -> dict:
    patch_states = _patch_state_map(raw_patch_states)
    items = []
    for group in list((review_queue or {}).get("items") or []):
        if not isinstance(group, dict):
            continue
        group_key = str(group.get("group_key") or "").strip()
        if not group_key:
            continue
        state = str(group.get("state") or "OPEN").upper()
        if state in _PROVIDER_ESCALATION_REVIEW_CLOSED_STATES:
            continue
        failure = str(group.get("failure_class") or "unknown").lower()
        lane = str(group.get("lane") or "UNKNOWN").upper()
        evidence = [dict(item) for item in list(group.get("evidence") or []) if isinstance(item, dict)]
        alert_count = int(group.get("alert_count") or len(evidence) or 0)
        max_return = _gb_float(group.get("max_return_pct"))
        avg_1h = _avg([_nullable_float(item.get("return_1h_pct")) for item in evidence])
        avg_4h = _avg([_nullable_float(item.get("return_4h_pct")) for item in evidence])
        state_row = dict(patch_states.get(group_key) or {})
        manual_state = str(state_row.get("state") or "WATCH").upper()
        if manual_state not in _PROVIDER_ESCALATION_PATCH_STATES:
            manual_state = "WATCH"
        if state == "DATA_PATCH_NEEDED" or failure in {"provider_miss", "no_market_data", "bad_ca_or_pair_mismatch"}:
            plan_type = "DATA_PROVIDER_REPAIR"
            proposed_fix = (
                "Strengthen provider repair before this blocker can suppress candidates: force fresh market reads, "
                "fallback source confirmation, and identity re-check for this failure class."
            )
            simulated_benefit = alert_count
            weak_buy_risk = 0
            expected_effect = "Recover market/identity context for names that were blocked by provider gaps."
        elif state == "RULE_PATCH_NEEDED":
            plan_type = "BLOCKER_RULE_PATCH"
            proposed_fix = (
                "Replay this blocker as scout-only instead of full suppression when early return evidence is strong."
            )
            sim_top = dict((rule_simulator or {}).get("top_candidate") or {})
            simulated_benefit = alert_count + max(0, int(sim_top.get("missed_runner_still_blocked_n") or 0))
            weak_buy_risk = max(0, int(sim_top.get("would_block_good_buy_n") or 0))
            expected_effect = "Reduce missed runners hidden by this blocker while preserving clean-buy gates."
        else:
            plan_type = str(group.get("recommended_state") or "DATA_PATCH_NEEDED").replace("_NEEDED", "")
            proposed_fix = "Classify this review group as data or rule work before implementation planning."
            simulated_benefit = alert_count
            weak_buy_risk = 1 if plan_type == "RULE_PATCH" else 0
            expected_effect = "No implementation until the review state is explicit."

        sample_n = max(alert_count, len(evidence))
        confidence_score = 0.0
        confidence_score += min(45.0, sample_n * 15.0)
        confidence_score += min(35.0, max_return)
        confidence_score += 15.0 if plan_type == "DATA_PROVIDER_REPAIR" else 0.0
        confidence_score -= weak_buy_risk * 12.0
        confidence_score = round(max(0.0, min(100.0, confidence_score)), 1)
        if state in {"OPEN", "ACKNOWLEDGED"}:
            gate_status = "NEEDS_CLASSIFICATION"
            gate_reason = "Review group must be marked as rule or data patch needed first."
        elif sample_n < 1:
            gate_status = "NEEDS_MORE_DATA"
            gate_reason = "No alert evidence attached to this group yet."
        elif weak_buy_risk > simulated_benefit:
            gate_status = "REJECT_RISK"
            gate_reason = "Replay risk is larger than expected missed-runner benefit."
        elif confidence_score >= 55 and simulated_benefit > weak_buy_risk:
            gate_status = "READY_FOR_MANUAL_REVIEW"
            gate_reason = "Evidence suggests benefit exceeds risk; manual implementation review is allowed."
        else:
            gate_status = "NEEDS_MORE_DATA"
            gate_reason = "Collect more outcome evidence before implementation."

        if manual_state == "READY_FOR_IMPLEMENTATION" and gate_status != "READY_FOR_MANUAL_REVIEW":
            manual_state = "WATCH"
        items.append({
            "group_key": group_key,
            "plan_key": f"patch:{group_key}",
            "review_state": state,
            "manual_state": manual_state,
            "manual_state_updated_at": state_row.get("updated_at"),
            "operator_note": state_row.get("note"),
            "plan_type": plan_type,
            "failure_class": failure,
            "lane": lane,
            "proposed_fix": proposed_fix,
            "expected_effect": expected_effect,
            "sample_n": sample_n,
            "alert_count": alert_count,
            "max_return_pct": _nullable_float(max_return),
            "avg_1h_pct": avg_1h,
            "avg_4h_pct": avg_4h,
            "simulated_benefit_n": simulated_benefit,
            "weak_buy_risk_n": weak_buy_risk,
            "confidence_score": confidence_score,
            "gate_status": gate_status,
            "gate_reason": gate_reason,
            "ready_for_implementation": manual_state == "READY_FOR_IMPLEMENTATION",
            "evidence": evidence[:4],
        })
    items.sort(
        key=lambda x: (
            1 if x.get("gate_status") == "READY_FOR_MANUAL_REVIEW" else 0,
            1 if x.get("manual_state") == "READY_FOR_IMPLEMENTATION" else 0,
            _gb_float(x.get("confidence_score")),
            _gb_float(x.get("max_return_pct")),
        ),
        reverse=True,
    )
    ready = [item for item in items if item.get("gate_status") == "READY_FOR_MANUAL_REVIEW"]
    implementation_ready = [item for item in items if item.get("ready_for_implementation")]
    state_counts: dict[str, int] = {}
    for item in items:
        key = str(item.get("gate_status") or "UNKNOWN").upper()
        state_counts[key] = state_counts.get(key, 0) + 1
    return {
        "status": "IMPLEMENTATION_READY" if implementation_ready else "READY_REVIEW" if ready else "WATCH" if items else "NO_PLANS",
        "plan_count": len(items),
        "ready_count": len(ready),
        "implementation_ready_count": len(implementation_ready),
        "state_counts": state_counts,
        "top_plan": items[0] if items else None,
        "items": items[:10],
        "next_action": (
            "Implement only manually reviewed ready patch plans; do not auto-change live rules."
            if implementation_ready
            else "Review the top patch plan and mark ready only after human approval."
            if ready
            else "Classify review groups or collect more outcome evidence before patching."
            if items
            else "No escalation patch plans."
        ),
    }


def _work_order_state_map(raw_value: str | None) -> dict[str, dict]:
    try:
        payload = json.loads(raw_value or "{}")
        if not isinstance(payload, dict):
            return {}
        out: dict[str, dict] = {}
        for key, value in payload.items():
            if isinstance(value, dict):
                out[str(key)] = dict(value)
        return out
    except Exception:
        return {}


def _work_order_risk_label(plan: dict) -> str:
    plan_type = str(plan.get("plan_type") or "").upper()
    lane = str(plan.get("lane") or "").upper()
    if "EXECUTION" in lane or "BUY" in lane:
        return "EXECUTION_SENSITIVE"
    if plan_type == "DATA_PROVIDER_REPAIR":
        return "DATA_ONLY"
    if plan_type == "BLOCKER_RULE_PATCH" and "SCOUT" in str(plan.get("proposed_fix") or "").upper():
        return "SCOUT_ONLY"
    if plan_type in {"BLOCKER_RULE_PATCH", "RULE_PATCH"}:
        return "RULE_TUNING"
    return "DATA_ONLY"


def _build_provider_escalation_work_orders(patch_plans: dict, raw_work_states: str | None) -> dict:
    states = _work_order_state_map(raw_work_states)
    items = []
    for plan in list((patch_plans or {}).get("items") or []):
        if not isinstance(plan, dict) or not bool(plan.get("ready_for_implementation")):
            continue
        group_key = str(plan.get("group_key") or "").strip()
        if not group_key:
            continue
        state_row = dict(states.get(group_key) or {})
        state = str(state_row.get("state") or "READY").upper()
        if state not in _PROVIDER_ESCALATION_WORK_ORDER_STATES:
            state = "READY"
        risk = _work_order_risk_label(plan)
        if risk == "DATA_ONLY":
            subsystem = "token intelligence provider repair"
            files = ["utils/token_intelligence.py", "dashboard/backend/routers/home.py"]
            functions = ["_build_provider_repair_snapshot", "token_intelligence_step", "_build_provider_escalation_patch_plans"]
            goal = f"Improve data repair for {plan.get('failure_class')} so the blocker does not suppress recoverable runners."
        elif risk == "SCOUT_ONLY":
            subsystem = "memecoin decision/routing rules"
            files = ["utils/memecoin_manager.py", "dashboard/backend/routers/home.py"]
            functions = ["decision_state generation", "Good Buy/Action Board blocker handling"]
            goal = f"Convert {plan.get('failure_class')} in {plan.get('lane')} from hard suppression to scout-only when proof is strong."
        else:
            subsystem = "memecoin rule tuning"
            files = ["utils/memecoin_manager.py", "dashboard/backend/routers/home.py"]
            functions = ["decision state rules", "rule simulator", "Daily Brief patch proof"]
            goal = f"Tune {plan.get('failure_class')} in {plan.get('lane')} using replay evidence before promotion."
        checklist = [
            {"key": "code_change", "label": "Make the smallest scoped code change in the target subsystem.", "required": True},
            {"key": "replay_or_smoke", "label": "Run replay/smoke proof against the affected blocker group.", "required": True},
            {"key": "frontend_proof", "label": "Verify Home/Daily Brief still exposes evidence and state correctly.", "required": True},
            {"key": "deploy_verification", "label": "Deploy and verify services, health, logs, and dashboard route.", "required": True},
            {"key": "rollback_condition", "label": "Define rollback condition: weaker buys increase or provider freshness degrades.", "required": True},
        ]
        items.append({
            "group_key": group_key,
            "work_order_key": f"work:{group_key}",
            "state": state,
            "state_updated_at": state_row.get("updated_at"),
            "operator_note": state_row.get("note"),
            "risk_label": risk,
            "target_subsystem": subsystem,
            "target_files": files,
            "target_functions": functions,
            "goal": goal,
            "constraints": [
                "No automatic rule edits from the dashboard.",
                "No live buying re-arm.",
                "Keep execution lock unchanged.",
                "Require manual implementation and post-deploy verification.",
            ],
            "proof_required": {
                "sample_n": plan.get("sample_n"),
                "confidence_score": plan.get("confidence_score"),
                "simulated_benefit_n": plan.get("simulated_benefit_n"),
                "weak_buy_risk_n": plan.get("weak_buy_risk_n"),
                "gate_status": plan.get("gate_status"),
            },
            "checklist": checklist,
            "rollback_condition": "Rollback if replay increases weak buys, removes active safety gates, or creates dashboard/runtime errors.",
            "source_plan": plan,
            "next_action": (
                "Engineering work is started; complete checklist before deploy."
                if state == "STARTED"
                else "Start work order manually when ready to implement."
                if state == "READY"
                else "Resolve blocker before implementation continues."
                if state == "BLOCKED"
                else "Work order complete; keep monitoring outcomes."
            ),
        })
    items.sort(
        key=lambda x: (
            {"STARTED": 3, "READY": 2, "BLOCKED": 1, "COMPLETE": 0}.get(str(x.get("state") or ""), 0),
            _gb_float(((x.get("source_plan") or {}).get("confidence_score"))),
            _gb_float(((x.get("source_plan") or {}).get("max_return_pct"))),
        ),
        reverse=True,
    )
    state_counts: dict[str, int] = {}
    for item in items:
        state = str(item.get("state") or "READY").upper()
        state_counts[state] = state_counts.get(state, 0) + 1
    return {
        "status": "IN_PROGRESS" if state_counts.get("STARTED") else "READY" if state_counts.get("READY") else "CLEAR" if items else "NO_WORK_ORDERS",
        "work_order_count": len(items),
        "started_count": int(state_counts.get("STARTED") or 0),
        "ready_count": int(state_counts.get("READY") or 0),
        "state_counts": state_counts,
        "top_work_order": items[0] if items else None,
        "items": items[:10],
        "next_action": (
            "Finish the started implementation checklist."
            if state_counts.get("STARTED")
            else "Start the top work order manually when ready."
            if state_counts.get("READY")
            else "No implementation work order is ready."
        ),
    }


def _execution_pack_replay_recipe(order: dict) -> list[dict]:
    risk = str(order.get("risk_label") or "").upper()
    group_key = str(order.get("group_key") or "")
    if risk == "DATA_ONLY":
        return [
            {
                "key": "provider_repair_smoke",
                "label": "Run provider repair smoke for the affected failure class.",
                "command": "env PYTHONPATH=. python3 -m py_compile utils/token_intelligence.py dashboard/backend/routers/home.py",
            },
            {
                "key": "outcome_autorun_smoke",
                "label": f"Use a temp-DB escalation smoke for {group_key} and confirm the blocker outcome stays auditable.",
                "command": "env PYTHONPATH=dashboard/backend:. python3 - <<'PY'\n# Build a temp DB with a due escalation row, run the outcome evaluator, and assert alert/review evidence persists.\nPY",
            },
        ]
    if risk == "SCOUT_ONLY":
        return [
            {
                "key": "decision_replay",
                "label": "Replay recent decision rows and confirm the blocker becomes scout-only, not full buy.",
                "command": "env PYTHONPATH=dashboard/backend:. python3 - <<'PY'\n# Replay Daily Brief outcome rows for the target blocker and compare missed/protected/weak counts.\nPY",
            },
            {
                "key": "frontend_snapshot",
                "label": "Build frontend and verify Home cards still show blocker evidence.",
                "command": "cd dashboard/frontend && npm run build",
            },
        ]
    return [
        {
            "key": "rule_replay",
            "label": "Replay the proposed rule tuning against recent outcome rows before changing thresholds.",
            "command": "env PYTHONPATH=dashboard/backend:. python3 - <<'PY'\n# Call _build_daily_crypto_brief(24) and inspect rule_simulator + patch plan evidence.\nPY",
        },
        {
            "key": "safety_compile",
            "label": "Compile backend surfaces that expose the work order and rule gate.",
            "command": "python3 -m py_compile dashboard/backend/routers/home.py dashboard/backend/main.py utils/token_intelligence.py",
        },
    ]


def _build_provider_escalation_execution_packs(work_orders: dict) -> dict:
    packs = []
    for order in list((work_orders or {}).get("items") or []):
        if not isinstance(order, dict):
            continue
        state = str(order.get("state") or "READY").upper()
        if state not in {"READY", "STARTED"}:
            continue
        plan = dict(order.get("source_plan") or {})
        evidence = [dict(item) for item in list(plan.get("evidence") or []) if isinstance(item, dict)]
        target_files = list(order.get("target_files") or [])
        target_functions = list(order.get("target_functions") or [])
        packs.append({
            "pack_key": f"exec:{order.get('group_key')}",
            "group_key": order.get("group_key"),
            "state": "ACTIVE" if state == "STARTED" else "READY",
            "work_order_state": state,
            "risk_label": order.get("risk_label"),
            "target_subsystem": order.get("target_subsystem"),
            "evidence_bundle": {
                "symbols": [item.get("symbol") for item in evidence if item.get("symbol")][:8],
                "mints": [item.get("mint") for item in evidence if item.get("mint")][:8],
                "alert_kinds": sorted({str(item.get("kind") or "UNKNOWN") for item in evidence}),
                "max_return_pct": plan.get("max_return_pct"),
                "avg_1h_pct": plan.get("avg_1h_pct"),
                "avg_4h_pct": plan.get("avg_4h_pct"),
                "confidence_score": plan.get("confidence_score"),
                "simulated_benefit_n": plan.get("simulated_benefit_n"),
                "weak_buy_risk_n": plan.get("weak_buy_risk_n"),
                "gate_status": plan.get("gate_status"),
                "why_it_matters": plan.get("expected_effect") or order.get("goal"),
                "evidence": evidence[:4],
            },
            "replay_test_recipe": _execution_pack_replay_recipe(order),
            "target_code_map": [
                {
                    "file": target_files[idx] if idx < len(target_files) else target_files[-1] if target_files else None,
                    "function": fn,
                    "expected_change": (
                        "Provider repair/read fallback behavior"
                        if str(order.get("risk_label") or "") == "DATA_ONLY"
                        else "Decision rule or scout-only blocker handling"
                    ),
                }
                for idx, fn in enumerate(target_functions or ["target implementation"])
            ],
            "completion_criteria": [
                "Code change is scoped to the target subsystem.",
                "Replay/smoke proof passes for the affected blocker group.",
                "Home/Daily Brief still renders review, patch plan, work order, and execution pack evidence.",
                "Production deploy verifies services active, /api/health 200, public :8888 closed, and no fresh tracebacks.",
                "MEMECOIN_LIVE_EXECUTION_CONFIRMED remains not true/unset; no live buying re-arm.",
                str(order.get("rollback_condition") or "Rollback condition documented."),
            ],
            "next_action": (
                "Continue this coding session from the target code map and replay recipe."
                if state == "STARTED"
                else "Press START on the work order before implementation begins."
            ),
        })
    for pack in packs:
        evidence = dict(pack.get("evidence_bundle") or {})
        risk = str(pack.get("risk_label") or "").upper()
        state = str(pack.get("state") or "").upper()
        benefit = int(evidence.get("simulated_benefit_n") or 0)
        weak_risk = int(evidence.get("weak_buy_risk_n") or 0)
        max_return = _gb_float(evidence.get("max_return_pct"))
        avg_1h = _gb_float(evidence.get("avg_1h_pct"))
        confidence = _gb_float(evidence.get("confidence_score"))
        active_bonus = 12.0 if state == "ACTIVE" else 4.0 if state == "READY" else 0.0
        impact_score = min(45.0, benefit * 12.0 + max(0.0, max_return) * 0.45 + max(0.0, avg_1h) * 0.25)
        confidence_score = min(35.0, confidence * 0.35)
        safety_score = 14.0 if str(evidence.get("gate_status") or "").upper() == "READY_FOR_MANUAL_REVIEW" else 6.0
        risk_penalty = weak_risk * 14.0
        if risk == "EXECUTION_SENSITIVE":
            risk_penalty += 18.0
        elif risk == "RULE_TUNING":
            risk_penalty += 8.0
        elif risk == "SCOUT_ONLY":
            risk_penalty += 4.0
        priority_score = round(max(0.0, min(100.0, impact_score + confidence_score + safety_score + active_bonus - risk_penalty)), 1)
        pack["priority_score"] = priority_score
        pack["score_breakdown"] = {
            "impact": round(impact_score, 1),
            "confidence": round(confidence_score, 1),
            "safety": round(safety_score, 1),
            "state_bonus": round(active_bonus, 1),
            "risk_penalty": round(risk_penalty, 1),
        }
        pack["mission_rank_reason"] = (
            f"score {priority_score} · benefit {benefit}/risk {weak_risk} · "
            f"conf {round(confidence, 1)} · max {round(max_return, 1)}%"
        )
    packs.sort(
        key=lambda x: (
            1 if x.get("state") == "ACTIVE" else 0,
            _gb_float(x.get("priority_score")),
            _gb_float(((x.get("evidence_bundle") or {}).get("confidence_score"))),
            _gb_float(((x.get("evidence_bundle") or {}).get("max_return_pct"))),
        ),
        reverse=True,
    )
    active = [pack for pack in packs if pack.get("state") == "ACTIVE"]
    return {
        "status": "ACTIVE" if active else "READY" if packs else "NO_PACKS",
        "pack_count": len(packs),
        "active_count": len(active),
        "top_pack": packs[0] if packs else None,
        "scoring": {
            "method": "impact + confidence + safety + state - risk",
            "top_score": packs[0].get("priority_score") if packs else None,
            "scored_count": len(packs),
        },
        "items": packs[:8],
        "next_action": (
            "Use the active execution pack as the coding handoff."
            if active
            else "Start a work order to activate its execution pack."
            if packs
            else "No execution pack is ready."
        ),
    }


def _build_provider_post_patch_outcome_tracker(work_orders: dict, escalation_rows: list[dict]) -> dict:
    completed_orders = [
        dict(order) for order in list((work_orders or {}).get("items") or [])
        if str(order.get("state") or "").upper() == "COMPLETE"
    ]
    items = []
    correct_labels = {"BLOCK_CORRECT", "SUPPRESSION_CORRECT", "REPAIR_RESOLVED"}
    miss_labels = {"BLOCK_MISSED_RUNNER", "SUPPRESSION_TOO_AGGRESSIVE"}
    for order in completed_orders:
        plan = dict(order.get("source_plan") or {})
        failure = str(plan.get("failure_class") or "").lower()
        lane = str(plan.get("lane") or "").upper()
        completed_at = _gb_parse_ts(order.get("state_updated_at"))
        matched = []
        for row in escalation_rows or []:
            if failure and str(row.get("failure_class") or "").lower() != failure:
                continue
            if lane and str(row.get("escalation_lane") or "").upper() != lane:
                continue
            outcome_ts = _gb_parse_ts(row.get("outcome_check_ts") or row.get("outcome_alert_ts") or row.get("updated_ts"))
            if completed_at and outcome_ts and outcome_ts < completed_at:
                continue
            correctness = str(row.get("blocker_correctness") or "").upper()
            if not correctness:
                continue
            matched.append(dict(row))
        correct = sum(1 for row in matched if str(row.get("blocker_correctness") or "").upper() in correct_labels)
        missed = sum(1 for row in matched if str(row.get("blocker_correctness") or "").upper() in miss_labels)
        pending = sum(1 for row in matched if str(row.get("blocker_correctness") or "").upper() in {"PENDING", "PENDING_OUTCOME"})
        judged = correct + missed
        status = (
            "REGRESSION_REVIEW" if missed
            else "IMPROVING" if correct and not missed
            else "WAITING_OUTCOMES" if pending or not judged
            else "TRACKING"
        )
        items.append({
            "group_key": order.get("group_key"),
            "status": status,
            "risk_label": order.get("risk_label"),
            "target_subsystem": order.get("target_subsystem"),
            "completed_at": order.get("state_updated_at"),
            "sample_n": judged,
            "correct_n": correct,
            "missed_n": missed,
            "pending_n": pending,
            "accuracy_pct": round((correct / max(1, judged)) * 100.0, 1) if judged else None,
            "max_return_pct": _nullable_float(max([_gb_float(row.get("outcome_max_return_pct")) for row in matched], default=0.0)),
            "symbols": [
                str(row.get("symbol") or "").upper()
                for row in matched[:6]
                if str(row.get("symbol") or "").strip()
            ],
            "next_action": (
                "Freeze related promotions and inspect the regression."
                if missed
                else "Keep collecting 24h/48h outcomes for this completed patch."
                if not judged
                else "Patch outcome is improving; keep monitoring for drift."
            ),
        })
    items.sort(
        key=lambda x: (
            1 if x.get("status") == "REGRESSION_REVIEW" else 0,
            int(x.get("sample_n") or 0),
            _gb_float(x.get("max_return_pct")),
        ),
        reverse=True,
    )
    regression_count = sum(1 for item in items if item.get("status") == "REGRESSION_REVIEW")
    improving_count = sum(1 for item in items if item.get("status") == "IMPROVING")
    return {
        "status": "REGRESSION_REVIEW" if regression_count else "TRACKING" if items else "NO_COMPLETED_PATCHES",
        "tracked_count": len(items),
        "regression_count": regression_count,
        "improving_count": improving_count,
        "top": items[0] if items else None,
        "items": items[:8],
        "next_action": (
            "Review post-patch regressions before starting another mission."
            if regression_count
            else "Keep completed patch outcomes under observation."
            if items
            else "Complete a work order to start post-patch tracking."
        ),
    }


def _build_provider_regression_guard(
    post_patch_tracker: dict,
    escalation_accuracy: dict,
    review_queue: dict,
    execution_packs: dict,
) -> dict:
    items = []
    for item in list((post_patch_tracker or {}).get("items") or []):
        if str(item.get("status") or "").upper() == "REGRESSION_REVIEW":
            group_key = str(item.get("group_key") or "")
            failure, _, lane = group_key.partition(":")
            items.append({
                "source": "post_patch",
                "group_key": group_key,
                "failure_class": failure or None,
                "lane": lane or None,
                "severity": "HIGH",
                "reason": f"Completed patch produced {item.get('missed_n') or 0} missed escalation outcomes.",
                "freeze": True,
            })
    for failure in list((escalation_accuracy or {}).get("frozen_failure_classes") or []):
        items.append({
            "source": "escalation_accuracy",
            "group_key": str(failure),
            "failure_class": str(failure),
            "lane": None,
            "severity": "MEDIUM",
            "reason": "Escalation accuracy has missed-runner evidence for this failure class.",
            "freeze": True,
        })
    for lane in list((escalation_accuracy or {}).get("frozen_lanes") or []):
        items.append({
            "source": "escalation_accuracy",
            "group_key": str(lane),
            "failure_class": None,
            "lane": str(lane),
            "severity": "MEDIUM",
            "reason": "Escalation accuracy has missed-runner evidence for this lane.",
            "freeze": True,
        })
    top_pack = dict((execution_packs or {}).get("top_pack") or {})
    weak_risk = int(((top_pack.get("evidence_bundle") or {}).get("weak_buy_risk_n")) or 0)
    benefit = int(((top_pack.get("evidence_bundle") or {}).get("simulated_benefit_n")) or 0)
    if top_pack and weak_risk > benefit:
        items.append({
            "source": "pack_score",
            "group_key": top_pack.get("group_key"),
            "failure_class": None,
            "lane": None,
            "severity": "HIGH",
            "reason": "Top execution pack carries more weak-buy risk than simulated benefit.",
            "freeze": True,
        })
    seen = set()
    deduped = []
    for item in items:
        key = (item.get("source"), item.get("group_key"), item.get("failure_class"), item.get("lane"))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return {
        "status": "ACTIVE" if deduped else "CLEAR",
        "freeze_count": len(deduped),
        "frozen_failure_classes": sorted({str(item.get("failure_class")) for item in deduped if item.get("failure_class")}),
        "frozen_lanes": sorted({str(item.get("lane")) for item in deduped if item.get("lane")}),
        "items": deduped[:10],
        "next_action": (
            "Freeze similar promotions until regression evidence is reviewed."
            if deduped
            else "No regression freeze is active."
        ),
    }


def _build_daily_top_mission(
    execution_packs: dict,
    post_patch_tracker: dict,
    regression_guard: dict,
    daily_build_score: dict,
    live_context_mission: dict | None = None,
    live_context_evidence: dict | None = None,
    live_context_outcome_loop: dict | None = None,
) -> dict:
    top_pack = dict((execution_packs or {}).get("top_pack") or {})
    if str((regression_guard or {}).get("status") or "").upper() == "ACTIVE":
        return {
            "status": "REGRESSION_GUARD",
            "mission_type": "REGRESSION_REVIEW",
            "title": "Review regression guard before new build work",
            "priority_score": 100,
            "pack_key": top_pack.get("pack_key"),
            "group_key": top_pack.get("group_key"),
            "headline": (regression_guard or {}).get("next_action"),
            "expected_upside": "Prevents weak-buy or missed-runner regressions from becoming future promotions.",
            "proof": "Clear or classify the active regression guard items.",
            "workbench_pack": top_pack or None,
            "next_action": (regression_guard or {}).get("next_action"),
        }
    if top_pack:
        evidence = dict(top_pack.get("evidence_bundle") or {})
        first_recipe = (top_pack.get("replay_test_recipe") or [{}])[0]
        first_target = (top_pack.get("target_code_map") or [{}])[0]
        return {
            "status": "ACTIVE" if top_pack.get("state") == "ACTIVE" else "READY",
            "mission_type": "EXECUTION_PACK",
            "title": f"{str(top_pack.get('risk_label') or 'PACK').replace('_', ' ')} mission",
            "priority_score": top_pack.get("priority_score"),
            "pack_key": top_pack.get("pack_key"),
            "group_key": top_pack.get("group_key"),
            "headline": top_pack.get("next_action"),
            "expected_upside": evidence.get("why_it_matters"),
            "proof": first_recipe.get("label") or "Run the replay recipe and completion criteria.",
            "target": {
                "subsystem": top_pack.get("target_subsystem"),
                "file": first_target.get("file"),
                "function": first_target.get("function"),
            },
            "workbench_pack": top_pack,
            "next_action": top_pack.get("next_action"),
        }
    if str((post_patch_tracker or {}).get("status") or "").upper() not in {"NO_COMPLETED_PATCHES", ""}:
        top = dict((post_patch_tracker or {}).get("top") or {})
        return {
            "status": "TRACKING",
            "mission_type": "POST_PATCH_TRACKING",
            "title": "Track shipped patch outcomes",
            "priority_score": 55,
            "pack_key": None,
            "group_key": top.get("group_key"),
            "headline": (post_patch_tracker or {}).get("next_action"),
            "expected_upside": "Confirms whether shipped patches actually improved the blocker loop.",
            "proof": "Wait for enough 24h/48h outcomes to classify improvement or regression.",
            "workbench_pack": None,
            "next_action": (post_patch_tracker or {}).get("next_action"),
        }
    if str((live_context_mission or {}).get("status") or "").upper() == "READY":
        mission = dict(live_context_mission or {})
        return {
            "status": "READY",
            "mission_type": mission.get("mission_type") or "LIVE_CONTEXT_MISSION",
            "title": mission.get("title") or "Live context mission",
            "priority_score": mission.get("priority_score"),
            "pack_key": None,
            "group_key": mission.get("group_key"),
            "headline": mission.get("headline"),
            "expected_upside": mission.get("expected_upside"),
            "proof": mission.get("proof") or (live_context_evidence or {}).get("next_action"),
            "target": mission.get("target"),
            "workbench_pack": None,
            "source_gap": mission.get("source_gap"),
            "evidence_requirements": live_context_evidence,
            "outcome_loop": live_context_outcome_loop,
            "next_action": mission.get("next_action"),
        }
    return {
        "status": "OBSERVE",
        "mission_type": "BUILD_FOCUS",
        "title": str((daily_build_score or {}).get("focus") or "OBSERVE").replace("_", " ").title(),
        "priority_score": daily_build_score.get("score"),
        "pack_key": None,
        "group_key": None,
        "headline": daily_build_score.get("next_action") or "Keep collecting outcomes.",
        "expected_upside": "Keeps the daily improvement loop pointed at the strongest available signal.",
        "proof": "Daily Brief remains locked and continues collecting fresh outcomes.",
        "workbench_pack": None,
        "next_action": daily_build_score.get("next_action"),
    }


def _build_rule_promotion_gate(
    simulator: dict,
    watchdog: dict,
    freshness_sla: dict,
    provider_reliability: dict | None = None,
    escalation_accuracy: dict | None = None,
    escalation_review_queue: dict | None = None,
) -> dict:
    top = dict((simulator or {}).get("top_candidate") or {})
    data_status = str((watchdog or {}).get("status") or "").upper()
    sla_status = str((freshness_sla or {}).get("status") or "").upper()
    score = _gb_float((freshness_sla or {}).get("score"))
    provider_hit_rate = _gb_float((provider_reliability or {}).get("repair_hit_rate_pct"), 100.0)
    escalation_sample = int((escalation_accuracy or {}).get("sample_n") or 0)
    escalation_accuracy_raw = (escalation_accuracy or {}).get("accuracy_pct")
    escalation_accuracy_pct = _gb_float(escalation_accuracy_raw, 100.0)
    escalation_missed = int((escalation_accuracy or {}).get("missed_n") or 0)
    frozen_failures = list((escalation_accuracy or {}).get("frozen_failure_classes") or [])
    frozen_lanes = list((escalation_accuracy or {}).get("frozen_lanes") or [])
    unresolved_reviews = int((escalation_review_queue or {}).get("unresolved_count") or 0)
    review_frozen_failures = list((escalation_review_queue or {}).get("frozen_failure_classes") or [])
    review_frozen_lanes = list((escalation_review_queue or {}).get("frozen_lanes") or [])
    active_frozen_failures = review_frozen_failures if escalation_review_queue is not None else frozen_failures
    active_frozen_lanes = review_frozen_lanes if escalation_review_queue is not None else frozen_lanes
    if not top:
        status = "NO_RULE"
        reason = "No simulator candidate has enough outcome evidence."
    elif unresolved_reviews > 0:
        status = "BLOCKED_ESCALATION_REVIEW"
        reason = "Unresolved escalation alert groups are frozen until reviewed."
    elif data_status in {"PATCH_QUEUE", "DEGRADED"} or sla_status == "DEGRADED" or score < 55:
        status = "BLOCKED_DATA"
        reason = "Provider freshness is not strong enough to promote a rule change."
    elif provider_hit_rate < 35 and int((provider_reliability or {}).get("attempts_24h") or 0) >= 8:
        status = "BLOCKED_PROVIDER_REPAIR"
        reason = "Provider repair hit rate is too weak to trust rule promotion."
    elif escalation_missed > 0 and escalation_review_queue is None:
        status = "BLOCKED_ESCALATION_MISS"
        reason = "A provider escalation blocker missed a runner; freeze this blocker class until reviewed."
    elif escalation_sample >= 5 and escalation_accuracy_pct < 70:
        status = "BLOCKED_ESCALATION_ACCURACY"
        reason = "Escalation backtests show missed runners or weak blocker correctness."
    elif int(top.get("net_score") or 0) < 8:
        status = "OBSERVE"
        reason = "Top rule edge is not large enough to promote."
    else:
        status = "READY_REVIEW"
        reason = "Data quality is acceptable; review the rule manually before coding."
    return {
        "status": status,
        "candidate": top or None,
        "reason": reason,
        "requirements": {
            "freshness_score_min": 55,
            "rule_net_score_min": 8,
            "provider_repair_hit_rate_min": 35,
            "data_status": data_status or "UNKNOWN",
            "freshness_sla_status": sla_status or "UNKNOWN",
            "provider_repair_hit_rate_pct": provider_hit_rate,
            "escalation_accuracy_pct": _nullable_float(escalation_accuracy_raw),
            "escalation_sample_n": escalation_sample,
            "escalation_review_unresolved_count": unresolved_reviews,
            "frozen_failure_classes": sorted(set(active_frozen_failures)),
            "frozen_lanes": sorted(set(active_frozen_lanes)),
        },
    }


def _build_missed_runner_clusters(journal_rows: list[dict]) -> dict:
    clusters: dict[str, dict] = {}
    for row in journal_rows:
        action = str(row.get("recommended_action") or "").upper()
        label = str(row.get("outcome_label") or "").upper()
        if action == "BUY" or label not in _BUY_DECISION_BULLISH_LABELS:
            continue
        snapshot = _decision_snapshot(row)
        primary = _primary_blocker_from_row(row, snapshot) or {}
        category = str(primary.get("category") or "unknown").lower()
        key = f"{category}:{str(primary.get('key') or 'unknown').lower()}"
        cluster = clusters.setdefault(key, {
            "key": key,
            "category": category,
            "label": primary.get("label") or key.replace("_", " "),
            "count": 0,
            "avg_max_return_pct": None,
            "total_return": 0.0,
            "examples": [],
        })
        cluster["count"] += 1
        cluster["total_return"] += _gb_float(row.get("max_return_pct"))
        if len(cluster["examples"]) < 4:
            cluster["examples"].append({
                "symbol": row.get("symbol"),
                "surface": row.get("source_surface"),
                "max_return_pct": _nullable_float(row.get("max_return_pct")),
                "decision_state": _decision_state_from_row(row, snapshot),
                "blocker": primary.get("label") or primary.get("key"),
            })
    out = []
    for cluster in clusters.values():
        count = max(1, int(cluster.get("count") or 0))
        cluster["avg_max_return_pct"] = round(_gb_float(cluster.get("total_return")) / count, 2)
        cluster.pop("total_return", None)
        out.append(cluster)
    out.sort(key=lambda x: (int(x.get("count") or 0), _gb_float(x.get("avg_max_return_pct"))), reverse=True)
    return {
        "status": "READY" if out else "NO_MISSED_RUNNERS",
        "clusters": out[:8],
        "top_cluster": out[0] if out else None,
    }


def _build_catalyst_context(kv_rows: dict[str, str], confluence_rows: list[dict], journal_rows: list[dict]) -> dict:
    narrative = {}
    try:
        narrative = json.loads(kv_rows.get("narrative_trending") or "{}")
    except Exception:
        narrative = {}
    cg_symbols = [str(x or "").upper() for x in list(narrative.get("cg_symbols") or [])[:12] if x]
    dex_symbols = [str(x or "").upper() for x in list(narrative.get("dex_symbols") or [])[:12] if x]
    journal_symbols = {
        str(row.get("symbol") or "").upper()
        for row in journal_rows
        if str(row.get("symbol") or "").strip()
    }
    overlaps = sorted((set(cg_symbols) | set(dex_symbols)) & journal_symbols)
    confluence = [
        {
            "symbol": row.get("token_symbol"),
            "mint": row.get("token_mint"),
            "type": row.get("confluence_type"),
            "score": _nullable_float(row.get("confluence_score")),
            "ts": row.get("ts_utc"),
        }
        for row in list(confluence_rows or [])[:8]
    ]
    status = "ACTIVE" if cg_symbols or dex_symbols or confluence else "NO_FEED"
    return {
        "status": status,
        "updated_at": narrative.get("updated_at"),
        "sources": {
            "coingecko_symbols": cg_symbols,
            "dexscreener_symbols": dex_symbols,
            "recent_confluence_count": len(confluence),
        },
        "decision_overlap_symbols": overlaps[:10],
        "recent_confluence": confluence,
        "next_action": "Use catalyst overlap as context, not as an execution trigger.",
    }


def _build_live_market_narrative_intake(kv_rows: dict[str, str], confluence_rows: list[dict]) -> dict:
    narrative = {}
    try:
        narrative = json.loads(kv_rows.get("narrative_trending") or "{}")
        if not isinstance(narrative, dict):
            narrative = {}
    except Exception:
        narrative = {}
    items: list[dict] = []
    seen: set[tuple[str, str]] = set()

    def _add_item(source: str, symbol: str | None, mint: str | None = None, **extra) -> None:
        symbol_u = str(symbol or "").strip().upper()
        mint_s = str(mint or "").strip()
        if not symbol_u and not mint_s:
            return
        key = (symbol_u, mint_s)
        if key in seen:
            return
        seen.add(key)
        items.append({
            "source": source,
            "symbol": symbol_u or None,
            "mint": mint_s or None,
            **extra,
        })

    for idx, item in enumerate(list(narrative.get("coingecko") or [])[:10]):
        if not isinstance(item, dict):
            continue
        _add_item(
            "coingecko",
            item.get("symbol"),
            None,
            name=item.get("name"),
            rank=item.get("rank"),
            heat_score=max(0.0, 65.0 - idx * 4.0),
            reason="CoinGecko global trending",
        )
    for idx, item in enumerate(list(narrative.get("dexscreener") or [])[:12]):
        if not isinstance(item, dict):
            continue
        boosts = _gb_float(item.get("boosts"))
        _add_item(
            "dexscreener",
            item.get("symbol"),
            item.get("mint"),
            name=item.get("name"),
            boosts=int(boosts or 0),
            heat_score=min(100.0, 72.0 + min(20.0, boosts / 5.0) - idx * 2.0),
            reason="DexScreener Solana boosted",
        )
    for idx, row in enumerate(list(confluence_rows or [])[:12]):
        _add_item(
            "confluence",
            row.get("token_symbol"),
            row.get("token_mint"),
            type=row.get("confluence_type"),
            heat_score=min(100.0, _gb_float(row.get("confluence_score"), 50.0) + 10.0),
            ts=row.get("ts_utc"),
            reason=f"{row.get('confluence_type') or 'confluence'} event",
        )

    items.sort(key=lambda x: _gb_float(x.get("heat_score")), reverse=True)
    hot_symbols = sorted({str(item.get("symbol") or "").upper() for item in items if item.get("symbol")})
    hot_mints = sorted({str(item.get("mint") or "") for item in items if item.get("mint")})
    updated_at = narrative.get("updated_at")
    return {
        "status": "ACTIVE" if items else "NO_FEED",
        "updated_at": updated_at,
        "source_counts": {
            "coingecko": len(list(narrative.get("coingecko") or [])),
            "dexscreener": len(list(narrative.get("dexscreener") or [])),
            "confluence": len(confluence_rows or []),
        },
        "hot_symbols": hot_symbols[:18],
        "hot_mints": hot_mints[:18],
        "items": items[:18],
        "next_action": (
            "Compare hot market context against Abrons coverage."
            if items
            else "Refresh narrative momentum and confluence feeds."
        ),
    }


def _live_context_mission_state_map(raw_value: str | None) -> dict[str, dict]:
    try:
        payload = json.loads(raw_value or "{}")
        if not isinstance(payload, dict):
            return {}
        out: dict[str, dict] = {}
        for key, value in payload.items():
            if isinstance(value, dict):
                out[str(key)] = dict(value)
        return out
    except Exception:
        return {}


def _live_context_mission_key(item_or_gap: dict) -> str:
    gap_type = str(item_or_gap.get("gap_type") or "MARKET_CONTEXT").upper()
    identity = str(item_or_gap.get("mint") or item_or_gap.get("symbol") or item_or_gap.get("source") or "unknown").strip()
    return f"{gap_type}:{identity}".upper()


def _classify_live_context_scope(item_or_gap: dict) -> dict:
    source = str(item_or_gap.get("source") or "").lower()
    symbol = str(item_or_gap.get("symbol") or "").strip().upper()
    mint = str(item_or_gap.get("mint") or "").strip()
    name = str(item_or_gap.get("name") or "").strip().lower()
    meme_terms = {"dog", "cat", "pepe", "inu", "bonk", "wif", "frog", "meme", "shib", "floki", "trencher"}
    sol_spot = {"SOL", "JUP", "JTO", "PYTH", "WIF", "BONK", "RAY", "ORCA", "HNT", "MOBILE", "IO", "DRIFT"}
    major_or_l1 = {
        "BTC", "ETH", "BNB", "XRP", "ADA", "DOGE", "TRX", "TON", "AVAX", "DOT", "MATIC", "POL",
        "BCH", "LTC", "ETC", "XMR", "ATOM", "NEAR", "APT", "SUI", "SEI", "ARB", "OP", "FIL",
        "ICP", "HBAR", "VET", "ALGO", "EGLD", "XTZ", "EOS", "IOTA", "KAS", "TAO", "ERG",
    }
    if mint:
        scope = "IN_SCOPE_SOLANA"
        reason = "Mint/address is present, so Abrons can attempt Solana-style coverage or explicit chain verification."
    elif source == "dexscreener":
        scope = "IN_SCOPE_SOLANA"
        reason = "DexScreener boosted context is treated as scanner-relevant unless later chain checks reject it."
    elif symbol in sol_spot:
        scope = "SPOT_ONLY"
        reason = "Symbol is Solana ecosystem context, but not automatically a memecoin execution target."
    elif symbol in major_or_l1:
        scope = "OUT_OF_SCOPE_L1"
        reason = "CoinGecko trend appears to be a standalone L1/major asset, not a memecoin scanner target."
    elif any(term in name or term in symbol.lower() for term in meme_terms):
        scope = "IN_SCOPE_MEME"
        reason = "Name/symbol has meme-like terms and deserves scanner coverage review."
    elif source == "coingecko":
        scope = "SPOT_ONLY"
        reason = "CoinGecko-only trend without a mint is broad market context until a tradable memecoin target exists."
    else:
        scope = "NEEDS_SOURCE"
        reason = "More source detail is needed before classifying this market item."
    return {
        "scope": scope,
        "reason": reason,
        "manual_only": True,
    }


def _build_live_context_mission_dossier(gap: dict, live_intake: dict, mission_states: dict) -> dict:
    if not gap:
        return {"status": "NO_DOSSIER", "next_action": "No live-context gap needs a dossier."}
    mission_key = _live_context_mission_key(gap)
    source_item = None
    for item in list((live_intake or {}).get("items") or []):
        if str(item.get("mint") or "") and str(item.get("mint") or "") == str(gap.get("mint") or ""):
            source_item = dict(item)
            break
        if str(item.get("symbol") or "").upper() and str(item.get("symbol") or "").upper() == str(gap.get("symbol") or "").upper():
            source_item = dict(item)
            break
    state_row = dict(mission_states.get(mission_key) or {})
    state = str(state_row.get("state") or "NEW").upper()
    if state not in _LIVE_CONTEXT_MISSION_STATES:
        state = "NEW"
    scope = _classify_live_context_scope({**(source_item or {}), **gap})
    return {
        "status": "READY",
        "mission_key": mission_key,
        "state": state,
        "state_updated_at": state_row.get("updated_at"),
        "operator_note": state_row.get("note"),
        "source": gap.get("source"),
        "symbol": gap.get("symbol"),
        "mint": gap.get("mint"),
        "name": (source_item or {}).get("name"),
        "gap_type": gap.get("gap_type"),
        "gap_score": gap.get("gap_score"),
        "heat_score": gap.get("heat_score"),
        "reason": gap.get("reason"),
        "source_item": source_item,
        "scope": scope,
        "next_action": (
            "Resolve this market mission as covered or ignored."
            if state == "INVESTIGATING"
            else "Mission resolved; feedback is applied to future gap detection."
            if state in {"RESOLVED_COVERED", "RESOLVED_IGNORED"}
            else "Classify whether this live market item belongs in Abrons coverage."
        ),
    }


def _build_live_context_blind_spot_resolution(dossier: dict) -> dict:
    if not dossier or dossier.get("status") == "NO_DOSSIER":
        return {"status": "NO_ACTION", "next_action": "No blind spot requires resolution."}
    state = str(dossier.get("state") or "NEW").upper()
    scope = str(((dossier.get("scope") or {}).get("scope")) or "NEEDS_SOURCE").upper()
    if state == "RESOLVED_IGNORED":
        status = "IGNORED"
        action = "Do not generate future missions for this item unless the source identity changes."
    elif state == "RESOLVED_COVERED":
        status = "COVERED"
        action = "Keep this item in normal coverage and let outcomes decide whether it mattered."
    elif scope in {"OUT_OF_SCOPE_L1", "SPOT_ONLY", "IGNORE_NO_ACTION"}:
        status = "RECOMMEND_IGNORE"
        action = "Mark ignored if this is not a memecoin/Solana coverage target."
    elif scope == "NEEDS_SOURCE":
        status = "NEEDS_SOURCE"
        action = "Request more source identity before adding scanner coverage."
    else:
        status = "RECOMMEND_COVERAGE"
        action = "Create or verify token intelligence/watch coverage, then mark covered."
    return {
        "status": status,
        "mission_key": dossier.get("mission_key"),
        "scope": scope,
        "recommended_state": (
            "RESOLVED_IGNORED" if status == "RECOMMEND_IGNORE"
            else "NEEDS_SOURCE" if status == "NEEDS_SOURCE"
            else "RESOLVED_COVERED" if status == "RECOMMEND_COVERAGE"
            else state
        ),
        "action": action,
        "next_action": action,
    }


def _build_live_opportunity_gap_detector(
    live_intake: dict,
    intelligence_rows: list[dict],
    journal_rows: list[dict],
    mission_states: dict | None = None,
) -> dict:
    by_symbol: dict[str, dict] = {}
    by_mint: dict[str, dict] = {}
    for row in intelligence_rows or []:
        symbol = str(row.get("symbol") or "").strip().upper()
        mint = str(row.get("mint") or "").strip()
        if symbol and symbol not in by_symbol:
            by_symbol[symbol] = dict(row)
        if mint and mint not in by_mint:
            by_mint[mint] = dict(row)
    journal_symbols = {
        str(row.get("symbol") or "").strip().upper()
        for row in journal_rows or []
        if str(row.get("symbol") or "").strip()
    }
    journal_mints = {
        str(row.get("mint") or "").strip()
        for row in journal_rows or []
        if str(row.get("mint") or "").strip()
    }
    gaps = []
    for item in list((live_intake or {}).get("items") or []):
        symbol = str(item.get("symbol") or "").strip().upper()
        mint = str(item.get("mint") or "").strip()
        row = by_mint.get(mint) if mint else None
        if row is None and symbol:
            row = by_symbol.get(symbol)
        seen_decision = bool((mint and mint in journal_mints) or (symbol and symbol in journal_symbols))
        freshness = str((row or {}).get("data_freshness") or "").upper()
        confidence = str((row or {}).get("data_confidence") or "").upper()
        quality = _gb_float((row or {}).get("quality_score"))
        pressure = _gb_float((row or {}).get("pressure_score"))
        gap_type = None
        reason = None
        if not row:
            gap_type = "BLIND_SPOT"
            reason = "Hot market item has no current token intelligence row."
        elif freshness == "STALE":
            gap_type = "STALE_COVERAGE"
            reason = "Hot market item is known, but market data is stale."
        elif confidence == "LOW":
            gap_type = "LOW_CONFIDENCE"
            reason = "Hot market item is known, but confidence is low."
        elif not seen_decision:
            gap_type = "NO_DECISION_SURFACE"
            reason = "Hot market item has not surfaced in recent decisions."
        elif quality < 45 and pressure >= 60:
            gap_type = "QUALITY_PRESSURE_MISMATCH"
            reason = "Pressure is elevated, but quality scoring is suppressing context."
        if not gap_type:
            continue
        heat = _gb_float(item.get("heat_score"))
        score = heat
        if gap_type == "BLIND_SPOT":
            score += 28.0
        elif gap_type == "STALE_COVERAGE":
            score += 22.0
        elif gap_type == "NO_DECISION_SURFACE":
            score += 16.0
        elif gap_type == "LOW_CONFIDENCE":
            score += 14.0
        if str(item.get("source") or "") == "dexscreener":
            score += 8.0
        if str(item.get("source") or "") == "confluence":
            score += 10.0
        candidate_gap = {
            "gap_type": gap_type,
            "symbol": symbol or None,
            "mint": mint or None,
            "source": item.get("source"),
        }
        mission_key = _live_context_mission_key(candidate_gap)
        state_row = dict((mission_states or {}).get(mission_key) or {})
        state = str(state_row.get("state") or "NEW").upper()
        if state in {"RESOLVED_IGNORED", "RESOLVED_COVERED"}:
            continue
        scope = _classify_live_context_scope({**item, **candidate_gap})
        gaps.append({
            "gap_key": mission_key,
            "gap_type": gap_type,
            "symbol": symbol or None,
            "mint": mint or None,
            "source": item.get("source"),
            "mission_state": state if state in _LIVE_CONTEXT_MISSION_STATES else "NEW",
            "mission_state_updated_at": state_row.get("updated_at"),
            "scope": scope.get("scope"),
            "scope_reason": scope.get("reason"),
            "heat_score": _nullable_float(heat),
            "gap_score": round(min(100.0, score), 1),
            "data_freshness": freshness or None,
            "data_confidence": confidence or None,
            "quality_score": _nullable_float(quality),
            "pressure_score": _nullable_float(pressure),
            "seen_decision": seen_decision,
            "reason": reason,
        })
    gaps.sort(key=lambda x: _gb_float(x.get("gap_score")), reverse=True)
    by_type: dict[str, int] = {}
    for gap in gaps:
        key = str(gap.get("gap_type") or "UNKNOWN")
        by_type[key] = by_type.get(key, 0) + 1
    return {
        "status": "GAPS_FOUND" if gaps else "ALIGNED" if (live_intake or {}).get("items") else "NO_FEED",
        "gap_count": len(gaps),
        "by_type": by_type,
        "top_gap": gaps[0] if gaps else None,
        "items": gaps[:12],
        "next_action": (
            "Generate a build mission from the top market coverage gap."
            if gaps
            else "Market context is aligned with current Abrons coverage."
            if (live_intake or {}).get("items")
            else "Refresh market/narrative intake before generating a mission."
        ),
    }


def _build_live_context_generated_mission(opportunity_gaps: dict, live_intake: dict) -> dict:
    gap = dict((opportunity_gaps or {}).get("top_gap") or {})
    if not gap:
        return {
            "status": "NO_MISSION",
            "mission_type": "LIVE_CONTEXT_OBSERVE",
            "title": "Market context aligned",
            "priority_score": 0,
            "headline": (opportunity_gaps or {}).get("next_action") or (live_intake or {}).get("next_action"),
            "expected_upside": "Keep watching live context until a coverage gap appears.",
            "next_action": (opportunity_gaps or {}).get("next_action") or "Keep observing market context.",
        }
    gap_type = str(gap.get("gap_type") or "").upper()
    if gap_type in {"BLIND_SPOT", "NO_DECISION_SURFACE"}:
        mission_type = "SCANNER_COVERAGE"
        target_subsystem = "market/narrative scanner coverage"
        title = "Add hot-context coverage"
        proof = "Show the hot token or sector appears in token intelligence and a read-only decision surface."
    elif gap_type in {"STALE_COVERAGE", "LOW_CONFIDENCE"}:
        mission_type = "DATA_REPAIR"
        target_subsystem = "token intelligence provider repair"
        title = "Repair hot-context data coverage"
        proof = "Refresh this hot item to LIVE/RECENT with non-low confidence before trusting decisions."
    else:
        mission_type = "RULE_REPLAY"
        target_subsystem = "memecoin decision replay"
        title = "Replay hot-context suppression"
        proof = "Replay recent decisions and prove quality-pressure mismatch is not hiding runners."
    symbol = gap.get("symbol") or "hot market item"
    return {
        "status": "READY",
        "mission_type": mission_type,
        "title": title,
        "priority_score": gap.get("gap_score"),
        "gap_key": gap.get("gap_key"),
        "group_key": gap.get("gap_key"),
        "headline": f"{symbol}: {str(gap_type).replace('_', ' ').lower()} from {gap.get('source') or 'live context'}.",
        "expected_upside": gap.get("reason"),
        "proof": proof,
        "target": {
            "subsystem": target_subsystem,
            "file": "utils/narrative_momentum.py" if mission_type == "SCANNER_COVERAGE" else "utils/token_intelligence.py" if mission_type == "DATA_REPAIR" else "dashboard/backend/routers/home.py",
            "function": "narrative/context intake" if mission_type == "SCANNER_COVERAGE" else "token_intelligence_step" if mission_type == "DATA_REPAIR" else "_build_daily_crypto_brief",
        },
        "source_gap": gap,
        "next_action": "Use this generated mission as the next manual build target if no execution pack is active.",
    }


def _build_live_context_evidence_requirements(generated_mission: dict) -> dict:
    mission_type = str((generated_mission or {}).get("mission_type") or "").upper()
    if mission_type == "SCANNER_COVERAGE":
        requirements = [
            "Narrative/Dex/Confluence source shows the hot token or sector.",
            "Abrons token intelligence has a current row or explicit watch record for it.",
            "Home/Daily Brief displays the gap without creating a buy signal.",
            "No live execution setting changes.",
        ]
    elif mission_type == "DATA_REPAIR":
        requirements = [
            "Provider refresh moves the target from stale/low confidence to LIVE or RECENT.",
            "Market cap/liquidity/volume fields are non-zero when a valid pair exists.",
            "Provider failure reason remains auditable if repair fails.",
            "No automatic buy or rule promotion follows the repair.",
        ]
    elif mission_type == "RULE_REPLAY":
        requirements = [
            "Replay identifies whether suppression protected or missed a runner.",
            "Weak-buy risk does not exceed expected missed-runner benefit.",
            "Daily Brief can explain the blocker and the replay result.",
            "Rule change remains manual-gated.",
        ]
    else:
        requirements = [
            "Wait for a live market gap or execution pack.",
            "Keep the execution lock unchanged.",
        ]
    return {
        "status": "READY" if mission_type not in {"", "LIVE_CONTEXT_OBSERVE"} else "OBSERVE",
        "mission_type": mission_type or "LIVE_CONTEXT_OBSERVE",
        "requirements": requirements,
        "pass_count": 0,
        "required_count": len(requirements),
        "next_action": requirements[0] if requirements else "Keep observing.",
    }


def _build_live_context_outcome_loop(opportunity_gaps: dict, generated_mission: dict, journal_rows: list[dict], intelligence_rows: list[dict]) -> dict:
    gap = dict((generated_mission or {}).get("source_gap") or (opportunity_gaps or {}).get("top_gap") or {})
    symbol = str(gap.get("symbol") or "").upper()
    mint = str(gap.get("mint") or "")
    if not gap:
        return {
            "status": "NO_ACTIVE_MISSION",
            "coverage_gap_count": int((opportunity_gaps or {}).get("gap_count") or 0),
            "next_action": "Outcome loop starts when a live-context mission exists.",
        }
    seen_decisions = [
        row for row in journal_rows or []
        if (symbol and str(row.get("symbol") or "").upper() == symbol)
        or (mint and str(row.get("mint") or "") == mint)
    ]
    intel_rows = [
        row for row in intelligence_rows or []
        if (symbol and str(row.get("symbol") or "").upper() == symbol)
        or (mint and str(row.get("mint") or "") == mint)
    ]
    freshest = intel_rows[0] if intel_rows else {}
    freshness = str(freshest.get("data_freshness") or "").upper()
    confidence = str(freshest.get("data_confidence") or "").upper()
    resolved = bool(freshest and freshness in {"LIVE", "RECENT"} and confidence != "LOW")
    surfaced = bool(seen_decisions)
    status = "IMPROVING" if resolved and surfaced else "COVERAGE_REPAIRED" if resolved else "SURFACED" if surfaced else "TRACKING"
    return {
        "status": status,
        "gap_key": gap.get("gap_key"),
        "symbol": symbol or None,
        "mint": mint or None,
        "coverage_gap_count": int((opportunity_gaps or {}).get("gap_count") or 0),
        "decision_surface_count": len(seen_decisions),
        "freshness": freshness or None,
        "confidence": confidence or None,
        "resolved": resolved,
        "surfaced": surfaced,
        "next_action": (
            "Live-context mission improved coverage; keep watching outcomes."
            if status == "IMPROVING"
            else "Repair data coverage before judging this market gap."
            if not resolved
            else "Get this repaired context onto a read-only decision surface."
        ),
    }


def _live_context_mission_outcome_journal(raw_value: str | None) -> list[dict]:
    try:
        payload = json.loads(raw_value or "[]")
        if not isinstance(payload, list):
            return []
        return [dict(item) for item in payload if isinstance(item, dict)]
    except Exception:
        return []


def _latest_live_context_mission_events(rows: list[dict]) -> dict[str, dict]:
    latest: dict[str, dict] = {}
    for row in rows or []:
        key = str(row.get("mission_key") or row.get("gap_key") or "").strip().upper()
        if not key:
            continue
        current = latest.get(key)
        current_ts = _gb_parse_ts((current or {}).get("decision_at"))
        row_ts = _gb_parse_ts(row.get("decision_at"))
        if current is None or (row_ts and (not current_ts or row_ts >= current_ts)):
            latest[key] = dict(row)
    return latest


def _live_context_current_item_map(live_intake: dict) -> dict[str, dict]:
    out: dict[str, dict] = {}
    for item in list((live_intake or {}).get("items") or []):
        item_dict = dict(item)
        symbol = str(item_dict.get("symbol") or "").strip().upper()
        mint = str(item_dict.get("mint") or "").strip()
        gap_type = "BLIND_SPOT" if not mint else "MARKET_CONTEXT"
        for key in {
            _live_context_mission_key({**item_dict, "gap_type": gap_type}),
            f"BLIND_SPOT:{symbol}".upper() if symbol else "",
            f"MARKET_CONTEXT:{mint}".upper() if mint else "",
            f"MARKET_CONTEXT:{symbol}".upper() if symbol else "",
        }:
            if key:
                out[key] = item_dict
    return out


def _live_context_decision_matches(event: dict, rows: list[dict]) -> list[dict]:
    symbol = str(event.get("symbol") or "").strip().upper()
    mint = str(event.get("mint") or "").strip()
    return [
        dict(row) for row in rows or []
        if (symbol and str(row.get("symbol") or "").strip().upper() == symbol)
        or (mint and str(row.get("mint") or "").strip() == mint)
    ]


def _classify_live_context_mission_outcome(
    event: dict,
    live_item: dict | None,
    decision_rows: list[dict],
    intelligence_rows: list[dict],
    now: datetime,
) -> dict:
    state = str(event.get("state") or "").upper()
    scope = str(event.get("scope") or "").upper()
    symbol = str(event.get("symbol") or "").strip().upper()
    mint = str(event.get("mint") or "").strip()
    heat = _gb_float((live_item or {}).get("heat_score"))
    source = str((live_item or {}).get("source") or event.get("source") or "").lower()
    matched_decisions = _live_context_decision_matches(event, decision_rows)
    matched_intel = _live_context_decision_matches(event, intelligence_rows)
    bullish_labels = {"BIG_RUNNER", "GOOD_RUNNER", "GOOD_BUY"}
    bullish_rows = [
        row for row in matched_decisions
        if str(row.get("outcome_label") or "").upper() in bullish_labels
        or _gb_float(row.get("max_return_pct")) >= 25.0
    ]
    fresh_intel = [
        row for row in matched_intel
        if str(row.get("data_freshness") or "").upper() in {"LIVE", "RECENT"}
        and str(row.get("data_confidence") or "").upper() != "LOW"
    ]
    decision_age_hours = None
    decision_ts = _gb_parse_ts(event.get("decision_at"))
    if decision_ts:
        decision_age_hours = round(max(0.0, (now - decision_ts).total_seconds() / 3600.0), 2)

    if state == "RESOLVED_IGNORED":
        if bullish_rows:
            label = "FALSE_IGNORE"
            correctness = "MISS"
            reason = "Ignored mission later matched bullish decision/outcome evidence."
        elif scope in {"OUT_OF_SCOPE_L1", "SPOT_ONLY"} and not mint:
            label = "GOOD_IGNORE"
            correctness = "CORRECT"
            reason = "Ignored item is broad market/spot context without a tradable memecoin identity."
        elif heat >= 80.0 or source == "dexscreener" or mint:
            label = "IGNORED_HOT_REVIEW"
            correctness = "REVIEW"
            reason = "Ignored item still has hot or tradable context and deserves one more review."
        else:
            label = "PENDING_REVIEW"
            correctness = "PENDING"
            reason = "Waiting for later market evidence to confirm the ignore."
    elif state == "RESOLVED_COVERED":
        if fresh_intel or matched_decisions:
            label = "COVERED_CONFIRMED"
            correctness = "CORRECT"
            reason = "Covered mission has current intelligence or decision-surface evidence."
        else:
            label = "COVER_STILL_MISSING"
            correctness = "REVIEW"
            reason = "Mission was marked covered, but coverage evidence is not visible yet."
    elif state == "NEEDS_SOURCE":
        if mint or (live_item or {}).get("mint") or source == "dexscreener":
            label = "SOURCE_RESOLVED"
            correctness = "CORRECT"
            reason = "Source identity is now specific enough to classify coverage."
        else:
            label = "SOURCE_PENDING"
            correctness = "PENDING"
            reason = "Still waiting for a tradable source identity."
    elif state == "INVESTIGATING":
        label = "INVESTIGATION_OPEN"
        correctness = "PENDING"
        reason = "Operator investigation is still open."
    else:
        label = "PENDING_REVIEW"
        correctness = "PENDING"
        reason = "Mission has not been resolved yet."

    return {
        "outcome_label": label,
        "correctness": correctness,
        "reason": reason,
        "decision_age_hours": decision_age_hours,
        "live_heat_score": _nullable_float(heat),
        "live_source": source or None,
        "matched_decisions": len(matched_decisions),
        "matched_intelligence_rows": len(matched_intel),
        "bullish_match_count": len(bullish_rows),
        "fresh_coverage_count": len(fresh_intel),
        "symbol": symbol or None,
        "mint": mint or None,
    }


def _build_live_context_mission_outcome_journal(
    raw_journal: list[dict],
    live_intake: dict,
    decision_rows: list[dict],
    intelligence_rows: list[dict],
    now: datetime,
) -> dict:
    latest = _latest_live_context_mission_events(raw_journal)
    item_map = _live_context_current_item_map(live_intake)
    items = []
    counts: dict[str, int] = {}
    correctness_counts: dict[str, int] = {}
    for key, event in latest.items():
        live_item = item_map.get(key)
        outcome = _classify_live_context_mission_outcome(event, live_item, decision_rows, intelligence_rows, now)
        label = str(outcome.get("outcome_label") or "PENDING_REVIEW").upper()
        correctness = str(outcome.get("correctness") or "PENDING").upper()
        counts[label] = counts.get(label, 0) + 1
        correctness_counts[correctness] = correctness_counts.get(correctness, 0) + 1
        items.append({
            "mission_key": key,
            "state": event.get("state"),
            "scope": event.get("scope"),
            "symbol": event.get("symbol"),
            "mint": event.get("mint"),
            "gap_type": event.get("gap_type"),
            "decision_at": event.get("decision_at"),
            "operator_note": event.get("operator_note") or event.get("note"),
            **outcome,
        })
    items.sort(key=lambda row: (_gb_parse_ts(row.get("decision_at")) or datetime.min.replace(tzinfo=timezone.utc)), reverse=True)
    return {
        "status": "ACTIVE" if items else "EMPTY",
        "event_count": len(raw_journal or []),
        "mission_count": len(items),
        "outcome_counts": counts,
        "correctness_counts": correctness_counts,
        "items": items[:40],
        "next_action": (
            "Use review queue outcomes to score whether mission decisions were right."
            if items
            else "Resolve a live market mission to start the outcome journal."
        ),
    }


def _build_live_context_review_queue(mission_journal: dict, current_gaps: dict, dossier: dict) -> dict:
    queue = []
    for item in list((mission_journal or {}).get("items") or []):
        label = str(item.get("outcome_label") or "").upper()
        state = str(item.get("state") or "").upper()
        priority = 0.0
        reason = None
        if label == "FALSE_IGNORE":
            priority = 100.0
            reason = "Ignored item later matched bullish outcome evidence."
        elif label == "COVER_STILL_MISSING":
            priority = 88.0
            reason = "Covered mission still lacks visible coverage evidence."
        elif label == "IGNORED_HOT_REVIEW":
            priority = 82.0
            reason = "Ignored item remains hot/tradable enough to re-check."
        elif label == "SOURCE_PENDING":
            priority = 68.0
            reason = "Source-needed mission still lacks tradable identity."
        elif state in {"NEW", "INVESTIGATING", "NEEDS_SOURCE"}:
            priority = 60.0
            reason = "Mission still needs an operator resolution."
        if priority:
            queue.append({**item, "priority_score": priority, "review_reason": reason})
    top_gap = dict((current_gaps or {}).get("top_gap") or {})
    if top_gap:
        queue.append({
            "mission_key": top_gap.get("gap_key"),
            "state": top_gap.get("mission_state") or "NEW",
            "scope": top_gap.get("scope"),
            "symbol": top_gap.get("symbol"),
            "mint": top_gap.get("mint"),
            "gap_type": top_gap.get("gap_type"),
            "outcome_label": "PENDING_REVIEW",
            "correctness": "PENDING",
            "priority_score": _gb_float(top_gap.get("gap_score")),
            "review_reason": top_gap.get("reason") or "Current top live opportunity gap needs resolution.",
        })
    if (dossier or {}).get("mission_key") and not any(q.get("mission_key") == dossier.get("mission_key") for q in queue):
        state = str((dossier or {}).get("state") or "NEW").upper()
        if state in {"NEW", "INVESTIGATING", "NEEDS_SOURCE"}:
            queue.append({
                "mission_key": dossier.get("mission_key"),
                "state": state,
                "scope": ((dossier or {}).get("scope") or {}).get("scope"),
                "symbol": dossier.get("symbol"),
                "mint": dossier.get("mint"),
                "gap_type": dossier.get("gap_type"),
                "outcome_label": "PENDING_REVIEW",
                "correctness": "PENDING",
                "priority_score": _gb_float((dossier or {}).get("gap_score"), 55.0),
                "review_reason": (dossier or {}).get("next_action"),
            })
    dedup: dict[str, dict] = {}
    for item in queue:
        key = str(item.get("mission_key") or "").upper()
        if not key:
            continue
        current = dedup.get(key)
        if current is None or _gb_float(item.get("priority_score")) > _gb_float(current.get("priority_score")):
            dedup[key] = item
    items = sorted(dedup.values(), key=lambda row: _gb_float(row.get("priority_score")), reverse=True)
    return {
        "status": "REVIEW_NEEDED" if items else "CLEAR",
        "open_count": len(items),
        "top_item": items[0] if items else None,
        "items": items[:12],
        "next_action": (
            "Work the top mission review before adding new market coverage."
            if items
            else "No mission decisions need review right now."
        ),
    }


def _build_live_context_decision_accuracy(mission_journal: dict) -> dict:
    items = list((mission_journal or {}).get("items") or [])
    correct = [item for item in items if str(item.get("correctness") or "").upper() == "CORRECT"]
    miss = [item for item in items if str(item.get("correctness") or "").upper() == "MISS"]
    review = [item for item in items if str(item.get("correctness") or "").upper() == "REVIEW"]
    pending = [item for item in items if str(item.get("correctness") or "").upper() == "PENDING"]
    scored = len(correct) + len(miss)
    accuracy = round((len(correct) / max(1, scored)) * 100.0, 1) if scored else None
    status = "LEARNING" if scored < 5 else "NEEDS_REVIEW" if miss or (accuracy is not None and accuracy < 75.0) else "HEALTHY"
    return {
        "status": status,
        "sample_n": scored,
        "correct_n": len(correct),
        "miss_n": len(miss),
        "review_n": len(review),
        "pending_n": len(pending),
        "accuracy_pct": accuracy,
        "top_miss": miss[0] if miss else None,
        "next_action": (
            "Collect at least five scored mission outcomes before trusting accuracy."
            if scored < 5
            else "Review false ignores before policy promotion."
            if miss
            else "Keep scoring mission decisions before changing policy."
        ),
    }


def _build_live_context_policy_suggestions(mission_journal: dict, accuracy: dict) -> dict:
    items = list((mission_journal or {}).get("items") or [])
    good_l1_ignores = [
        item for item in items
        if str(item.get("outcome_label") or "").upper() == "GOOD_IGNORE"
        and str(item.get("scope") or "").upper() in {"OUT_OF_SCOPE_L1", "SPOT_ONLY"}
    ]
    false_ignores = [item for item in items if str(item.get("outcome_label") or "").upper() == "FALSE_IGNORE"]
    cover_missing = [item for item in items if str(item.get("outcome_label") or "").upper() == "COVER_STILL_MISSING"]
    source_pending = [item for item in items if str(item.get("outcome_label") or "").upper() == "SOURCE_PENDING"]
    suggestions = []
    if false_ignores:
        suggestions.append({
            "policy_key": "NO_AUTO_IGNORE_HOT_TRADABLE",
            "confidence": "HIGH",
            "evidence_n": len(false_ignores),
            "suggestion": "Do not auto-ignore hot items with mints, DexScreener source, or later bullish evidence.",
            "manual_only": True,
        })
    if len(good_l1_ignores) >= 3 or (good_l1_ignores and not false_ignores):
        suggestions.append({
            "policy_key": "QUIET_OUT_OF_SCOPE_L1_HEAT",
            "confidence": "MEDIUM" if len(good_l1_ignores) < 3 else "HIGH",
            "evidence_n": len(good_l1_ignores),
            "suggestion": "Keep CoinGecko-only L1/spot heat out of memecoin coverage unless spot strategy explicitly requests it.",
            "manual_only": True,
        })
    if cover_missing:
        suggestions.append({
            "policy_key": "REQUIRE_VISIBLE_COVERAGE_PROOF",
            "confidence": "MEDIUM",
            "evidence_n": len(cover_missing),
            "suggestion": "A covered mission should show fresh token intelligence or a decision-surface row before it is treated as complete.",
            "manual_only": True,
        })
    if source_pending:
        suggestions.append({
            "policy_key": "SOURCE_NEEDED_EXPIRY",
            "confidence": "LOW",
            "evidence_n": len(source_pending),
            "suggestion": "Expire source-needed missions that never gain a mint or concrete tradable source.",
            "manual_only": True,
        })
    return {
        "status": "READY_REVIEW" if suggestions else "NO_POLICY_CHANGE",
        "suggestion_count": len(suggestions),
        "items": suggestions[:6],
        "accuracy_pct": (accuracy or {}).get("accuracy_pct"),
        "next_action": (
            "Review suggestions manually; none should auto-promote into execution."
            if suggestions
            else "Keep collecting mission outcomes before suggesting policy."
        ),
    }


def _build_live_context_mission_evidence_packet(
    review_queue: dict,
    mission_journal: dict,
    raw_journal: list[dict],
    live_intake: dict,
    intelligence_rows: list[dict],
    decision_rows: list[dict],
    dossier: dict,
) -> dict:
    top = dict((review_queue or {}).get("top_item") or {})
    if not top:
        return {
            "status": "NO_OPEN_REVIEW",
            "next_action": "No live mission review item needs an evidence packet.",
        }
    mission_key = str(top.get("mission_key") or "").strip().upper()
    item_map = _live_context_current_item_map(live_intake)
    live_item = item_map.get(mission_key)
    symbol = str(top.get("symbol") or (live_item or {}).get("symbol") or "").strip().upper()
    mint = str(top.get("mint") or (live_item or {}).get("mint") or "").strip()
    identity_event = {
        "symbol": symbol or None,
        "mint": mint or None,
    }
    matched_decisions = _live_context_decision_matches(identity_event, decision_rows)[:8]
    matched_intel = _live_context_decision_matches(identity_event, intelligence_rows)[:8]
    bullish_labels = {"BIG_RUNNER", "GOOD_RUNNER", "GOOD_BUY"}
    bullish = [
        row for row in matched_decisions
        if str(row.get("outcome_label") or "").upper() in bullish_labels
        or _gb_float(row.get("max_return_pct")) >= 25.0
    ][:5]
    fresh_coverage = [
        row for row in matched_intel
        if str(row.get("data_freshness") or "").upper() in {"LIVE", "RECENT"}
        and str(row.get("data_confidence") or "").upper() != "LOW"
    ][:5]
    history = [
        dict(row) for row in raw_journal or []
        if str(row.get("mission_key") or row.get("gap_key") or "").strip().upper() == mission_key
    ][:8]
    evidence_flags = []
    if live_item:
        evidence_flags.append("live_context_seen")
    if bullish:
        evidence_flags.append("bullish_outcome_match")
    if fresh_coverage:
        evidence_flags.append("fresh_coverage_visible")
    if matched_decisions:
        evidence_flags.append("decision_surface_seen")
    if matched_intel:
        evidence_flags.append("token_intelligence_seen")
    if not evidence_flags:
        evidence_flags.append("evidence_sparse")
    return {
        "status": "READY",
        "mission_key": mission_key,
        "symbol": symbol or None,
        "mint": mint or None,
        "state": top.get("state"),
        "scope": top.get("scope") or ((dossier or {}).get("scope") or {}).get("scope"),
        "outcome_label": top.get("outcome_label"),
        "correctness": top.get("correctness"),
        "priority_score": top.get("priority_score"),
        "review_reason": top.get("review_reason") or top.get("reason"),
        "source": (live_item or {}).get("source") or top.get("live_source") or (dossier or {}).get("source"),
        "heat_score": top.get("live_heat_score") if top.get("live_heat_score") is not None else (live_item or {}).get("heat_score"),
        "gap_type": top.get("gap_type") or (dossier or {}).get("gap_type"),
        "evidence_flags": evidence_flags,
        "source_item": live_item,
        "mission_history": history,
        "decision_matches": matched_decisions,
        "intelligence_matches": matched_intel,
        "bullish_matches": bullish,
        "fresh_coverage": fresh_coverage,
        "counts": {
            "history": len(history),
            "decision_matches": len(matched_decisions),
            "intelligence_matches": len(matched_intel),
            "bullish_matches": len(bullish),
            "fresh_coverage": len(fresh_coverage),
        },
        "next_action": "Use the recommended verdict only if this evidence packet matches the chart/read.",
    }


def _build_live_context_recommended_verdict(evidence_packet: dict, blind_spot_resolution: dict) -> dict:
    if not evidence_packet or evidence_packet.get("status") != "READY":
        return {
            "status": "NO_VERDICT",
            "recommended_state": None,
            "confidence": "NONE",
            "reason": "No open evidence packet.",
            "next_action": "Wait for an open mission review item.",
        }
    label = str(evidence_packet.get("outcome_label") or "").upper()
    scope = str(evidence_packet.get("scope") or "").upper()
    counts = dict(evidence_packet.get("counts") or {})
    bullish_n = int(counts.get("bullish_matches") or 0)
    fresh_n = int(counts.get("fresh_coverage") or 0)
    decision_n = int(counts.get("decision_matches") or 0)
    source = str(evidence_packet.get("source") or "").lower()
    mint = str(evidence_packet.get("mint") or "").strip()

    if label == "FALSE_IGNORE" or bullish_n:
        state = "INVESTIGATING"
        confidence = "HIGH"
        reason = "Ignored mission has bullish outcome evidence; reopen investigation before keeping it ignored."
    elif label == "COVER_STILL_MISSING":
        state = "NEEDS_SOURCE" if not fresh_n and not decision_n else "RESOLVED_COVERED"
        confidence = "MEDIUM"
        reason = "Coverage proof is missing; require source/coverage unless fresh evidence is now visible."
    elif label == "IGNORED_HOT_REVIEW":
        state = "INVESTIGATING"
        confidence = "MEDIUM"
        reason = "Ignored item still looks hot or tradable enough for another operator look."
    elif label == "SOURCE_PENDING":
        state = "NEEDS_SOURCE"
        confidence = "MEDIUM"
        reason = "Keep this source-gated until a mint or concrete tradable source appears."
    elif scope in {"OUT_OF_SCOPE_L1", "SPOT_ONLY"} and not mint and source != "dexscreener":
        state = "RESOLVED_IGNORED"
        confidence = "HIGH"
        reason = "Broad L1/spot context should stay out of memecoin coverage unless spot strategy asks for it."
    elif fresh_n or decision_n:
        state = "RESOLVED_COVERED"
        confidence = "HIGH" if fresh_n else "MEDIUM"
        reason = "Coverage or decision-surface proof is visible."
    elif str((blind_spot_resolution or {}).get("recommended_state") or "").upper() in _LIVE_CONTEXT_MISSION_STATES:
        state = str((blind_spot_resolution or {}).get("recommended_state") or "").upper()
        confidence = "LOW"
        reason = str((blind_spot_resolution or {}).get("action") or "Use scope classifier recommendation.")
    else:
        state = "INVESTIGATING"
        confidence = "LOW"
        reason = "Evidence is sparse; investigate before resolving."

    return {
        "status": "READY",
        "mission_key": evidence_packet.get("mission_key"),
        "recommended_state": state,
        "confidence": confidence,
        "reason": reason,
        "button_label": {
            "RESOLVED_IGNORED": "KEEP IGNORED",
            "RESOLVED_COVERED": "MARK COVERED",
            "NEEDS_SOURCE": "NEEDS SOURCE",
            "INVESTIGATING": "REOPEN",
        }.get(state, "APPLY"),
        "next_action": "Apply this verdict only after checking the evidence packet.",
    }


def _live_context_policy_window_counts(items: list[dict], now: datetime) -> dict:
    def _in_window(row: dict, hours: int) -> bool:
        ts = _gb_parse_ts(row.get("decision_at"))
        return bool(ts and ts >= now - timedelta(hours=hours))

    return {
        "24h": [item for item in items if _in_window(item, 24)],
        "7d": [item for item in items if _in_window(item, 24 * 7)],
    }


def _attach_live_context_policy_impact_preview(policy_suggestions: dict, mission_journal: dict, now: datetime) -> dict:
    suggestions = []
    items = list((mission_journal or {}).get("items") or [])
    windows = _live_context_policy_window_counts(items, now)
    for suggestion in list((policy_suggestions or {}).get("items") or []):
        key = str(suggestion.get("policy_key") or "").upper()
        preview = {}
        for label, rows in windows.items():
            if key == "QUIET_OUT_OF_SCOPE_L1_HEAT":
                affected = [
                    row for row in rows
                    if str(row.get("scope") or "").upper() in {"OUT_OF_SCOPE_L1", "SPOT_ONLY"}
                    and not row.get("mint")
                ]
                risk = [row for row in affected if str(row.get("outcome_label") or "").upper() == "FALSE_IGNORE"]
            elif key == "NO_AUTO_IGNORE_HOT_TRADABLE":
                affected = [
                    row for row in rows
                    if row.get("mint")
                    or str(row.get("live_source") or "").lower() == "dexscreener"
                    or _gb_float(row.get("live_heat_score")) >= 80.0
                ]
                risk = [row for row in affected if str(row.get("outcome_label") or "").upper() == "GOOD_IGNORE"]
            elif key == "REQUIRE_VISIBLE_COVERAGE_PROOF":
                affected = [row for row in rows if str(row.get("state") or "").upper() == "RESOLVED_COVERED"]
                risk = []
            elif key == "SOURCE_NEEDED_EXPIRY":
                affected = [row for row in rows if str(row.get("outcome_label") or "").upper() == "SOURCE_PENDING"]
                risk = []
            else:
                affected = []
                risk = []
            preview[label] = {
                "affected_count": len(affected),
                "risk_count": len(risk),
                "sample_symbols": [str(row.get("symbol") or row.get("mint") or row.get("mission_key") or "mission") for row in affected[:5]],
            }
        suggestions.append({**suggestion, "impact_preview": preview})
    return {
        **(policy_suggestions or {}),
        "items": suggestions,
        "impact_preview_status": "READY" if suggestions else "NO_POLICY_CHANGE",
    }


def _build_paper_to_pilot_gate(paper_rows: list[dict], lock_ok: bool, freshness_sla: dict, decision_quality: dict) -> dict:
    sample = len(paper_rows)
    wins = len([
        r for r in paper_rows
        if str(r.get("outcome_label") or "").upper() in {"BIG_RUNNER", "GOOD_RUNNER", "GOOD_BUY", "WIN", "PROFIT"}
        or _gb_float(r.get("return_4h_pct")) > 0
        or _gb_float(r.get("max_return_pct")) >= 5
    ])
    weak = len([
        r for r in paper_rows
        if str(r.get("outcome_label") or "").upper() in {"BAD_BUY", "WEAK_BUY", "LOSS"}
        or _gb_float(r.get("return_4h_pct")) <= -5
    ])
    avg_4h = _avg([_nullable_float(r.get("return_4h_pct")) for r in paper_rows])
    avg_max = _avg([_nullable_float(r.get("max_return_pct")) for r in paper_rows])
    win_rate = round((wins / max(1, sample)) * 100.0, 1) if sample else 0.0
    blockers = []
    if not lock_ok:
        blockers.append("execution_lock_review")
    if str((freshness_sla or {}).get("status") or "").upper() != "OK":
        blockers.append("freshness_sla_not_ok")
    if sample < 30:
        blockers.append("paper_sample_below_30")
    if win_rate < 45:
        blockers.append("paper_win_rate_below_45")
    if avg_4h is None or avg_4h < 0:
        blockers.append("paper_avg_4h_not_positive")
    if int((decision_quality or {}).get("missed_runner_count") or 0) > 3:
        blockers.append("missed_runner_count_high")
    status = "READY_FOR_DISCUSSION" if not blockers else "LOCKED" if not lock_ok else "NOT_READY"
    return {
        "status": status,
        "sample_n": sample,
        "win_rate_pct": win_rate,
        "weak_count": weak,
        "avg_4h_pct": avg_4h,
        "avg_max_return_pct": avg_max,
        "blockers": blockers,
        "note": "Read-only gate only; requires separate explicit re-arm discussion even if ready.",
    }


def _build_daily_build_score(
    lock_ok: bool,
    freshness_sla: dict,
    decision_quality: dict,
    watchdog: dict,
    rule_gate: dict,
    catalyst_context: dict,
    paper_gate: dict,
    escalation_queue: dict | None = None,
    escalation_accuracy: dict | None = None,
) -> dict:
    data_score = _gb_float((freshness_sla or {}).get("score"))
    rule_score = 70.0 if str((rule_gate or {}).get("status") or "") == "READY_REVIEW" else 45.0 if (rule_gate or {}).get("candidate") else 25.0
    research_score = 70.0 if str((catalyst_context or {}).get("status") or "") == "ACTIVE" else 35.0
    execution_score = 100.0 if lock_ok else 15.0
    paper_score = 75.0 if str((paper_gate or {}).get("status") or "") == "READY_FOR_DISCUSSION" else 45.0 if int((paper_gate or {}).get("sample_n") or 0) >= 20 else 25.0
    active_escalations = int((escalation_queue or {}).get("active_count") or 0)
    sla_breaches = int((escalation_queue or {}).get("sla_breached_count") or 0)
    escalation_score = max(10.0, 100.0 - (active_escalations * 8.0) - (sla_breaches * 20.0))
    escalation_sample = int((escalation_accuracy or {}).get("sample_n") or 0)
    escalation_missed = int((escalation_accuracy or {}).get("missed_n") or 0)
    if escalation_sample <= 0:
        escalation_accuracy_score = 50.0
    else:
        escalation_accuracy_score = max(10.0, min(100.0, _gb_float((escalation_accuracy or {}).get("accuracy_pct"), 50.0) + _gb_float((escalation_accuracy or {}).get("confidence_adjustment"))))
    components = {
        "data": round(data_score, 1),
        "rules": round(rule_score, 1),
        "research": round(research_score, 1),
        "escalations": round(escalation_score, 1),
        "escalation_accuracy": round(escalation_accuracy_score, 1),
        "execution_safety": round(execution_score, 1),
        "paper": round(paper_score, 1),
    }
    if str((watchdog or {}).get("status") or "").upper() in {"DEGRADED", "PATCH_QUEUE"} or data_score < 65:
        focus = "DATA"
    elif sla_breaches:
        focus = "ESCALATION_SLA"
    elif active_escalations:
        focus = "ESCALATIONS"
    elif escalation_missed:
        focus = "ESCALATION_ACCURACY"
    elif int((decision_quality or {}).get("missed_runner_count") or 0) > 3:
        focus = "MISSED_RUNNERS"
    elif str((rule_gate or {}).get("status") or "") == "READY_REVIEW":
        focus = "RULES"
    elif str((catalyst_context or {}).get("status") or "") != "ACTIVE":
        focus = "CATALYSTS"
    elif str((paper_gate or {}).get("status") or "") == "READY_FOR_DISCUSSION":
        focus = "PAPER_TO_PILOT_REVIEW"
    else:
        focus = "OBSERVE"
    overall = round(sum(components.values()) / max(1, len(components)), 1)
    return {
        "score": overall,
        "focus": focus,
        "components": components,
        "next_action": {
            "DATA": "Keep repairing stale provider coverage before rule changes.",
            "ESCALATION_SLA": "Clear breached provider escalations before new tuning work.",
            "ESCALATIONS": "Work the provider escalation queue before promoting candidates.",
            "ESCALATION_ACCURACY": "Review missed escalation outcomes before trusting provider blockers.",
            "MISSED_RUNNERS": "Cluster missed-runner blockers and promote scout timing fixes only after data is fresh.",
            "RULES": "Manually review the simulator candidate; do not auto-promote.",
            "CATALYSTS": "Refresh narrative and confluence context.",
            "PAPER_TO_PILOT_REVIEW": "Prepare a separate explicit re-arm discussion, not an automatic re-arm.",
            "OBSERVE": "Keep collecting outcomes.",
        }.get(focus, "Keep collecting outcomes."),
    }


def _build_daily_build_hooks(autopsy: dict, simulator: dict, watchdog: dict, lock_ok: bool, rule_gate: dict | None = None) -> dict:
    top_rule = (autopsy or {}).get("top_rule_to_review") or {}
    top_sim = (simulator or {}).get("top_candidate") or {}
    if not lock_ok:
        status = "LOCK_FIRST"
        next_patch = "Verify execution lock before any signal patch."
    elif str((watchdog or {}).get("status") or "").upper() in {"PATCH_QUEUE", "DEGRADED"}:
        status = "DATA_FIRST"
        next_patch = str((watchdog or {}).get("action") or "Patch data quality before rule changes.")
    elif str((rule_gate or {}).get("status") or "").upper() == "BLOCKED_DATA":
        status = "DATA_FIRST"
        next_patch = str((rule_gate or {}).get("reason") or "Patch data quality before rule changes.")
    elif top_rule:
        status = "RULE_REVIEW"
        next_patch = f"Review {top_rule.get('label') or top_rule.get('key')} with {top_rule.get('recommendation') or 'simulation'}."
    elif top_sim:
        status = "SIMULATE"
        next_patch = f"Replay {top_sim.get('label') or top_sim.get('key')} before coding another threshold."
    else:
        status = "OBSERVE"
        next_patch = "Keep collecting outcomes; no urgent daily patch."
    return {
        "status": status,
        "next_patch": next_patch,
        "safe_to_rearm_discussion": bool(lock_ok and status == "OBSERVE"),
        "automation_hooks": [
            "24h guarded soak audit",
            "daily crypto brief",
            "outcome autopsy",
            "rule impact simulator",
            "data quality watchdog",
            "provider repair automation",
            "freshness SLA",
            "paper-to-pilot gate",
        ],
    }


def _run_due_provider_escalation_outcome_checks(
    now: datetime | None = None,
    *,
    min_interval_s: int = _DAILY_BRIEF_OUTCOME_AUTORUN_MIN_SECONDS,
) -> dict:
    now = now or datetime.now(timezone.utc)
    now_iso = now.isoformat()
    meta_key = "provider_escalation_outcome_autorun"
    due_count = 0
    overdue_count = 0
    last_run_ts = None
    try:
        conn = _dj_conn()
        try:
            conn.execute("CREATE TABLE IF NOT EXISTS kv_store (key TEXT PRIMARY KEY, value TEXT)")
            exists = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='provider_repair_escalations'"
            ).fetchone()
            if not exists:
                return {
                    "status": "NO_ESCALATIONS",
                    "ran": False,
                    "checked_at": now_iso,
                    "due_count": 0,
                    "overdue_count": 0,
                }
            row = conn.execute(
                """
                SELECT
                    COUNT(*) AS due_count,
                    SUM(CASE WHEN next_outcome_check_ts <= ? THEN 1 ELSE 0 END) AS overdue_count
                FROM provider_repair_escalations
                WHERE escalation_status IN (
                    'REVIEW_COMPLETE_STILL_BLOCKED',
                    'SUPPRESSED',
                    'RESOLVED_REPAIRED'
                )
                  AND next_outcome_check_ts IS NOT NULL
                  AND next_outcome_check_ts <= ?
                """,
                ((now - timedelta(minutes=30)).isoformat(), now_iso),
            ).fetchone()
            due_count = int((row["due_count"] if row else 0) or 0)
            overdue_count = int((row["overdue_count"] if row else 0) or 0)
            meta_row = conn.execute("SELECT value FROM kv_store WHERE key=?", (meta_key,)).fetchone()
            if meta_row and meta_row[0]:
                meta = json.loads(str(meta_row[0]))
                if isinstance(meta, dict):
                    last_run_ts = meta.get("last_run_at")
        finally:
            conn.close()
    except Exception as exc:
        return {
            "status": "UNAVAILABLE",
            "ran": False,
            "checked_at": now_iso,
            "due_count": due_count,
            "overdue_count": overdue_count,
            "reason": str(exc)[:180],
        }

    if due_count <= 0:
        return {
            "status": "NOT_DUE",
            "ran": False,
            "checked_at": now_iso,
            "due_count": 0,
            "overdue_count": 0,
            "last_run_at": last_run_ts,
        }

    last_run = _gb_parse_ts(last_run_ts)
    if last_run and (now - last_run).total_seconds() < max(30, int(min_interval_s)):
        return {
            "status": "RECENTLY_CHECKED",
            "ran": False,
            "checked_at": now_iso,
            "due_count": due_count,
            "overdue_count": overdue_count,
            "last_run_at": last_run_ts,
        }

    started = {
        "status": "RUNNING",
        "last_run_at": now_iso,
        "due_count": due_count,
        "overdue_count": overdue_count,
    }
    try:
        conn = _dj_conn()
        try:
            conn.execute(
                "INSERT OR REPLACE INTO kv_store (key, value) VALUES (?, ?)",
                (meta_key, json.dumps(started, separators=(",", ":"))),
            )
            conn.commit()
        finally:
            conn.close()
    except Exception:
        pass

    try:
        from utils.token_intelligence import evaluate_provider_escalation_outcomes  # type: ignore

        result = evaluate_provider_escalation_outcomes(limit=120)
        status = "ALERTS" if int(result.get("alerts_emitted") or 0) else "CHECKED"
        payload = {
            "status": status,
            "ran": True,
            "checked_at": datetime.now(timezone.utc).isoformat(),
            "last_run_at": now_iso,
            "due_count": due_count,
            "overdue_count": overdue_count,
            "result": result,
        }
    except Exception as exc:
        payload = {
            "status": "ERROR",
            "ran": True,
            "checked_at": datetime.now(timezone.utc).isoformat(),
            "last_run_at": now_iso,
            "due_count": due_count,
            "overdue_count": overdue_count,
            "error": str(exc)[:220],
        }

    try:
        conn = _dj_conn()
        try:
            conn.execute(
                "INSERT OR REPLACE INTO kv_store (key, value) VALUES (?, ?)",
                (meta_key, json.dumps(payload, separators=(",", ":"))),
            )
            conn.commit()
        finally:
            conn.close()
    except Exception:
        pass
    return payload


def _build_daily_crypto_brief(lookback_hours: int = 24, outcome_autorun: dict | None = None) -> dict:
    """One read-only surface for the daily build loop."""
    lookback_hours = max(1, min(72, int(lookback_hours or 24)))
    now = datetime.now(timezone.utc)
    outcome_autorun = outcome_autorun or _run_due_provider_escalation_outcome_checks(now)
    since = now - timedelta(hours=lookback_hours)

    def _in_window(value) -> bool:
        ts = _gb_parse_ts(value)
        return bool(ts and ts >= since)

    def _avg_key(rows: list[dict], key: str) -> float | None:
        return _avg([_nullable_float(row.get(key)) for row in rows])

    def _row_age_min(row: dict) -> float | None:
        ts = _gb_parse_ts(row.get("updated_at"))
        if not ts:
            return None
        return round(max(0.0, (now - ts).total_seconds() / 60.0), 1)

    try:
        conn = _dj_conn()
        try:
            intelligence_rows = [
                dict(r) for r in conn.execute(
                    """
                    SELECT mint, symbol, updated_at, data_freshness, data_confidence,
                           market_source, quality_score, risk_score, pressure_score,
                           volume_24h_usd, liquidity, marketcap
                    FROM token_intelligence_current
                    WHERE mint IS NOT NULL AND TRIM(mint) != ''
                    ORDER BY updated_at DESC
                    LIMIT 600
                    """
                ).fetchall()
            ]
            journal_rows = [
                dict(r) for r in conn.execute(
                    """
                        SELECT id, created_ts, source_surface, symbol, mint, recommended_action,
                               priority, reason, blockers_json, snapshot_json, resolution_status,
                               outcome_label, outcome_1h_pct, outcome_4h_pct, outcome_24h_pct,
                               max_return_pct, max_drawdown_pct
                    FROM decision_journal
                    ORDER BY id DESC
                    LIMIT 1800
                    """
                ).fetchall()
            ]
            try:
                signal_outcome_rows = [
                    dict(r) for r in conn.execute(
                        """
                        SELECT scanned_at, symbol, mint, source, score, status,
                               return_1h_pct, return_4h_pct, return_24h_pct,
                               liquidity_usd, volume_24h, mcap_at_scan,
                               rug_label, token_age_days, heat_state_at_scan,
                               heat_score_at_scan
                        FROM memecoin_signal_outcomes
                        WHERE scanned_at >= ?
                        ORDER BY scanned_at DESC
                        LIMIT 3000
                        """,
                        ((now - timedelta(hours=max(lookback_hours, 24) + 24)).isoformat(),),
                    ).fetchall()
                ]
            except Exception:
                signal_outcome_rows = []
            paper_rows = [
                dict(r) for r in conn.execute(
                    """
                    SELECT entry_ts, symbol, status, outcome_label, return_1h_pct,
                           return_4h_pct, return_24h_pct, max_return_pct
                    FROM memecoin_entry_paper_trades
                    ORDER BY id DESC
                    LIMIT 1500
                    """
                ).fetchall()
            ]
            intent_rows = [
                dict(r) for r in conn.execute(
                    """
                    SELECT ts_utc, source, lane, action_type, mode, authority_verdict,
                           executed, execution_result
                    FROM execution_intents
                    ORDER BY id DESC
                    LIMIT 600
                    """
                ).fetchall()
            ]
            try:
                token_snapshot_rows = [
                    dict(r) for r in conn.execute(
                        """
                        SELECT ts_utc, data_freshness, data_confidence, market_source
                        FROM token_intelligence_snapshots
                        WHERE ts_utc >= ?
                        ORDER BY ts_utc DESC
                        LIMIT 3000
                        """,
                        (since.isoformat(),),
                    ).fetchall()
                ]
            except Exception:
                token_snapshot_rows = []
            try:
                repair_rows = [
                    dict(r) for r in conn.execute(
                        """
                        SELECT ts_utc, mint, symbol, previous_source, previous_freshness,
                               previous_confidence, previous_quality, previous_pressure,
                               repair_status, new_source, new_freshness, new_confidence,
                               new_quality, new_pressure, latency_ms, unresolved_count, reason,
                               failure_class, provider_path, repair_score, queue_flags_json
                        FROM token_provider_repair_events
                        WHERE ts_utc >= ?
                        ORDER BY id DESC
                        LIMIT 800
                        """,
                        (since.isoformat(),),
                    ).fetchall()
                ]
            except Exception:
                repair_rows = []
            try:
                escalation_rows = [
                    dict(r) for r in conn.execute(
                        """
                        SELECT id, created_ts, updated_ts, mint, symbol, failure_class,
                               repair_status, escalation_lane, escalation_status,
                               priority_score, queue_flags_json, provider_path, reason,
                               source_event_id, operator_decision, operator_note,
                               outcome_label, last_action_ts, sla_due_ts,
                               outcome_check_ts, outcome_status, outcome_source,
                               outcome_return_1h_pct, outcome_return_4h_pct,
                               outcome_return_24h_pct, outcome_max_return_pct,
                               outcome_max_drawdown_pct, blocker_correctness,
                               confidence_impact, outcome_reason,
                               outcome_1h_status, outcome_1h_check_ts, outcome_1h_correctness,
                               outcome_4h_status, outcome_4h_check_ts, outcome_4h_correctness,
                               outcome_24h_status, outcome_24h_check_ts, outcome_24h_correctness,
                               next_outcome_check_ts, next_outcome_horizon,
                               outcome_alert_kind, outcome_alert_ts
                        FROM provider_repair_escalations
                        WHERE created_ts >= ?
                           OR updated_ts >= ?
                           OR escalation_status IN ('QUEUED','WATCHING','FORCE_REFRESH_REQUESTED','STALE_REVIEW')
                        ORDER BY priority_score DESC, updated_ts DESC
                        LIMIT 500
                        """,
                        (since.isoformat(), since.isoformat()),
                    ).fetchall()
                ]
            except Exception:
                escalation_rows = []
            try:
                kv_rows = {
                    str(r["key"]): str(r["value"] or "")
                    for r in conn.execute(
                        "SELECT key, value FROM kv_store WHERE key IN ('narrative_trending','provider_escalation_outcome_alerts','provider_escalation_outcome_autorun','provider_escalation_review_states','provider_escalation_patch_states','provider_escalation_work_order_states','live_context_mission_states','live_context_mission_outcome_journal','replay_evidence_snapshot')"
                    ).fetchall()
                }
            except Exception:
                kv_rows = {}
            try:
                confluence_rows = [
                    dict(r) for r in conn.execute(
                        """
                        SELECT ts_utc, token_symbol, token_mint, confluence_type,
                               confluence_score, source_count, sources
                        FROM confluence_events
                        WHERE ts_utc >= ?
                        ORDER BY ts_utc DESC
                        LIMIT 80
                        """,
                        (since.isoformat(),),
                    ).fetchall()
                ]
            except Exception:
                confluence_rows = []
            open_trade_count = int(conn.execute(
                "SELECT COUNT(*) FROM memecoin_trades WHERE UPPER(COALESCE(status, ''))='OPEN'"
            ).fetchone()[0] or 0)
        finally:
            conn.close()
    except Exception as exc:
        return {
            "generated_at": now.isoformat(),
            "lookback_hours": lookback_hours,
            "status": "ERROR",
            "headline": f"Daily crypto brief unavailable: {exc}",
            "safety": {"execution_lock": "UNKNOWN", "open_memecoin_trades": None},
            "data_freshness": {},
            "decision_quality": {},
            "paper_pilot": {},
            "top_missed_runners": [],
            "weak_buy_calls": [],
            "top_paper_movers": [],
            "next_actions": ["Fix the daily brief data read before tuning rules."],
        }

    journal_24h = [r for r in journal_rows if _in_window(r.get("created_ts"))]
    paper_24h = [r for r in paper_rows if _in_window(r.get("entry_ts"))]
    intents_24h = [r for r in intent_rows if _in_window(r.get("ts_utc"))]

    freshness_counts: dict[str, int] = {}
    confidence_counts: dict[str, int] = {}
    for row in intelligence_rows:
        freshness_counts[str(row.get("data_freshness") or "UNKNOWN").upper()] = freshness_counts.get(str(row.get("data_freshness") or "UNKNOWN").upper(), 0) + 1
        confidence_counts[str(row.get("data_confidence") or "UNKNOWN").upper()] = confidence_counts.get(str(row.get("data_confidence") or "UNKNOWN").upper(), 0) + 1
    freshest = intelligence_rows[0] if intelligence_rows else {}
    stale_high_quality = [
        {
            "symbol": row.get("symbol"),
            "age_minutes": _row_age_min(row),
            "quality_score": row.get("quality_score"),
            "pressure_score": row.get("pressure_score"),
            "market_source": row.get("market_source"),
        }
        for row in intelligence_rows
        if str(row.get("data_freshness") or "").upper() == "STALE"
        and _gb_float(row.get("quality_score")) >= 75
    ][:8]

    outcome_counts: dict[str, int] = {}
    action_counts: dict[str, int] = {}
    surface_counts: dict[str, int] = {}
    for row in journal_24h:
        outcome_counts[str(row.get("outcome_label") or "PENDING").upper()] = outcome_counts.get(str(row.get("outcome_label") or "PENDING").upper(), 0) + 1
        action_counts[str(row.get("recommended_action") or "UNKNOWN").upper()] = action_counts.get(str(row.get("recommended_action") or "UNKNOWN").upper(), 0) + 1
        surface_counts[str(row.get("source_surface") or "UNKNOWN").upper()] = surface_counts.get(str(row.get("source_surface") or "UNKNOWN").upper(), 0) + 1

    bullish_labels = {"BIG_RUNNER", "GOOD_RUNNER", "GOOD_BUY"}
    weak_labels = {"BAD_BUY", "WEAK_BUY", "FLAT"}
    missed = []
    weak_buys = []
    for row in journal_24h:
        action = str(row.get("recommended_action") or "").upper()
        label = str(row.get("outcome_label") or "").upper()
        item = {
            "symbol": row.get("symbol"),
            "surface": row.get("source_surface"),
            "action": action,
            "priority": row.get("priority"),
            "outcome_label": label or None,
            "max_return_pct": _nullable_float(row.get("max_return_pct")),
            "reason": str(row.get("reason") or "")[:180],
        }
        if action != "BUY" and label in bullish_labels:
            missed.append(item)
        elif action == "BUY" and label in weak_labels:
            weak_buys.append(item)
    missed.sort(key=lambda x: _gb_float(x.get("max_return_pct")), reverse=True)
    weak_buys.sort(key=lambda x: _gb_float(x.get("max_return_pct")), reverse=True)

    paper_outcomes: dict[str, int] = {}
    paper_status: dict[str, int] = {}
    for row in paper_24h:
        paper_outcomes[str(row.get("outcome_label") or "PENDING").upper()] = paper_outcomes.get(str(row.get("outcome_label") or "PENDING").upper(), 0) + 1
        paper_status[str(row.get("status") or "UNKNOWN").upper()] = paper_status.get(str(row.get("status") or "UNKNOWN").upper(), 0) + 1
    paper_movers = [
        {
            "symbol": row.get("symbol"),
            "status": row.get("status"),
            "outcome_label": row.get("outcome_label"),
            "max_return_pct": _nullable_float(row.get("max_return_pct")),
            "return_1h_pct": _nullable_float(row.get("return_1h_pct")),
            "return_4h_pct": _nullable_float(row.get("return_4h_pct")),
            "return_24h_pct": _nullable_float(row.get("return_24h_pct")),
        }
        for row in paper_24h
    ]
    paper_movers.sort(key=lambda x: _gb_float(x.get("max_return_pct")), reverse=True)

    intent_modes: dict[str, int] = {}
    intent_verdicts: dict[str, int] = {}
